INSERT INTO "TJ_CONTENT"(CONTENT_ID,TONGJIAN_ID,REIGN_ID,VOLUME_ID,NUMBER,ORIGINAL,SIMPLIFIED,TRANSLATION,NOTES,TAGS,SOURCE_URL,CREATE_TIME)
SELECT * FROM (VALUES
(1,'8be19ea9-db0e-11ef-b00e-a0d3651f611f',1,1,1,'初命晉大夫魏斯、趙籍、韓虔爲諸侯。','初命晋大夫魏斯、赵籍、韩虔为诸侯。','周威烈王姬午首次册封晋国大夫魏斯、赵籍、韩虔为诸侯。','[{"type": "胡注", "text": "此溫公書法所由始也。魏之先，畢公高後，與周同姓；其苗裔曰畢萬，始封於魏。至魏舒，始爲晉正卿；三世至斯。趙之先，造父後；至叔帶，始自周適晉；至趙夙，始封於耿。至趙盾，始爲晉正卿；六世至籍。韓之先，出於周武王；至韓武子事晉，封於韓原。至韓厥，爲晉正卿；六世至虔。三家者，世爲晉大夫，於周則陪臣也。周室旣衰，晉主夏盟，以尊王室，故命之爲伯。三卿竊晉之權，暴蔑其君，剖分其國，此王法所必誅也。威烈王不惟不能誅之，又命之爲諸侯，是崇獎奸名犯分之臣也，通鑑始於此，其所以謹名分歟！", "textJt": "此温公书法所由始也。魏之先，毕公高后，与周同姓；其苗裔曰毕万，始封于魏。至魏舒，始为晋正卿；三世至斯。赵之先，造父后；至叔带，始自周适晋；至赵夙，始封于耿。至赵盾，始为晋正卿；六世至籍。韩之先，出于周武王；至韩武子事晋，封于韩原。至韩厥，为晋正卿；六世至虔。三家者，世为晋大夫，于周则陪臣也。周室既衰，晋主夏盟，以尊王室，故命之为伯。三卿窃晋之权，暴蔑其君，剖分其国，此王法所必诛也。威烈王不惟不能诛之，又命之为诸侯，是崇奖奸名犯分之臣也，通鉴始于此，其所以谨名分欤！"}]','人事,内政,三家分晋,魏斯,赵籍,韩虔,晋,大夫,諸侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(2,'8be19ed2-db0e-11ef-a31c-a0d3651f611f',1,1,2,'臣光曰：臣聞天子之職莫大於禮，禮莫大於分，分莫大於名。何謂禮？紀綱是也。何謂分？君、臣是也。何謂名？公、侯、卿、大夫是也。','臣光曰：臣闻天子之职莫大于礼，礼莫大于分，分莫大于名。何谓礼？纪纲是也。何谓分？君、臣是也。何谓名？公、侯、卿、大夫是也。','臣司马光说：我听说天子的职责中没有比礼更重大的，礼之中没有比君臣之分更重大的，君臣之分之中没有比名号更重大的。什么是礼？就是纲纪法度。什么是分？就是君与臣的分别。什么是名？就是公、侯、卿、大夫这些爵位名号。','[{"type": "胡注", "text": "分，扶問翻；下同。", "textJt": "分，扶问翻；下同。"}]','史论,光,公,侯,卿,大夫','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(3,'8be19ed5-db0e-11ef-bee1-a0d3651f611f',1,1,3,'夫以四海之廣，兆民之衆，受制於一人，雖有絕倫之力，高世之智，莫不奔走而服役者，豈非以禮爲之紀綱哉！是故天子統三公，三公率諸侯，諸侯制卿大夫，卿大夫治士庶人。貴以臨賤，賤以承貴。上之使下猶心腹之運手足，根本之制支葉，下之事上猶手足之衞心腹，支葉之庇本根，然後能上下相保而國家治安。故曰天子之職莫大於禮也。','夫以四海之广，兆民之众，受制于一人，虽有绝伦之力，高世之智，莫不奔走而服役者，岂非以礼为之纪纲哉！是故天子统三公，三公率诸侯，诸侯制卿大夫，卿大夫治士庶人。贵以临贱，贱以承贵。上之使下犹心腹之运手足，根本之制支叶，下之事上犹手足之衞心腹，支叶之庇本根，然后能上下相保而国家治安。故曰天子之职莫大于礼也。','四海如此广阔，兆民如此众多，却受制于一人，即使有绝伦的力量、高世的智慧，也没有不奔走服役的，难道不正是用礼制作为纲纪吗！因此天子统辖三公，三公率领诸侯，诸侯制约卿大夫，卿大夫治理士人与庶民。尊贵者凌驾于卑贱者之上，卑贱者侍奉尊贵者。在上者役使在下者，就像心腹调动手足、根本控制枝叶，在下者事奉在上者，就像手足保卫心腹、枝叶庇护本根，然后才能上下相互保全，国家长治久安。所以说，天子的职责没有比礼制更重大的。',NULL,'史论','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(4,'8be19ee2-db0e-11ef-9924-a0d3651f611f',1,1,4,'文王序易，以乾、坤爲首。孔子繫之曰：「天尊地卑，乾坤定矣。卑高以陳，貴賤位矣。」言君臣之位猶天地之不可易也。春秋抑諸侯，尊王室，王人雖微，序於諸侯之上，以是見聖人於君臣之際未嘗不惓惓也。非有桀、紂之暴，湯、武之仁，人歸之，天命之，君臣之分當守節伏死而已矣。是故以微子而代紂則成湯配天矣，以季札而君吳則太伯血食矣，然二子寧亡國而不爲者，誠以禮之大節不可亂也。故曰禮莫大於分也。','文王序易，以干、坤为首。孔子系之曰：「天尊地卑，乾坤定矣。卑高以陈，贵贱位矣。」言君臣之位犹天地之不可易也。春秋抑诸侯，尊王室，王人虽微，序于诸侯之上，以是见圣人于君臣之际未尝不惓惓也。非有桀、纣之暴，汤、武之仁，人归之，天命之，君臣之分当守节伏死而已矣。是故以微子而代纣则成汤配天矣，以季札而君吴则太伯血食矣，然二子宁亡国而不为者，诚以礼之大节不可乱也。故曰礼莫大于分也。','周文王序次《易》，把《乾》《坤》两卦放在首位。孔子系辞说：“天尊贵，地卑微，乾坤由此确定。卑下与高大按次序列出，贵贱也就有了定位。”这是说君臣之位如同天地一样不可改易。《春秋》贬抑诸侯，尊崇王室，周王室的臣属虽然卑微，仍排在诸侯之上，由此可见圣人对于君臣之间的关系，从来都念念不忘。除非有桀、纣那样的暴虐，汤、武那样的仁德，民众归附他们，上天授予他们天命；否则君臣的名分，就应当坚守节操，至死不渝。因此，如果让微子取代纣王，成汤开创的商朝就能与天相配；如果让季札做吴国君主，太伯也能永享祭祀。然而二人宁愿让国家灭亡也不肯这样做，实在是因为礼制的大节不可紊乱。所以说：礼没有比名分更重要的了。','[{"type": "胡注", "text": "惓，逵員翻。漢·劉向傳：忠臣畎畝，猶不忘君惓惓之義也。惓惓，猶言勤勤也。", "textJt": "惓，逵员翻。汉·刘向传：忠臣畎亩，犹不忘君惓惓之义也。惓惓，犹言勤勤也。"}, {"type": "胡注", "text": "史記：商帝乙生三子：長曰微子啓，次曰中衍，季曰紂。紂之母爲后。帝乙欲立啓爲太子，太史據法爭之曰：「有妻之子，不可立妾之子。」乃立紂。紂卒以暴虐亡殷國。孔鄭玄義曰：物之大者莫若於天；推父比天，與之相配，行孝之大，莫大於此；所謂「嚴父莫大於配天」也。又孔氏曰：禮記稱萬物本乎天，人本乎祖。俱爲其本，可以相配，故王者皆以祖配天。諡法：除殘去虐曰湯。然諡法起於周；蓋殷人先有此號，周人遂引以爲諡法。分，扶問翻。長，知兩翻。卒，子恤翻。", "textJt": "史记：商帝乙生三子：长曰微子启，次曰中衍，季曰纣。纣之母为后。帝乙欲立启为太子，太史据法争之曰：「有妻之子，不可立妾之子。」乃立纣。纣卒以暴虐亡殷国。孔郑玄义曰：物之大者莫若于天；推父比天，与之相配，行孝之大，莫大于此；所谓「严父莫大于配天」也。又孔氏曰：礼记称万物本乎天，人本乎祖。俱为其本，可以相配，故王者皆以祖配天。谥法：除残去虐曰汤。然谥法起于周；盖殷人先有此号，周人遂引以为谥法。分，扶问翻。长，知两翻。卒，子恤翻。"}, {"type": "胡注", "text": "吳王壽夢有子四人：長曰諸樊，次曰餘祭，次曰餘昩，次曰季札。季札賢，壽夢欲立之，季札讓不可，於是立諸樊。諸樊卒，以授餘祭，欲兄弟以次相傳，必致國於季札；季札終讓而逃之。其後諸樊之子光與餘昩之子僚爭國，至於夫差，吳遂以亡。宗廟之祭用牲，故曰血食。太伯，吳立國之君。范甯曰：太者，善大之稱；伯者，長也。周太王之元子，故曰太伯。陸德明曰：壽夢，莫公翻。餘祭，側介翻。餘昩，音末。", "textJt": "吴王寿梦有子四人：长曰诸樊，次曰余祭，次曰余昩，次曰季札。季札贤，寿梦欲立之，季札让不可，于是立诸樊。诸樊卒，以授余祭，欲兄弟以次相传，必致国于季札；季札终让而逃之。其后诸樊之子光与余昩之子僚争国，至于夫差，吴遂以亡。宗庙之祭用牲，故曰血食。太伯，吴立国之君。范宁曰：太者，善大之称；伯者，长也。周太王之元子，故曰太伯。陆德明曰：寿梦，莫公翻。余祭，侧介翻。余昩，音末。"}]','史论,文王,孔子,桀,纣,汤,武,微子,成汤,季札,太伯,吴','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(5,'8be40251-db0e-11ef-a22b-a0d3651f611f',1,1,5,'夫禮，辨貴賤，序親疏，裁羣物，制庶事，非名不著，非器不形；名以命之，器以別之，然後上下粲然有倫，此禮之大經也。名器旣亡，則禮安得獨在哉！昔仲叔于奚有功於衞，辭邑而請繁纓，孔子以爲不如多與之邑。惟名與器，不可以假人，君之所司也；政亡則國家從之。衞君待孔子而爲政，孔子欲先正名，以爲名不正則民無所措手足。夫繁纓，小物也，而孔子惜之；正名，細務也，而孔子先之：誠以名器旣亂則上下無以相保故也。夫事未有不生於微而成於著，聖人之慮遠，故能謹其微而治之，衆人之識近，故必待其著而後救之；治其微則用力寡而功多，救其著則竭力而不能及也。易曰：「履霜堅冰至，」書曰：「一日二日萬幾，」謂此類也。故曰分莫大於名也。','夫礼，辨贵贱，序亲疏，裁群物，制庶事，非名不著，非器不形；名以命之，器以别之，然后上下粲然有伦，此礼之大经也。名器既亡，则礼安得独在哉！昔仲叔于奚有功于衞，辞邑而请繁缨，孔子以为不如多与之邑。惟名与器，不可以假人，君之所司也；政亡则国家从之。衞君待孔子而为政，孔子欲先正名，以为名不正则民无所措手足。夫繁缨，小物也，而孔子惜之；正名，细务也，而孔子先之：诚以名器既乱则上下无以相保故也。夫事未有不生于微而成于著，圣人之虑远，故能谨其微而治之，众人之识近，故必待其著而后救之；治其微则用力寡而功多，救其著则竭力而不能及也。易曰：「履霜坚冰至，」书曰：「一日二日万几，」谓此类也。故曰分莫大于名也。','礼，用来分辨贵贱，排列亲疏，裁制万物，治理众事；没有名分，就无法显明；没有器物，就无法体现。用名分来命名，用器物来区别，然后上下才分明有序，这就是礼的根本纲领。名分和器物既然丧失，礼又怎么能单独存在呢！从前仲叔于奚对卫国有功，辞去封邑而请求繁缨这种马饰，孔子认为不如多给他封邑。只有名分和器物，不能借给别人，这是国君所掌管的；政权丧失，国家也就随之灭亡。卫君等待孔子来执掌国政，孔子想先纠正名分，认为名分不正，百姓就不知如何举手投足。繁缨，不过是小物件，孔子却吝惜它；正名，不过是细事，孔子却把它放在首位：实在是因为名分和器物一旦紊乱，上下就无法相互维系了。凡事无不是从细微处萌生，而后发展成显著。圣人思虑深远，所以能在细微时谨慎对待并加以治理；众人见识短浅，所以必定要等到显著之后才去补救。在细微时治理，用力少而功效多；到显著时补救，即使竭尽全力也难以追及。《易经》说：“踩到霜，就知道坚冰将要到来。”《尚书》说：“一天两天之内，就有万端政务。”说的就是这类事情。所以说，上下之分没有比名分更重要的了。','[{"type": "胡注", "text": "左傳：衞孫桓子帥師與齊師戰于新築，衞師敗績。新築人仲叔于奚救孫桓子，桓子是以免。旣而衞人賞之邑，辭；請曲縣、繁纓以朝，許之。孔子聞之曰：「不如多與之邑，惟名與器不可以假人。」繁纓，馬飾也。繁，馬鬣上飾；纓，馬膺前飾。晉志·註曰：纓在馬膺如索帬。繁，音蒲官翻。纓，伊盈翻。索，昔各翻。", "textJt": "左传：衞孙桓子帅师与齐师战于新筑，衞师败绩。新筑人仲叔于奚救孙桓子，桓子是以免。既而衞人赏之邑，辞；请曲县、繁缨以朝，许之。孔子闻之曰：「不如多与之邑，惟名与器不可以假人。」繁缨，马饰也。繁，马鬣上饰；缨，马膺前饰。晋志·注曰：缨在马膺如索帬。繁，音蒲官翻。缨，伊盈翻。索，昔各翻。"}, {"type": "胡注", "text": "見論語。", "textJt": "见论语。"}, {"type": "胡注", "text": "治，直之翻；下同。", "textJt": "治，直之翻；下同。"}, {"type": "胡注", "text": "坤初六爻辭。象曰：「履霜堅冰，陰始凝也。馴致其道，至堅冰也。」", "textJt": "坤初六爻辞。象曰：「履霜坚冰，阴始凝也。驯致其道，至坚冰也。」"}, {"type": "胡注", "text": "皋陶謨之辭。孔安國註曰：幾，微也。言當戒懼萬事之微。幾，居依翻。", "textJt": "皋陶谟之辞。孔安国注曰：几，微也。言当戒惧万事之微。几，居依翻。"}]','史论,仲叔于奚,孔子,衞','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(6,'8be40278-db0e-11ef-b78c-a0d3651f611f',1,1,6,'嗚呼！幽、厲失德，周道日衰，綱紀散壞，下陵上替，諸侯專征，大夫擅政，禮之大體什喪七八矣，然文、武之祀猶緜緜相屬者，蓋以周之子孫尚能守其名分故也。何以言之？昔晉文公有大功於王室，請隧於襄王，襄王不許，曰：「王章也。未有代德而有二王，亦叔父之所惡也。不然，叔父有地而隧，又何請焉！」文公於是懼而不敢違。是故以周之地則不大於曹、滕，以周之民則不衆於邾、莒，然歷數百年，宗主天下，雖以晉、楚、齊、秦之強不敢加者，何哉？徒以名分尚存故也。至於季氏之於魯，田常之於齊，白公之於楚，智伯之於晉，其勢皆足以逐君而自爲，然而卒不敢者，豈其力不足而心不忍哉，乃畏奸名犯分而天下共誅之也。今晉大夫暴蔑其君，剖分晉國，天子旣不能討，又寵秩之，使列於諸侯，是區區之名分復不能守而幷棄之也。先王之禮於斯盡矣！','呜呼！幽、厉失德，周道日衰，纲纪散坏，下陵上替，诸侯专征，大夫擅政，礼之大体什丧七八矣，然文、武之祀犹緜緜相属者，盖以周之子孙尚能守其名分故也。何以言之？昔晋文公有大功于王室，请隧于襄王，襄王不许，曰：「王章也。未有代德而有二王，亦叔父之所恶也。不然，叔父有地而隧，又何请焉！」文公于是惧而不敢违。是故以周之地则不大于曹、滕，以周之民则不众于邾、莒，然历数百年，宗主天下，虽以晋、楚、齐、秦之强不敢加者，何哉？徒以名分尚存故也。至于季氏之于鲁，田常之于齐，白公之于楚，智伯之于晋，其势皆足以逐君而自为，然而卒不敢者，岂其力不足而心不忍哉，乃畏奸名犯分而天下共诛之也。今晋大夫暴蔑其君，剖分晋国，天子既不能讨，又宠秩之，使列于诸侯，是区区之名分复不能守而幷弃之也。先王之礼于斯尽矣！','唉！周幽王、周厉王丧失为君之德，周朝的治国之道日渐衰微，纲纪散乱毁坏，在下者侵凌在上者，在上者政令不行，诸侯擅自征伐，大夫把持国政，礼制的大体已丧失了十分之七八。然而周文王、周武王的祭祀仍能绵绵接续，这大概是因为周室子孙还能守住名分的缘故。为什么这样说呢？从前晋文公对周王室立有大功，向周襄王请求死后使用隧葬之礼，周襄王不答应，说：“这是天子的礼制。没有取代周室的德行，却要有两个天子，这也是叔父所厌恶的。如果不是这样，叔父有自己的封地，完全可以自行隧葬，又何必来向我请求呢！”晋文公因此畏惧，不敢违背。所以，周室的土地并不比曹国、滕国大，民众并不比邾国、莒国多，然而历经数百年，始终是天下宗主，即使以晋、楚、齐、秦的强大，也不敢侵犯，这是为什么呢？只不过因为名分还存在而已。至于鲁国的季氏、齐国的田常、楚国的白公胜、晋国的智伯，他们的势力都足够驱逐国君而自行即位，可是终究不敢这样做，难道是力量不足或于心不忍吗？不过是畏惧背上奸犯名分的罪名而遭到天下人共同讨伐罢了。如今晋国大夫欺凌蔑视自己的国君，瓜分晋国，天子已经无法讨伐，反又封赏他们，使他们列于诸侯，这样，周室仅存的一点名分也不能守住，而一并丢弃了。先王的礼制到这里就完全终结了！','[{"type": "胡注", "text": "謂齊桓公、晉文公至悼公以及楚莊王、吳夫差之類。", "textJt": "谓齐桓公、晋文公至悼公以及楚庄王、吴夫差之类。"}, {"type": "胡注", "text": "謂晉六卿、魯三家、齊田氏之類。", "textJt": "谓晋六卿、鲁三家、齐田氏之类。"}, {"type": "胡注", "text": "屬，聯屬也，音之欲翻。凡聯屬之屬皆同音。", "textJt": "属，联属也，音之欲翻。凡联属之属皆同音。"}, {"type": "胡注", "text": "太叔帶之難，襄王出居于氾。晉文公帥師納王，殺太叔帶。旣定襄王于郟，王勞之以地，辭；請隧焉，王弗許云云。杜預曰：闕地通路曰隧，此乃王者葬禮也。諸侯皆縣柩而下。王章者，章顯王者異於諸侯。古者天子謂同姓諸侯爲伯父、叔父。隧，音遂。惡，烏路翻。難，乃旦翻。氾，音汎。勞，力到翻。闕，其月翻。縣，音玄。柩，其久翻。", "textJt": "太叔带之难，襄王出居于泛。晋文公帅师纳王，杀太叔带。既定襄王于郏，王劳之以地，辞；请隧焉，王弗许云云。杜预曰：阙地通路曰隧，此乃王者葬礼也。诸侯皆县柩而下。王章者，章显王者异于诸侯。古者天子谓同姓诸侯为伯父、叔父。隧，音遂。恶，乌路翻。难，乃旦翻。泛，音泛。劳，力到翻。阙，其月翻。县，音玄。柩，其久翻。"}, {"type": "胡注", "text": "曹、滕、邾、莒，春秋時小國。莒，居許翻。", "textJt": "曹、滕、邾、莒，春秋时小国。莒，居许翻。"}, {"type": "胡注", "text": "魯大夫季氏，自季友以來，世執魯國之政。季平子逐昭公，季康子逐哀公，然終身北面，不敢篡國。田常，卽陳恆。田氏本陳氏；溫公避國諱，改「恆」曰「常」。陳成子得齊國之政，殺闞止，弑簡公，而亦不敢自立。史記·世家以陳敬仲完爲田敬仲完，陳成子恆爲田常，故通鑑因以爲據。白公勝殺楚令尹子西、司馬子期，石乞曰：「焚庫弑王，不然不濟！」白公曰：「弑王不祥，焚庫無聚。」智伯當晉之衰，專其國政，侵伐鄰國，於晉大夫爲最強；攻晉出公，出公道死。智伯欲幷晉而不敢，乃奉哀公驕立之。", "textJt": "鲁大夫季氏，自季友以来，世执鲁国之政。季平子逐昭公，季康子逐哀公，然终身北面，不敢篡国。田常，即陈恒。田氏本陈氏；温公避国讳，改「恒」曰「常」。陈成子得齐国之政，杀阚止，弑简公，而亦不敢自立。史记·世家以陈敬仲完为田敬仲完，陈成子恒为田常，故通鉴因以为据。白公胜杀楚令尹子西、司马子期，石乞曰：「焚库弑王，不然不济！」白公曰：「弑王不祥，焚库无聚。」智伯当晋之衰，专其国政，侵伐邻国，于晋大夫为最强；攻晋出公，出公道死。智伯欲幷晋而不敢，乃奉哀公骄立之。"}, {"type": "胡注", "text": "史記·六國年表：定王十六年，趙、魏、韓滅智伯，遂三分晉國。", "textJt": "史记·六国年表：定王十六年，赵、魏、韩灭智伯，遂三分晋国。"}, {"type": "胡注", "text": "陸德明經典釋文：凡復字，其義訓又者，並音扶又翻。", "textJt": "陆德明经典释文：凡复字，其义训又者，并音扶又翻。"}]','史论,三家分晋,幽,厉,文,武,晋文公,襄王,文公,季氏,田常,白公,智伯,周,曹,滕,邾,莒,晋,楚,齐,秦,鲁,晋国','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(7,'8be647a0-db0e-11ef-984e-a0d3651f611f',1,1,7,'或者以爲當是之時，周室微弱，三晉強盛，雖欲勿許，其可得乎！是大不然。夫三晉雖強，苟不顧天下之誅而犯義侵禮，則不請於天子而自立矣。不請於天子而自立，則爲悖逆之臣，天下苟有桓、文之君，必奉禮義而征之。今請於天子而天子許之，是受天子之命而爲諸侯也，誰得而討之！故三晉之列於諸侯，非三晉之壞禮，乃天子自壞之也。','或者以为当是之时，周室微弱，三晋强盛，虽欲勿许，其可得乎！是大不然。夫三晋虽强，苟不顾天下之诛而犯义侵礼，则不请于天子而自立矣。不请于天子而自立，则为悖逆之臣，天下苟有桓、文之君，必奉礼义而征之。今请于天子而天子许之，是受天子之命而为诸侯也，谁得而讨之！故三晋之列于诸侯，非三晋之坏礼，乃天子自坏之也。','有人说那时周王室微弱，三晋强盛，天子即使想不答应，又怎么可能办到呢？这种说法完全不对。三晋虽然强盛，但如果不顾天下人的责罚而背弃道义、侵犯礼法，就不会向天子请求而自行立为诸侯了。不向天子请求而自行立为诸侯，就是叛逆的臣子；天下若有齐桓公、晋文公那样的君主，必定会尊奉礼义而征讨他们。现在三晋向天子请求，天子又答应了，他们就是受天子之命而成为诸侯，谁还能够讨伐他们呢！所以三晋被列入诸侯之列，并不是三晋败坏了礼制，而是天子自己败坏了礼制啊。','[{"type": "胡注", "text": "三家分晉國，時因謂之「三晉」，猶後之三秦、三齊也。", "textJt": "三家分晋国，时因谓之「三晋」，犹后之三秦、三齐也。"}]','史论,三家分晋,桓,文,周室,三晋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(8,'8be647ae-db0e-11ef-bff7-a0d3651f611f',1,1,8,'烏呼！君臣之禮旣壞矣，則天下以智力相雄長，遂使聖賢之後爲諸侯者，社稷無不泯絕，生民之類糜滅幾盡，豈不哀哉！','乌呼！君臣之礼既坏矣，则天下以智力相雄长，遂使圣贤之后为诸侯者，社稷无不泯绝，生民之类糜灭几尽，岂不哀哉！','唉！君臣之间的礼制既已败坏，天下便依靠智谋和武力互相争胜称雄，致使那些身为诸侯的圣贤后裔，国家无不灭亡绝祀，黎民百姓几乎伤亡殆尽，怎能不令人哀痛！','[{"type": "胡注", "text": "此壞，其義爲成壞之壞，讀如字。", "textJt": "此坏，其义为成坏之坏，读如字。"}, {"type": "胡注", "text": "謂齊、宋亡於田氏，魯、陳、越亡於楚，鄭亡於韓也。泯，彌忍翻，盡也，又彌鄰翻。毛晃曰：沒也，滅也。", "textJt": "谓齐、宋亡于田氏，鲁、陈、越亡于楚，郑亡于韩也。泯，弥忍翻，尽也，又弥邻翻。毛晃曰：没也，灭也。"}, {"type": "胡注", "text": "說文曰：糜，糝也；取糜爛之義，音忙皮翻。幾，居依翻，又渠希翻，近也。", "textJt": "说文曰：糜，糁也；取糜烂之义，音忙皮翻。几，居依翻，又渠希翻，近也。"}]','史论,三家分晋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(9,'8be647be-db0e-11ef-8cea-a0d3651f611f',1,1,9,'初，智宣子將以瑤爲後，智果曰：「不如宵也。瑤之賢於人者五，其不逮者一也。美鬢長大則賢，射御足力則賢，伎藝畢給則賢，巧文辯惠則賢，強毅果敢則賢；如是而甚不仁。夫以其五賢陵人而以不仁行之，其誰能待之？若果立瑤也，智宗必滅。」弗聽。智果別族於太史，爲輔氏。','初，智宣子将以瑶为后，智果曰：「不如宵也。瑶之贤于人者五，其不逮者一也。美鬓长大则贤，射御足力则贤，伎艺毕给则贤，巧文辩惠则贤，强毅果敢则贤；如是而甚不仁。夫以其五贤陵人而以不仁行之，其谁能待之？若果立瑶也，智宗必灭。」弗听。智果别族于太史，为辅氏。','当初，晋国的智宣子准备立智瑶为继承人，智果说：“不如立智宵。智瑶比别人贤能的地方有五项，不如别人的地方只有一项：鬓发漂亮、身材高大，是贤能；射箭驾车很有力气，是贤能；各种技艺无不齐备，是贤能；文辞巧妙、论辩聪慧，是贤能；坚强果敢、刚毅果断，是贤能。即使这样，他却很不仁。如果凭这五项贤能凌驾别人，又用不仁的方式去做，谁还能容得下他呢？如果果真立智瑶为继承人，智氏宗族必定灭亡。”智宣子不听。智果就到太史那里办理脱离智族姓氏的手续，自立为辅氏。','[{"type": "胡注", "text": "韋昭曰：智宣子，晉卿荀躒之子申也。瑤，宣子之子智伯也，諡曰襄子。智果，智氏之族也。宵，宣子之庶子也。按諡法：聖善周聞曰宣。智氏溢美也。", "textJt": "韦昭曰：智宣子，晋卿荀跞之子申也。瑶，宣子之子智伯也，谥曰襄子。智果，智氏之族也。宵，宣子之庶子也。按谥法：圣善周闻曰宣。智氏溢美也。"}, {"type": "胡注", "text": "韋昭曰：不仁也。", "textJt": "韦昭曰：不仁也。"}, {"type": "胡注", "text": "通鑑俗傳寫者多作「美鬚」，非也。國語作「美鬢」，今從之。", "textJt": "通鉴俗传写者多作「美须」，非也。国语作「美鬓」，今从之。"}, {"type": "胡注", "text": "韋昭曰：給，足也。巧文，巧於文辭。伎，渠綺翻。", "textJt": "韦昭曰：给，足也。巧文，巧于文辞。伎，渠绮翻。"}, {"type": "胡注", "text": "韋昭曰：待，猶假也。", "textJt": "韦昭曰：待，犹假也。"}, {"type": "胡注", "text": "此事見國語。按左傳哀公二十三年，晉荀瑤伐齊，始見于傳。哀二十三年，史記元王五年也。荀躒，智文子也。定十四年，智文子猶見于傳。智宣子之事，傳無所考。立瑤之議，當在元王五年之前。韋昭曰：太史掌氏姓，周禮春官之屬；小史掌定世繫，辨昭穆。鄭司農註云：史官主書，故韓宣子聘魯，觀書于太史。世繫，謂帝繫、世本之屬是也；小史主定之。賈公彥疏曰：註引太史證之者，太史史官之長，共其事故也。蓋周之制，小史定姓氏，其書則太史掌之。智果欲避智氏之禍，故於太史別族。宋祁國語補音：別，彼列翻；又如字。", "textJt": "此事见国语。按左传哀公二十三年，晋荀瑶伐齐，始见于传。哀二十三年，史记元王五年也。荀跞，智文子也。定十四年，智文子犹见于传。智宣子之事，传无所考。立瑶之议，当在元王五年之前。韦昭曰：太史掌氏姓，周礼春官之属；小史掌定世系，辨昭穆。郑司农注云：史官主书，故韩宣子聘鲁，观书于太史。世系，谓帝系、世本之属是也；小史主定之。贾公彦疏曰：注引太史证之者，太史史官之长，共其事故也。盖周之制，小史定姓氏，其书则太史掌之。智果欲避智氏之祸，故于太史别族。宋祁国语补音：别，彼列翻；又如字。"}]','人事,权争,三家分晋,智宣子,瑶,智果,宵,智,辅氏','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(10,'8be8ab23-db0e-11ef-a13f-a0d3651f611f',1,1,10,'趙簡子之子，長曰伯魯，幼曰無恤。將置後，不知所立，乃書訓戒之辭於二簡，以授二子曰：「謹識之！」三年而問之，伯魯不能舉其辭；求其簡，已失之矣。問無恤，誦其辭甚習；求其簡，出諸袖中而奏之。於是簡子以無恤爲賢，立以爲後。','赵简子之子，长曰伯鲁，幼曰无恤。将置后，不知所立，乃书训戒之辞于二简，以授二子曰：「谨识之！」三年而问之，伯鲁不能举其辞；求其简，已失之矣。问无恤，诵其辞甚习；求其简，出诸袖中而奏之。于是简子以无恤为贤，立以为后。','赵简子的儿子中，长子叫伯鲁，幼子叫无恤。赵简子准备确立继承人，不知该立谁，便把训诫的话写在两块竹简上，分别交给两个儿子说：“要谨慎记住！”三年后询问他们，伯鲁不能说出竹简上的话；向他要竹简，已经丢失了。问无恤，他把竹简上的话背诵得非常熟练；向他要竹简，他从袖中取出呈上。于是赵简子认为无恤贤能，立他为继承人。','[{"type": "胡注", "text": "趙簡子，文子之孫鞅也。諡法：一德不懈曰簡。白虎通曰：子，孳也，孳孳無已也。趙岐曰：子者，男子之通稱也。長，知兩翻。", "textJt": "赵简子，文子之孙鞅也。谥法：一德不懈曰简。白虎通曰：子，孳也，孳孳无已也。赵岐曰：子者，男子之通称也。长，知两翻。"}, {"type": "胡注", "text": "孔穎達曰：書者，舒也。書緯·璇璣鈐云：書者，如也。則書者，寫其言如其意，得展舒也。世本曰：沮誦、蒼頡作書。釋文名曰：書，庶也，紀庶物也；亦言著也，著之簡紙，求不滅也。簡，竹策也。", "textJt": "孔颖达曰：书者，舒也。书纬·璇玑钤云：书者，如也。则书者，写其言如其意，得展舒也。世本曰：沮诵、苍颉作书。释文名曰：书，庶也，纪庶物也；亦言著也，著之简纸，求不灭也。简，竹策也。"}, {"type": "胡注", "text": "習，熟也。", "textJt": "习，熟也。"}, {"type": "胡注", "text": "毛晃曰：奏，進上也。", "textJt": "毛晃曰：奏，进上也。"}]','人事,赵简子,伯鲁,无恤,简子','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(11,'8be8ab3d-db0e-11ef-9082-a0d3651f611f',1,1,11,'簡子使尹鐸爲晉陽，請曰：「以爲繭絲乎？抑爲保障乎？」簡子曰：「保障哉！」尹鐸損其戶數。簡子謂無恤曰：「晉國有難，而無以尹鐸爲少，無以晉陽爲遠，必以爲歸。」','简子使尹铎为晋阳，请曰：「以为茧丝乎？抑为保障乎？」简子曰：「保障哉！」尹铎损其户数。简子谓无恤曰：「晋国有难，而无以尹铎为少，无以晋阳为远，必以为归。」','赵简子派尹铎去治理晋阳。尹铎请示说：“您是想让我把那里当作抽茧取丝般搜刮民财的地方，还是当作保障之地？”赵简子说：“作保障！”尹铎于是核减了当地民户的数目。赵简子对无恤说：“晋国一旦有难，不要嫌尹铎身份低微，不要嫌晋阳路途遥远，一定要把那里作为归宿。”','[{"type": "胡注", "text": "姓譜：尹，少昊之子，封於尹城，子孫因爲氏。韋昭曰：晉陽，趙氏邑。爲，治也。班志曰：晉陽，故詩唐國。周成王滅唐，封弟叔虞。龍山在西，晉水所出，東入汾。臣瓚曰：所謂唐，今河東永安縣是也，去晉四百里。括地志曰：晉陽故城，今名晉城，在蒲州虞鄕縣西。今按水經註：晉水出晉陽縣西龍山。昔智伯遏晉水以灌晉陽，其水分爲二流，北瀆卽智氏故渠也。同過水出沾縣北山，西過榆次縣南，又西到晉陽縣南。榆次縣南水側有鑿臺，戰國策所謂「智伯死於鑿臺之下」，卽此處也。參而考之，晉陽故城恐不在蒲州。水經註又云：叔虞封於唐，縣有晉水，故改名爲晉。子夏序詩，「此晉也而謂之唐」，是也，與班志合。瓚說及括地志未知何據。", "textJt": "姓谱：尹，少昊之子，封于尹城，子孙因为氏。韦昭曰：晋阳，赵氏邑。为，治也。班志曰：晋阳，故诗唐国。周成王灭唐，封弟叔虞。龙山在西，晋水所出，东入汾。臣瓒曰：所谓唐，今河东永安县是也，去晋四百里。括地志曰：晋阳故城，今名晋城，在蒲州虞鄕县西。今按水经注：晋水出晋阳县西龙山。昔智伯遏晋水以灌晋阳，其水分为二流，北渎即智氏故渠也。同过水出沾县北山，西过榆次县南，又西到晋阳县南。榆次县南水侧有凿台，战国策所谓「智伯死于凿台之下」，即此处也。参而考之，晋阳故城恐不在蒲州。水经注又云：叔虞封于唐，县有晋水，故改名为晋。子夏序诗，「此晋也而谓之唐」，是也，与班志合。瓒说及括地志未知何据。"}, {"type": "胡注", "text": "繭絲，謂浚民之膏澤，如抽繭之緒，不盡則不止。保障，謂厚民之生，如築堡以自障，愈培則愈厚。宋祁曰：障，之亮翻，又音章。", "textJt": "茧丝，谓浚民之膏泽，如抽茧之绪，不尽则不止。保障，谓厚民之生，如筑堡以自障，愈培则愈厚。宋祁曰：障，之亮翻，又音章。"}, {"type": "胡注", "text": "韋昭曰：損其戶，則民優而稅少。", "textJt": "韦昭曰：损其户，则民优而税少。"}, {"type": "胡注", "text": "而，汝也。難，乃旦翻，患也，阨也。少，音多少之少。重之爲多，輕之爲少。", "textJt": "而，汝也。难，乃旦翻，患也，阨也。少，音多少之少。重之为多，轻之为少。"}]','内政,人事,三家分晋,简子,尹铎,无恤,晋阳,晋国','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(12,'8be8ab8b-db0e-11ef-8705-a0d3651f611f',1,1,12,'及智宣子卒，智襄子爲政，與韓康子、魏桓子宴於藍臺。智伯戲康子而侮段規。智國聞之，諫曰：「主不備難，難必至矣！」智伯曰：「難將由我。我不爲難，誰敢興之！」對曰：「不然。夏書有之：『一人三失，怨豈在明，不見是圖。』夫君子能勤小物，故無大患。今主一宴而恥人之君相，又弗備，曰『不敢興難』，無乃不可乎！蜹、蟻、蜂、蠆，皆能害人，況君相乎！」弗聽。','及智宣子卒，智襄子为政，与韩康子、魏桓子宴于蓝台。智伯戏康子而侮段规。智国闻之，谏曰：「主不备难，难必至矣！」智伯曰：「难将由我。我不为难，谁敢兴之！」对曰：「不然。夏书有之：『一人三失，怨岂在明，不见是图。』夫君子能勤小物，故无大患。今主一宴而耻人之君相，又弗备，曰『不敢兴难』，无乃不可乎！蜹、蚁、蜂、虿，皆能害人，况君相乎！」弗听。','智宣子去世后，智襄子智瑶执掌国政，与韩康子、魏桓子在蓝台宴饮。席间智瑶戏弄韩康子，又羞辱韩康子的家相段规。智瑶的家臣智国听说后，进谏说：“主公如果不防备祸难，祸难一定会到来！”智瑶说：“祸难由我作主。我不降祸，谁敢发难！”智国回答说：“并非如此。《夏书》上有这样的话：‘一个人屡次犯错，怨仇岂会只在明处，应在尚未显现时就设法防备。’君子能够勤谨地对待小事，所以没有大的祸患。如今主公因一次宴饮就羞辱人家的国君与国相，又不加防备，还说‘他们不敢发难’，恐怕不可以吧！蚊子、蚂蚁、黄蜂、蝎子都能伤害人，何况是国君和国相呢！”智瑶不听。','[{"type": "胡注", "text": "諡法：有勞定國曰襄。爲政，爲晉國之政。", "textJt": "谥法：有劳定国曰襄。为政，为晋国之政。"}, {"type": "胡注", "text": "韓康子，韓宣子之曾孫莊子之子虔虎也。魏桓子，魏獻子之子曼多之孫駒也。諡法：溫柔好樂曰康；辟土服遠曰桓。爾雅：四方而高曰臺。", "textJt": "韩康子，韩宣子之曾孙庄子之子虔虎也。魏桓子，魏献子之子曼多之孙驹也。谥法：温柔好乐曰康；辟土服远曰桓。尔雅：四方而高曰台。"}, {"type": "胡注", "text": "姓譜：段，鄭共叔段之後。", "textJt": "姓谱：段，郑共叔段之后。"}, {"type": "胡注", "text": "春秋以來，大夫之家臣謂大夫曰主。難，乃旦翻；下同。", "textJt": "春秋以来，大夫之家臣谓大夫曰主。难，乃旦翻；下同。"}, {"type": "胡注", "text": "書·五子之歌之辭。夏，戶雅翻。見，賢遍翻，發見也，著也，形也。", "textJt": "书·五子之歌之辞。夏，户雅翻。见，贤遍翻，发见也，著也，形也。"}, {"type": "胡注", "text": "夫，音扶。段規，韓康子之相也。相，息醬翻；下同。", "textJt": "夫，音扶。段规，韩康子之相也。相，息酱翻；下同。"}, {"type": "胡注", "text": "宋祁曰：蜹，如銳翻；又字林：人劣翻。秦人謂蚊爲蜹。今按：蜹，小蟲，日中羣集人之肌膚而嘬其血，蚊之類也。蜂，細腰而能螫人。蠆亦毒蟲，長尾，音丑邁翻。", "textJt": "宋祁曰：蜹，如锐翻；又字林：人劣翻。秦人谓蚊为蜹。今按：蜹，小虫，日中群集人之肌肤而嘬其血，蚊之类也。蜂，细腰而能螫人。虿亦毒虫，长尾，音丑迈翻。"}]','权争,晋阳之战（三家灭智）,智宣子,智襄子,韩康子,魏桓子,智伯,康子,段规,智国,蓝台','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(13,'8beb0a93-db0e-11ef-8ca2-a0d3651f611f',1,1,13,'智伯請地於韓康子，康子欲弗與。段規曰：「智伯好利而愎，不與，將伐我；不如與之。彼狃於得地，必請於他人；他人不與，必嚮之以兵，然後我得免於患而待事之變矣。」康子曰：「善。」使使者致萬家之邑於智伯。智伯悅。又求地於魏桓子，桓子欲弗與。任章曰：「何故弗與？」桓子曰：「無故索地，故弗與。」任章曰：「無故索地，諸大夫必懼；吾與之地，智伯必驕。彼驕而輕敵，此懼而相親；以相親之兵待輕敵之人，智氏之命必不長矣。周書曰：『將欲敗之，必姑輔之。將欲取之，必姑與之。』主不如與之，以驕智伯，然後可以擇交而圖智氏矣，柰何獨以吾爲智氏質乎！」桓子曰：「善。」復與之萬家之邑一。','智伯请地于韩康子，康子欲弗与。段规曰：「智伯好利而愎，不与，将伐我；不如与之。彼狃于得地，必请于他人；他人不与，必向之以兵，然后我得免于患而待事之变矣。」康子曰：「善。」使使者致万家之邑于智伯。智伯悦。又求地于魏桓子，桓子欲弗与。任章曰：「何故弗与？」桓子曰：「无故索地，故弗与。」任章曰：「无故索地，诸大夫必惧；吾与之地，智伯必骄。彼骄而轻敌，此惧而相亲；以相亲之兵待轻敌之人，智氏之命必不长矣。周书曰：『将欲败之，必姑辅之。将欲取之，必姑与之。』主不如与之，以骄智伯，然后可以择交而图智氏矣，柰何独以吾为智氏质乎！」桓子曰：「善。」复与之万家之邑一。','智伯瑶向韩康子索要土地，韩康子不想给。段规说：“智瑶贪财而又刚愎自用，如果不给，他就会攻打我们；不如给他。他因轻易得地而更加骄纵，必定会再向别人索要；别人不给，他一定会对人家用兵。这样我们就能免于祸患，静观事态变化。”韩康子说：“好。”于是派使者把一座有万户人家的城邑送给了智伯。智伯很高兴。他又向魏桓子索要土地，魏桓子不想给。任章说：“为什么不给？”魏桓子说：“无缘无故索要土地，所以不给。”任章说：“智瑶无缘无故索要土地，各位大夫一定害怕；我们给他土地，智瑶一定骄傲。他骄傲就会轻视敌人，我们害怕就会互相亲近；用互相亲近的军队对付轻敌的人，智氏的性命一定不会长久了。《周书》说：‘想要打败他，必须先暂且帮助他；想要夺取他，必须先暂且给他。’主公不如给他，让智瑶骄傲，然后就可以选择结交盟友来图谋智氏了，为什么偏偏要让我们做智氏的靶子呢！”魏桓子说：“好。”又给了智伯瑶一座有万户人家的城邑。','[{"type": "胡注", "text": "毛晃曰：邑，都邑。四井爲邑，四邑爲丘；邑方二里，丘方四里。載師以公邑之田任甸地，以家邑之田任稍地。註：公邑，謂六遂餘地。家邑，大夫之采地。此又與四井之邑不同。又都，國都；邑，縣也。左傳：凡邑有先君宗廟之主曰都，無曰邑。邑曰築，都曰城。此謂大縣邑也。杜預引周禮「四縣爲都，四井爲邑」，恐誤。四井之邑方二里，豈能容宗廟城郭！如論語「十室之邑」，西都賦「都都相望，邑邑相屬」，則是四縣四井之都邑也。若千室之邑、萬家之邑，則非井邑矣。項安世曰：小司徒井牧田野，以四井爲邑，凡三十六家；除公田四夫，凡三十二家；遂大夫會爲邑者之政，以里爲邑，凡二十五家。遂大夫蓋論里井之制，二十五家共一里門，卽六鄕之二十五家爲一閭也；小司徒蓋論溝洫之制，四井爲邑，共用一溝，卽匠人所謂「井間廣四尺深四尺謂之溝」也。居則度人之衆寡，溝則度水之衆寡，此其所以異歟！毛、項二說皆明周制，參而考之，戰國之所謂邑非周制矣。致，送至也。", "textJt": "毛晃曰：邑，都邑。四井为邑，四邑为丘；邑方二里，丘方四里。载师以公邑之田任甸地，以家邑之田任稍地。注：公邑，谓六遂余地。家邑，大夫之采地。此又与四井之邑不同。又都，国都；邑，县也。左传：凡邑有先君宗庙之主曰都，无曰邑。邑曰筑，都曰城。此谓大县邑也。杜预引周礼「四县为都，四井为邑」，恐误。四井之邑方二里，岂能容宗庙城郭！如论语「十室之邑」，西都赋「都都相望，邑邑相属」，则是四县四井之都邑也。若千室之邑、万家之邑，则非井邑矣。项安世曰：小司徒井牧田野，以四井为邑，凡三十六家；除公田四夫，凡三十二家；遂大夫会为邑者之政，以里为邑，凡二十五家。遂大夫盖论里井之制，二十五家共一里门，即六鄕之二十五家为一闾也；小司徒盖论沟洫之制，四井为邑，共用一沟，即匠人所谓「井间广四尺深四尺谓之沟」也。居则度人之众寡，沟则度水之众寡，此其所以异欤！毛、项二说皆明周制，参而考之，战国之所谓邑非周制矣。致，送至也。"}, {"type": "胡注", "text": "任章，魏桓子之相也。姓譜：黃帝二十五子，十二人各以德爲姓，第一曰任氏。又任爲風姓之國，實太昊之後，主濟祀，今濟州任城卽其地。任，市林翻。", "textJt": "任章，魏桓子之相也。姓谱：黄帝二十五子，十二人各以德为姓，第一曰任氏。又任为风姓之国，实太昊之后，主济祀，今济州任城即其地。任，市林翻。"}, {"type": "胡注", "text": "逸書也。敗，補邁翻。", "textJt": "逸书也。败，补迈翻。"}, {"type": "胡注", "text": "質，脂利翻，物相綴當也。又質讀如字，亦通。質，謂椹質也，質的也。椹質受斧，質的受矢。言智伯怒魏桓子，必加兵於魏，如椹質之受斧，質的之受矢也。", "textJt": "质，脂利翻，物相缀当也。又质读如字，亦通。质，谓椹质也，质的也。椹质受斧，质的受矢。言智伯怒魏桓子，必加兵于魏，如椹质之受斧，质的之受矢也。"}]','外交,权争,晋阳之战（三家灭智）,智伯,韩康子,康子,段规,魏桓子,桓子,任章,智氏','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(14,'8beb0acd-db0e-11ef-8a3d-a0d3651f611f',1,1,14,'智伯又求蔡、皋狼之地於趙襄子，襄子弗與。智伯怒，帥韓、魏之甲以攻趙氏。襄子將出，曰：「吾何走乎？」從者曰：「長子近，且城厚完。」襄子曰：「民罷力以完之，又斃死以守之，其誰與我！」從者曰：「邯鄲之倉庫實。」襄子曰：「浚民之膏澤以實之，又因而殺之，其誰與我！其晉陽乎，先主之所屬也，尹鐸之所寬也，民必和矣。」乃走晉陽。','智伯又求蔡、皋狼之地于赵襄子，襄子弗与。智伯怒，帅韩、魏之甲以攻赵氏。襄子将出，曰：「吾何走乎？」从者曰：「长子近，且城厚完。」襄子曰：「民罢力以完之，又毙死以守之，其谁与我！」从者曰：「邯郸之仓库实。」襄子曰：「浚民之膏泽以实之，又因而杀之，其谁与我！其晋阳乎，先主之所属也，尹铎之所宽也，民必和矣。」乃走晋阳。','智伯又向赵襄子索取蔡、皋狼两处土地，赵襄子不肯给。智伯大怒，率领韩、魏两家的甲兵攻打赵氏。赵襄子准备出逃，问：“我逃到哪里去呢？”随从说：“长子离得近，而且城墙厚实完好。”赵襄子说：“百姓耗尽力气才修好它，又要拼死为它守卫，谁还会支持我！”随从说：“邯郸的仓库充实。”赵襄子说：“榨取百姓的脂膏才充实了仓库，现在又因此让他们去送死，谁还会支持我！还是去晋阳吧，那是先主托付的地方，尹铎在那里施政宽厚，百姓必定和睦归附。”于是逃往晋阳。','[{"type": "胡注", "text": "康曰：皋，姑勞切；狼，盧當切；春秋蔡地，後爲趙邑。余據春秋之時，晉、楚爭盟，晉不能越鄭而服蔡。三家分晉，韓得成皋，因以幷鄭，時蔡已爲楚所滅，鄭之南境亦入于楚，就使皋狼爲蔡地，趙襄子安得而有之！漢書·地理志西河郡有皋狼縣，又有藺縣。漢之西河，春秋以來皆爲晉境，而古文「藺」字與「蔡」字近，或者「蔡」字其「藺」字之訛也。", "textJt": "康曰：皋，姑劳切；狼，卢当切；春秋蔡地，后为赵邑。余据春秋之时，晋、楚争盟，晋不能越郑而服蔡。三家分晋，韩得成皋，因以幷郑，时蔡已为楚所灭，郑之南境亦入于楚，就使皋狼为蔡地，赵襄子安得而有之！汉书·地理志西河郡有皋狼县，又有蔺县。汉之西河，春秋以来皆为晋境，而古文「蔺」字与「蔡」字近，或者「蔡」字其「蔺」字之讹也。"}, {"type": "胡注", "text": "從，才用翻。長子縣，周史辛伯所封邑。班志屬上黨郡。陸德明曰：長子之長，丁丈翻。顏師古曰：長，讀爲短長之長；今讀爲長幼之長，非也。崔豹古今註曰：城，盛也，所以盛受民物也。淮南子曰：鯀作城。盛，時征翻。", "textJt": "从，才用翻。长子县，周史辛伯所封邑。班志属上党郡。陆德明曰：长子之长，丁丈翻。颜师古曰：长，读为短长之长；今读为长幼之长，非也。崔豹古今注曰：城，盛也，所以盛受民物也。淮南子曰：鲧作城。盛，时征翻。"}, {"type": "胡注", "text": "韋昭曰：謂誰與我同力也。", "textJt": "韦昭曰：谓谁与我同力也。"}, {"type": "胡注", "text": "邯鄲，卽春秋邯鄲午之邑也。班志，邯鄲縣屬趙國。張晏曰：邯鄲山在東城下。單，盡也。城郭從邑，故旁加邑。宋白曰：邯鄲本衞地，後屬晉；七國時爲趙都，趙敬侯自晉陽始都邯鄲。余按史記·六國年表，周安王之十六年，趙敬侯之元年；烈王之二年，趙成侯之元年。成侯二十二年，魏克邯鄲，是年顯王之十六年也。二十四年，魏歸邯鄲。若敬侯已都邯鄲，魏克其國都而趙不亡，何也？至顯王二十二年，公子范襲邯鄲，不勝而死，是年肅侯之三年也。意此時趙方都邯鄲，蓋肅侯徙都，非敬侯也。邯，音寒。鄲，音丹，康：多寒切。", "textJt": "邯郸，即春秋邯郸午之邑也。班志，邯郸县属赵国。张晏曰：邯郸山在东城下。单，尽也。城郭从邑，故旁加邑。宋白曰：邯郸本衞地，后属晋；七国时为赵都，赵敬侯自晋阳始都邯郸。余按史记·六国年表，周安王之十六年，赵敬侯之元年；烈王之二年，赵成侯之元年。成侯二十二年，魏克邯郸，是年显王之十六年也。二十四年，魏归邯郸。若敬侯已都邯郸，魏克其国都而赵不亡，何也？至显王二十二年，公子范袭邯郸，不胜而死，是年肃侯之三年也。意此时赵方都邯郸，盖肃侯徙都，非敬侯也。邯，音寒。郸，音丹，康：多寒切。"}, {"type": "胡注", "text": "韋昭曰：浚，煎也，讀曰醮。宋祁曰：浚，蘇俊翻；醮，子召翻；余謂浚讀當如宋音。浚者，疏瀹也，淘也，深也。", "textJt": "韦昭曰：浚，煎也，读曰醮。宋祁曰：浚，苏俊翻；醮，子召翻；余谓浚读当如宋音。浚者，疏瀹也，淘也，深也。"}, {"type": "胡注", "text": "古者諸侯之大夫，其家之臣子皆稱之曰主，死則曰先主，考左傳可見已。屬，陟玉翻。", "textJt": "古者诸侯之大夫，其家之臣子皆称之曰主，死则曰先主，考左传可见已。属，陟玉翻。"}]','军事,晋阳之战（三家灭智）,智伯,赵襄子,襄子,赵氏,尹铎,蔡,皋狼,韩,魏,长子,邯郸,晋阳','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(15,'8bedcafb-db0e-11ef-8771-a0d3651f611f',1,1,15,'三家以國人圍而灌之，城不浸者三版；沈竈產鼃，民無叛意。智伯行水，魏桓子御，韓康子驂乘。智伯曰：「吾乃今知水可以亡人國也。」桓子肘康子，康子履桓子之跗，以汾水可以灌安邑，絳水可以灌平陽也。絺疵謂智伯曰：「韓、魏必反矣。」智伯曰：「子何以知之？」絺疵曰：「以人事知之。夫從韓、魏之兵以攻趙，趙亡，難必及韓、魏矣。今約勝趙而三分其地，城不沒者三版，人馬相食，城降有日，而二子無喜志，有憂色，是非反而何？」明日，智伯以絺疵之言告二子，二子曰：「此夫讒人欲爲趙氏游說，使主疑於二家而懈於攻趙氏也。不然，夫二家豈不利朝夕分趙氏之田，而欲爲危難不可成之事乎！」二子出，絺疵入曰：「主何以臣之言告二子也？」智伯曰：「子何以知之？」對曰：「臣見其視臣端而趨疾，知臣得其情故也。」智伯不悛。絺疵請使於齊。','三家以国人围而灌之，城不浸者三版；沈灶产鼃，民无叛意。智伯行水，魏桓子御，韩康子骖乘。智伯曰：「吾乃今知水可以亡人国也。」桓子肘康子，康子履桓子之跗，以汾水可以灌安邑，绛水可以灌平阳也。𫄨疵谓智伯曰：「韩、魏必反矣。」智伯曰：「子何以知之？」𫄨疵曰：「以人事知之。夫从韩、魏之兵以攻赵，赵亡，难必及韩、魏矣。今约胜赵而三分其地，城不没者三版，人马相食，城降有日，而二子无喜志，有忧色，是非反而何？」明日，智伯以𫄨疵之言告二子，二子曰：「此夫谗人欲为赵氏游说，使主疑于二家而懈于攻赵氏也。不然，夫二家岂不利朝夕分赵氏之田，而欲为危难不可成之事乎！」二子出，𫄨疵入曰：「主何以臣之言告二子也？」智伯曰：「子何以知之？」对曰：「臣见其视臣端而趋疾，知臣得其情故也。」智伯不悛。𫄨疵请使于齐。','智瑶、韩康子、魏桓子三家统领国人包围晋阳，并引水灌城，城墙没有被水淹没的部分只有三版高；锅灶沉没在水中，生出了蛙蛤，百姓仍没有背叛之意。智瑶巡视水势，魏桓子为之驾车，韩康子在右边陪乘。智瑶说：“我如今才知道，水可以灭亡他人的国家啊。”魏桓子用胳膊肘碰了碰韩康子，韩康子又踩了踩魏桓子的脚背，两人都想到汾水可以灌魏都安邑，绛水可以灌韩都平阳。絺疵对智瑶说：“韩、魏两家必定会反叛。”智瑶问：“您凭什么知道？”絺疵说：“根据人事推知。我们率领韩、魏两家的军队攻打赵氏，赵氏灭亡之后，祸难必然落到韩、魏两家。如今约定战胜赵氏后三家瓜分其地，城墙没被水淹没的只有三版，城中人马相食，城池投降只是早晚的事，而这两人没有喜悦之意，反而面有忧色，这不是要反叛又是什么？”次日，智瑶把絺疵的话告诉了韩、魏二人，二人说：“这是那进谗言的人想替赵氏游说，让主公怀疑我们两家而放松攻打赵氏啊。不然的话，我们两家难道不乐于早晚分取赵氏的田地，反而要去做危险而难以成功的事吗？”两人出去后，絺疵进来说：“主公为什么把臣的话告诉那两人呢？”智瑶说：“您怎么知道？”絺疵回答说：“臣看到他们盯着臣看而且快步离开，便知道他们已经察觉臣掌握了实情。”智瑶仍不悔改。絺疵于是请求出使齐国以避祸。','[{"type": "胡注", "text": "高二尺爲一版；三版，六尺。", "textJt": "高二尺为一版；三版，六尺。"}, {"type": "胡注", "text": "沈，持林翻。顏師古漢書音義曰：鼃，黽也，似蝦蟇而長脚，其色青。史游急就章曰：蛙，蝦蟇。陸佃埤雅曰：鼃，似蝦蟇而長踦，瞋目如怒。鼃，與蛙同，音下媧翻。", "textJt": "沈，持林翻。颜师古汉书音义曰：鼃，黾也，似虾蟇而长脚，其色青。史游急就章曰：蛙，虾蟇。陆佃埤雅曰：鼃，似虾蟇而长踦，瞋目如怒。鼃，与蛙同，音下娲翻。"}, {"type": "胡注", "text": "據經典釋文，凡巡行之行，音下孟翻；後倣此。", "textJt": "据经典释文，凡巡行之行，音下孟翻；后倣此。"}, {"type": "胡注", "text": "兵車，尊者居左，執弓矢；御者居中；有力者居右，持矛以備傾側，所謂車右是也。韓、魏畏智氏之強，一爲之御，一爲之右。驂，與參同，參者，三也。三人同車則曰驂乘，四人同車則曰駟乘。左傳：齊伐晉，燭庸之越駟乘。杜預註曰：四人共乘者殿車。乘，石證翻。", "textJt": "兵车，尊者居左，执弓矢；御者居中；有力者居右，持矛以备倾侧，所谓车右是也。韩、魏畏智氏之强，一为之御，一为之右。骖，与参同，参者，三也。三人同车则曰骖乘，四人同车则曰驷乘。左传：齐伐晋，烛庸之越驷乘。杜预注曰：四人共乘者殿车。乘，石证翻。"}, {"type": "胡注", "text": "跗，音夫，足趾也。班志：汾水出汾陽北山。汾陽縣屬太原郡，安邑縣屬河東郡。史記正義曰：安邑故城在絳州夏縣東北十五里。應劭曰：絳水出河東絳縣西南。平陽縣亦屬河東郡。安邑，魏絳始居邑。平陽，韓武子玄孫貞子始居之。桓、康二子之肘足接，蓋各爲都邑慮也。水經註曰：絳水出絳縣西南，蓋以故絳爲言，其水出絳山東，西北流而合于澮，猶在絳縣界中。智伯所謂「汾水可以灌安邑」，或亦有之；「絳水可以灌平陽」，未識所由。余謂自春秋之季至于元魏，歷年滋多，郡縣之離合，川谷之遷改，有不可以一時所睹爲據者。史記正義曰：韓初都平陽，今晉州也。括地志曰：絳水一名白，今名沸泉，源出絳山，飛泉奮湧，揚波注縣，積壑三十餘丈，望之極爲奇觀，可接引北灌平陽城。酈道元父範，歷仕三齊，少長齊地，熟其山川，後入關死於道，未嘗至河東也。此蓋因耳學而致疑。括地志成於唐之魏王泰，泰者，太宗之愛子，羅致天下一時名儒以作此書，其考據宜詳，當取以爲據。", "textJt": "跗，音夫，足趾也。班志：汾水出汾阳北山。汾阳县属太原郡，安邑县属河东郡。史记正义曰：安邑故城在绛州夏县东北十五里。应劭曰：绛水出河东绛县西南。平阳县亦属河东郡。安邑，魏绛始居邑。平阳，韩武子玄孙贞子始居之。桓、康二子之肘足接，盖各为都邑虑也。水经注曰：绛水出绛县西南，盖以故绛为言，其水出绛山东，西北流而合于浍，犹在绛县界中。智伯所谓「汾水可以灌安邑」，或亦有之；「绛水可以灌平阳」，未识所由。余谓自春秋之季至于元魏，历年滋多，郡县之离合，川谷之迁改，有不可以一时所睹为据者。史记正义曰：韩初都平阳，今晋州也。括地志曰：绛水一名白，今名沸泉，源出绛山，飞泉奋涌，扬波注县，积壑三十余丈，望之极为奇观，可接引北灌平阳城。郦道元父范，历仕三齐，少长齐地，熟其山川，后入关死于道，未尝至河东也。此盖因耳学而致疑。括地志成于唐之魏王泰，泰者，太宗之爱子，罗致天下一时名儒以作此书，其考据宜详，当取以为据。"}, {"type": "胡注", "text": "夫，音扶；餘並同。難，乃旦翻。降，戶江翻，下也，服也。說，輸芮翻。懈，居隘翻，怠也。危難，如字。悛，丑緣翻，改也，止也。絺，抽遲翻，姓也。康曰：「絺」當作「郗」，姓譜諸書未有從絲者，疑借字。余按姓譜：絺姓，周蘇忿生支子，封於絺，因氏焉。爲趙之爲，音于僞翻。使，疏吏翻。疵請出使以避禍也。", "textJt": "夫，音扶；余并同。难，乃旦翻。降，户江翻，下也，服也。说，输芮翻。懈，居隘翻，怠也。危难，如字。悛，丑缘翻，改也，止也。𫄨，抽迟翻，姓也。康曰：「𫄨」当作「郗」，姓谱诸书未有从丝者，疑借字。余按姓谱：𫄨姓，周苏忿生支子，封于𫄨，因氏焉。为赵之为，音于伪翻。使，疏吏翻。疵请出使以避祸也。"}]','军事,权争,晋阳之战（三家灭智）,智伯,魏桓子,韩康子,桓子,康子,𫄨疵,赵氏,汾水,安邑,绛水,平阳,韩,魏,赵,齐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(16,'8bef6580-db0e-11ef-ab45-a0d3651f611f',1,1,16,'趙襄子使張孟談潛出見二子，曰：「臣聞脣亡則齒寒。今智伯帥韓、魏以攻趙，趙亡則韓、魏爲之次矣。」二子曰：「我心知其然也；恐事未遂而謀泄，則禍立至矣。」張孟談曰：「謀出二主之口，入臣之耳，何傷也！」二子乃潛與張孟談約，爲之期日而遣之。襄子夜使人殺守隄之吏，而決水灌智伯軍。智伯軍救水而亂，韓、魏翼而擊之，襄子將卒犯其前，大敗智伯之衆，遂殺智伯，盡滅智氏之族。唯輔果在。','赵襄子使张孟谈潜出见二子，曰：「臣闻唇亡则齿寒。今智伯帅韩、魏以攻赵，赵亡则韩、魏为之次矣。」二子曰：「我心知其然也；恐事未遂而谋泄，则祸立至矣。」张孟谈曰：「谋出二主之口，入臣之耳，何伤也！」二子乃潜与张孟谈约，为之期日而遣之。襄子夜使人杀守隄之吏，而决水灌智伯军。智伯军救水而乱，韩、魏翼而击之，襄子将卒犯其前，大败智伯之众，遂杀智伯，尽灭智氏之族。唯辅果在。','赵襄子派张孟谈秘密出城去见韩、魏二子，说：“我听说唇亡则齿寒。如今智伯统率韩、魏两军攻打赵氏，赵氏灭亡之后，韩、魏就是接下来的了。”韩康子、魏桓子说：“我们心里知道会是这样；只是怕事情还没成功而计谋泄露，那么灾祸立刻就会到来。”张孟谈说：“计谋从两位主人口中说出，只进入我一个人的耳中，有什么妨害呢！”二人于是暗中与张孟谈约定，定好行动的日期后送走了他。赵襄子趁夜派人杀死智伯军守堤的官吏，并决开河水灌淹智伯军营。智伯军因救水而陷入混乱，韩、魏从两翼夹击，赵襄子率领士卒冲击智伯军正面，大败智伯的军队，随后杀死智伯，将智氏族人全部诛灭。只有辅果幸免。','[{"type": "胡注", "text": "姓譜：張氏本自軒轅第五子揮，始造弦，寔張網羅，世掌其職，後因氏焉。風俗傳云：張、王、李、趙，黃帝所賜姓也。又晉有解張，字張侯，自此晉國有張氏。唐姓氏譜：張氏出自姬姓，黃帝子少昊青陽氏第五子揮正始制弓矢，子孫賜姓張。周宣王卿士張仲，其後裔事晉爲大夫。", "textJt": "姓谱：张氏本自轩辕第五子挥，始造弦，寔张网罗，世掌其职，后因氏焉。风俗传云：张、王、李、赵，黄帝所赐姓也。又晋有解张，字张侯，自此晋国有张氏。唐姓氏谱：张氏出自姬姓，黄帝子少昊青阳氏第五子挥正始制弓矢，子孙赐姓张。周宣王卿士张仲，其后裔事晋为大夫。"}, {"type": "胡注", "text": "將，卽亮翻，又音如字。將，領也。卒，臧沒翻。說文：吏人給事者衣爲卒，卒衣有題識；其字從「衣」從「十」。", "textJt": "将，即亮翻，又音如字。将，领也。卒，臧没翻。说文：吏人给事者衣为卒，卒衣有题识；其字从「衣」从「十」。"}, {"type": "胡注", "text": "以此敗彼曰敗。敗，比邁翻。", "textJt": "以此败彼曰败。败，比迈翻。"}, {"type": "胡注", "text": "史記·六國年表，三晉滅智氏在周定王十六年，上距獲麟二十七年。皇甫謐曰：元王十一年癸未，三晉滅智伯。", "textJt": "史记·六国年表，三晋灭智氏在周定王十六年，上距获麟二十七年。皇甫谧曰：元王十一年癸未，三晋灭智伯。"}, {"type": "胡注", "text": "以別族也。", "textJt": "以别族也。"}]','军事,外交,晋阳之战（三家灭智）,赵襄子,张孟谈,智伯,襄子,智氏,辅果,韩,魏,赵','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(17,'8bef65c0-db0e-11ef-af4d-a0d3651f611f',1,1,17,'臣光曰：智伯之亡也，才勝德也。夫才與德異，而世俗莫之能辨，通謂之賢，此其所以失人也。夫聰察強毅之謂才，正直中和之謂德。才者，德之資也；德者，才之帥也。雲夢之竹，天下之勁也；然而不矯揉，不羽括，則不能以入堅。棠谿之金，天下之利也；然而不鎔範，不砥礪，則不能以擊強。是故才德全盡謂之「聖人」，才德兼亡謂之「愚人」；德勝才謂之「君子」，才勝德謂之「小人」。凡取人之術，苟不得聖人、君子而與之，與其得小人，不若得愚人。何則？君子挾才以爲善，小人挾才以爲惡。挾才以爲善者，善無不至矣；挾才以爲惡者，惡亦無不至矣。愚者雖欲爲不善，智不能周，力不能勝，譬如乳狗搏人，人得而制之。小人智足以遂其姦，勇足以決其暴，是虎而翼者也，其爲害豈不多哉！夫德者人之所嚴，而才者人之所愛；愛者易親，嚴者易疏，是以察者多蔽於才而遺於德。自古昔以來，國之亂臣，家之敗子，才有餘而德不足，以至於顚覆者多矣，豈特智伯哉！故爲國爲家者苟能審於才德之分而知所先後，又何失人之足患哉！','臣光曰：智伯之亡也，才胜德也。夫才与德异，而世俗莫之能辨，通谓之贤，此其所以失人也。夫聪察强毅之谓才，正直中和之谓德。才者，德之资也；德者，才之帅也。云梦之竹，天下之劲也；然而不矫揉，不羽括，则不能以入坚。棠谿之金，天下之利也；然而不镕范，不砥砺，则不能以击强。是故才德全尽谓之「圣人」，才德兼亡谓之「愚人」；德胜才谓之「君子」，才胜德谓之「小人」。凡取人之术，苟不得圣人、君子而与之，与其得小人，不若得愚人。何则？君子挟才以为善，小人挟才以为恶。挟才以为善者，善无不至矣；挟才以为恶者，恶亦无不至矣。愚者虽欲为不善，智不能周，力不能胜，譬如乳狗搏人，人得而制之。小人智足以遂其奸，勇足以决其暴，是虎而翼者也，其为害岂不多哉！夫德者人之所严，而才者人之所爱；爱者易亲，严者易疏，是以察者多蔽于才而遗于德。自古昔以来，国之乱臣，家之败子，才有余而德不足，以至于顚覆者多矣，岂特智伯哉！故为国为家者苟能审于才德之分而知所先后，又何失人之足患哉！','臣司马光说：智伯智瑶的灭亡，在于才胜过了德。才与德是不同的，但世俗之人没有谁能够分辨清楚，把它们笼统地都叫做贤，这就是人们看错人才的原因。聪明明察、坚强果毅，叫做才；正直公道、中正平和，叫做德。才，是德的凭借；德，是才的统帅。云梦出产的竹子，是天下最刚劲的；然而如果不加以矫正弯曲，不配上箭羽和箭括，就不能穿透坚硬的东西。棠溪出产的金属，是天下最锋利的；然而如果不经过熔铸模具，不加以磨砺，就不能用来击打强敌。因此，才和德都完备的人叫做“圣人”，才和德都丧失的人叫做“愚人”；德胜过才叫做“君子”，才胜过德叫做“小人”。大凡选取人才的原则，如果得不到圣人、君子而加以任用，与其得到小人，还不如得到愚人。为什么呢？君子凭着才能来行善，小人凭着才能来作恶。凭着才能来行善的人，善事没有做不到的；凭着才能来作恶的人，恶事也没有做不到的。愚人虽然也想做坏事，但智谋不能周全，力量不能胜任；譬如小狗扑咬人，人能够把它制服。小人的智谋足以实现他的奸诈，勇力足以促成他的暴虐，这就像老虎又添上了翅膀，他造成的祸害难道还不多吗！德，是人们所敬畏的；才，是人们所喜爱的。令人喜爱的容易亲近，令人敬畏的容易疏远，因此考察人才的人往往被才所蒙蔽而遗漏了德。从古以来，国家的乱臣，家族的败子，才有余而德不足，以至倾覆灭亡的太多了，哪里只是智伯呢！所以治理国家和家族的人，如果能够明察才与德的区别，并且知道谁先谁后，又何必为看错人才而忧虑呢！','[{"type": "胡注", "text": "書·禹貢：雲土夢作乂。孔安國註云：雲夢之澤在江南。左傳：楚王以鄭伯田江南之夢。杜預註云：楚之雲夢跨江南北。班志：雲夢澤在南郡華容縣南。祝穆曰：據左傳䢵夫人弃子文於夢中，言夢而不言雲，楚子避吳入于雲中，言雲而不言夢，則知雲、夢二澤也。漢陽志：雲在江之北，夢在江之南。又安陸有雲夢澤，枝江有雲夢城。蓋古之雲夢澤甚廣，而後世悉爲邑居聚落，故地之以雲夢得名者非一處。竹箭之產，荊楚爲良；雲夢，楚之地也。夢，如字，又莫公翻。", "textJt": "书·禹贡：云土梦作乂。孔安国注云：云梦之泽在江南。左传：楚王以郑伯田江南之梦。杜预注云：楚之云梦跨江南北。班志：云梦泽在南郡华容县南。祝穆曰：据左传䢵夫人弃子文于梦中，言梦而不言云，楚子避吴入于云中，言云而不言梦，则知云、梦二泽也。汉阳志：云在江之北，梦在江之南。又安陆有云梦泽，枝江有云梦城。盖古之云梦泽甚广，而后世悉为邑居聚落，故地之以云梦得名者非一处。竹箭之产，荆楚为良；云梦，楚之地也。梦，如字，又莫公翻。"}, {"type": "胡注", "text": "矯，舉夭翻。揉，如久翻。康曰：揉曲爲矯，揉所以橈曲而使之直也。羽者，箭翎。括者，箭窟受弦處。括，音聒，通作「筈」。", "textJt": "矫，举夭翻。揉，如久翻。康曰：揉曲为矫，揉所以桡曲而使之直也。羽者，箭翎。括者，箭窟受弦处。括，音聒，通作「筈」。"}, {"type": "胡注", "text": "左傳：楚封吳夫槪王於棠谿。戰國之時，其地屬韓，出金甚精利。劉昭郡國志：汝南郡吳房縣有棠谿亭。杜佑通典曰：棠谿在今汝州郾城縣界。九域志：蔡州有冶爐城，韓國鑄劍之地。", "textJt": "左传：楚封吴夫槪王于棠谿。战国之时，其地属韩，出金甚精利。刘昭郡国志：汝南郡吴房县有棠谿亭。杜佑通典曰：棠谿在今汝州郾城县界。九域志：蔡州有冶炉城，韩国铸剑之地。"}, {"type": "胡注", "text": "毛晃曰：鎔，銷也，鑄也；說文：鑄器法也。董仲舒傳：猶金在鎔。註：鎔，謂鑄器之模範。範，法也，式也。禮運：範金合土。砥，軫氏翻，柔石也。礪，力制翻，䃺也。", "textJt": "毛晃曰：镕，销也，铸也；说文：铸器法也。董仲舒传：犹金在镕。注：镕，谓铸器之模范。范，法也，式也。礼运：范金合土。砥，轸氏翻，柔石也。砺，力制翻，䃺也。"}, {"type": "胡注", "text": "挾，戶頰翻。朱元晦曰：挾者，兼有而恃之之稱。勝，音升。乳，儒遇翻，乳育也。乳狗，育子之狗也。搏，伯各翻。", "textJt": "挟，户颊翻。朱元晦曰：挟者，兼有而恃之之称。胜，音升。乳，儒遇翻，乳育也。乳狗，育子之狗也。搏，伯各翻。"}, {"type": "胡注", "text": "虎而傅翼，其爲害也愈甚。", "textJt": "虎而傅翼，其为害也愈甚。"}, {"type": "胡注", "text": "嚴，敬也。", "textJt": "严，敬也。"}]','史论,三家分晋,光,智伯,云梦,棠谿','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(18,'8bf1ccda-db0e-11ef-8fae-a0d3651f611f',1,1,18,'三家分智氏之田。趙襄子漆智伯之頭，以爲飲器。智伯之臣豫讓欲爲之報仇，乃詐爲刑人，挾匕首，入襄子宮中塗廁。襄子如廁心動，索之，獲豫讓。左右欲殺之，襄子曰：「智伯死無後，而此人欲爲報仇，眞義士也，吾謹避之耳。」乃舍之。豫讓又漆身爲癩，吞炭爲啞。行乞於市，其妻不識也。行見其友，其友識之，爲之泣曰：「以子之才，臣事趙孟，必得近幸，子乃爲所欲爲，顧不易邪？何乃自苦如此？求以報仇，不亦難乎！」豫讓曰：「旣已委質爲臣，而又求殺之，是二心也。凡吾所爲者，極難耳。然所以爲此者，將以愧天下後世之爲人臣懷二心者也。」襄子出，豫讓伏於橋下。襄子至橋，馬驚；索之，得豫讓，遂殺之。','三家分智氏之田。赵襄子漆智伯之头，以为饮器。智伯之臣豫让欲为之报仇，乃诈为刑人，挟匕首，入襄子宫中涂厕。襄子如厕心动，索之，获豫让。左右欲杀之，襄子曰：「智伯死无后，而此人欲为报仇，真义士也，吾谨避之耳。」乃舍之。豫让又漆身为癞，吞炭为哑。行乞于市，其妻不识也。行见其友，其友识之，为之泣曰：「以子之才，臣事赵孟，必得近幸，子乃为所欲为，顾不易邪？何乃自苦如此？求以报仇，不亦难乎！」豫让曰：「既已委质为臣，而又求杀之，是二心也。凡吾所为者，极难耳。然所以为此者，将以愧天下后世之为人臣怀二心者也。」襄子出，豫让伏于桥下。襄子至桥，马惊；索之，得豫让，遂杀之。','韩、赵、魏三家瓜分了智氏的土地。赵襄子把智伯瑶的头颅涂上油漆，做成饮酒的器皿。智伯的家臣豫让想替智伯报仇，于是装扮成受过刑的犯人，怀揣匕首，混入赵襄子的宫中涂刷厕所。赵襄子上厕所时心里忽然一动，便让人搜查厕所，抓到了豫让。左右的人要杀死豫让，赵襄子说：“智伯死了又没有后代，这个人还想替他报仇，真是义士啊，我小心回避他就是了。”于是放走了豫让。豫让又在身上涂上漆，使皮肤生满癞疮，又吞下炭使嗓子变哑。他在街市上乞讨，连他的妻子都认不出他。后来他在市上行乞时遇见他的朋友，朋友认出了他，为他的惨状流泪说：“凭你的才能，如果作臣子去事奉赵襄子，必定能得到亲近和宠信，到那时你再去做你想做的报仇之事，难道不是很容易吗？何必这样折磨自己？想寻求报仇，不也太难了吗！”豫让说：“既然已经委身作人家的臣属，却又想杀掉人家，这就是怀有二心。我如今做的这些事，极难做到。然而我之所以这样做，是要让天下后世那些身为人臣却怀有二心的人感到羞愧。”有一天，赵襄子外出，豫让埋伏在桥下。赵襄子到桥上时，拉车的马突然受惊；他命人搜查，抓住了豫让，于是把他杀了。','[{"type": "胡注", "text": "說文：桼，木汁可以䰍物；下從水，象桼如水滴而下也。漢書·張騫傳：匈奴破月氏王，以其頭爲飲器。韋昭註曰：飲器，椑榼也。晉灼曰：飲器，虎子屬也。或曰，飲酒之器也。師古曰：匈奴嘗以月氏王頭與漢使歃血盟，然則飲酒之器是也。韋云椑榼，晉云虎子，皆非也。椑榼，卽今之偏榼，所以盛酒耳，非用飲者也。虎子，褻器，所以溲便者。椑，音鼙。榼，克合翻。氏，音支。使，疏吏翻。歃，色甲翻。盛，時征翻。褻，息列翻。溲，疏鳩翻。便，毘連翻。", "textJt": "说文：桼，木汁可以䰍物；下从水，象桼如水滴而下也。汉书·张骞传：匈奴破月氏王，以其头为饮器。韦昭注曰：饮器，椑榼也。晋灼曰：饮器，虎子属也。或曰，饮酒之器也。师古曰：匈奴尝以月氏王头与汉使歃血盟，然则饮酒之器是也。韦云椑榼，晋云虎子，皆非也。椑榼，即今之偏榼，所以盛酒耳，非用饮者也。虎子，亵器，所以溲便者。椑，音鼙。榼，克合翻。氏，音支。使，疏吏翻。歃，色甲翻。盛，时征翻。亵，息列翻。溲，疏鸠翻。便，毘连翻。"}, {"type": "胡注", "text": "豫，姓也。讓，名也。戰國之時又有豫且，不知其同時否也。爲，音于僞翻；下同。", "textJt": "豫，姓也。让，名也。战国之时又有豫且，不知其同时否也。为，音于伪翻；下同。"}, {"type": "胡注", "text": "挾，持也。劉向曰：匕首，短劍。鹽鐵論曰：匕首長尺八寸；頭類匕，故云匕首。匕，音比。廁，初吏翻，圊也。長，直亮翻。", "textJt": "挟，持也。刘向曰：匕首，短剑。盐铁论曰：匕首长尺八寸；头类匕，故云匕首。匕，音比。厕，初吏翻，圊也。长，直亮翻。"}, {"type": "胡注", "text": "神農日中爲市，致天下之民，聚天下之貨，交易而退，此立市之始也。鄭氏周禮註曰：市，雜聚之處。", "textJt": "神农日中为市，致天下之民，聚天下之货，交易而退，此立市之始也。郑氏周礼注曰：市，杂聚之处。"}, {"type": "胡注", "text": "自春秋之時，趙宣子謂之宣孟，趙文子謂之趙孟，其後遂襲而呼爲趙孟。孟，長也。", "textJt": "自春秋之时，赵宣子谓之宣孟，赵文子谓之赵孟，其后遂袭而呼为赵孟。孟，长也。"}, {"type": "胡注", "text": "經典釋文曰：質，職日翻。委質，委其體以事君也。後漢書註：委質，屈膝。", "textJt": "经典释文曰：质，职日翻。委质，委其体以事君也。后汉书注：委质，屈膝。"}, {"type": "胡注", "text": "自智宣子立瑤，至豫讓報仇，其事皆在威烈王二十三年之前，故先以「初」字發之。溫公之意，蓋以天下莫大於名分，觀命三大夫爲諸侯之事，則知周之所以益微，七雄之所以益盛；莫重於宗社，觀智、趙立後之事，則知智宣子之所以失，趙簡子之所以得；君臣之義當守節伏死而已，觀豫讓之事，則知策名委質者必有霣而無貳。其爲後世之鑑，豈不昭昭也哉！", "textJt": "自智宣子立瑶，至豫让报仇，其事皆在威烈王二十三年之前，故先以「初」字发之。温公之意，盖以天下莫大于名分，观命三大夫为诸侯之事，则知周之所以益微，七雄之所以益盛；莫重于宗社，观智、赵立后之事，则知智宣子之所以失，赵简子之所以得；君臣之义当守节伏死而已，观豫让之事，则知策名委质者必有𫕥而无贰。其为后世之鉴，岂不昭昭也哉！"}]','人事,权争,晋阳之战（三家灭智）,智氏,赵襄子,智伯,豫让,襄子,赵孟','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(19,'8bf4033f-db0e-11ef-a48f-a0d3651f611f',1,1,19,'襄子爲伯魯之不立也，有子五人，不肯置後。封伯魯之子於代，曰代成君，早卒；立其子浣爲趙氏後。襄子卒，弟桓子逐浣而自立；一年卒。趙氏之人曰：「桓子立非襄主意。」乃共殺其子，復迎浣而立之，是爲獻子。獻子生籍，是爲烈侯。魏斯者，魏桓子之孫也，是爲文侯。韓康子生武子；武子生虔，是爲景侯。','襄子为伯鲁之不立也，有子五人，不肯置后。封伯鲁之子于代，曰代成君，早卒；立其子浣为赵氏后。襄子卒，弟桓子逐浣而自立；一年卒。赵氏之人曰：「桓子立非襄主意。」乃共杀其子，复迎浣而立之，是为献子。献子生籍，是为烈侯。魏斯者，魏桓子之孙也，是为文侯。韩康子生武子；武子生虔，是为景侯。','赵襄子因为哥哥伯鲁当年未能被父亲立为继承人，自己虽有五个儿子，却不肯立他们为继承人。他把伯鲁的儿子封在代地，号称代成君；代成君早死，又立代成君的儿子赵浣为赵氏继承人。赵襄子去世后，他的弟弟赵桓子（《史记》记载赵桓子是赵襄子的同母弟，《世本》记载赵桓子是赵襄子之子，目前大多同意后者）驱逐了赵浣，自立为赵氏主君；在位一年就死了。赵氏族人说：“桓子自立，并不是赵襄子主君的本意。”于是族人共同杀了桓子的儿子，又迎回赵浣立为赵氏之主，这就是赵献子。赵献子生赵籍，就是赵烈侯。魏斯，是魏桓子的孙子，就是魏文侯。韩康子生韩武子；韩武子生韩虔，就是韩景侯。','[{"type": "胡注", "text": "代國在夏屋句注之北，趙襄子滅之。班志有代郡代縣。爲，于僞翻。夏，戶雅翻。", "textJt": "代国在夏屋句注之北，赵襄子灭之。班志有代郡代县。为，于伪翻。夏，户雅翻。"}, {"type": "胡注", "text": "成，諡也。諡法：安民立政曰成。", "textJt": "成，谥也。谥法：安民立政曰成。"}, {"type": "胡注", "text": "史記·六國表，威烈王元年，襄子卒；二年，趙桓子元年，卒；明年，國人立獻侯浣。「浣」，索隱作「晚」。卒，子恤翻；下同。", "textJt": "史记·六国表，威烈王元年，襄子卒；二年，赵桓子元年，卒；明年，国人立献侯浣。「浣」，索隐作「晚」。卒，子恤翻；下同。"}, {"type": "胡注", "text": "復，扶又翻；又音如字。獻子，卽獻侯。六國表：威烈王三年，獻侯之元年。蓋分晉之後，三晉僭侯久矣。諡法：知質有聖曰獻。", "textJt": "复，扶又翻；又音如字。献子，即献侯。六国表：威烈王三年，献侯之元年。盖分晋之后，三晋僭侯久矣。谥法：知质有圣曰献。"}, {"type": "胡注", "text": "諡法：有功安民曰烈；秉德尊業曰烈。", "textJt": "谥法：有功安民曰烈；秉德尊业曰烈。"}, {"type": "胡注", "text": "諡法：學勤好問曰文；慈惠安民曰文。", "textJt": "谥法：学勤好问曰文；慈惠安民曰文。"}, {"type": "胡注", "text": "諡法：克定禍亂曰武；布義行剛曰景。六國表：威烈王二年，魏文侯斯元年；十八年，韓景侯虔元年。蓋其在國僭爵已久，不敢以通王室；威烈王遂因而命之，識者重爲周惜。通鑑於此序三家之世也。", "textJt": "谥法：克定祸乱曰武；布义行刚曰景。六国表：威烈王二年，魏文侯斯元年；十八年，韩景侯虔元年。盖其在国僭爵已久，不敢以通王室；威烈王遂因而命之，识者重为周惜。通鉴于此序三家之世也。"}]','权争,三家分晋,襄子,伯鲁,代成君,浣,赵氏,桓子,襄主,献子,籍,烈侯,魏斯,魏桓子,文侯,韩康子,武子,虔,景侯,代','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(20,'8bf42ab2-db0e-11ef-80a0-a0d3651f611f',1,1,20,'魏文侯以卜子夏、田子方爲師。每過段干木之廬必式。四方賢士多歸之。','魏文侯以卜子夏、田子方为师。每过段干木之庐必式。四方贤士多归之。','魏文侯魏斯尊崇卜子夏、田子方为老师。他每次经过段干木的庐舍，一定手扶车轼俯首致敬。四方贤士因此多来归附他。','[{"type": "胡注", "text": "卜，以官爲氏。田本出於陳，陳敬仲以陳爲田氏。徐廣曰：始食采地，由是改姓田氏。索隱曰：陳、田二聲相近，遂爲田氏。夏，戶雅翻。", "textJt": "卜，以官为氏。田本出于陈，陈敬仲以陈为田氏。徐广曰：始食采地，由是改姓田氏。索隐曰：陈、田二声相近，遂为田氏。夏，户雅翻。"}, {"type": "胡注", "text": "過，工禾翻。唐人志氏族曰：李耳，字伯陽，一字耼；其後有李宗，魏封於段，爲干木大夫，是以段爲氏也。余按：通鑑赧王四十二年，魏有段干子，則段干，複姓也。書：武王式商容閭。註云：式其閭巷，以禮賢。記·曲禮：國君撫式，士下之。註云：升車必正立，據式小俛，崇敬也。師古曰：式，車前橫木。古者立乘；凡言式車者，謂俛首撫式，以禮敬人。孔穎達曰：式，謂俯下頭也。古者車箱長四尺四寸而三分，前一後二，橫一木，下去車牀三尺三寸，謂之爲式；又於式上二尺二寸橫一木，謂之較，較去車牀凡五尺五寸。於時立乘，若平常則憑較，故詩云「倚重較兮」是也。若應爲敬，則落隱下式，而頭得俯俛，故記云「式視馬尾」是也。較，訖岳翻。", "textJt": "过，工禾翻。唐人志氏族曰：李耳，字伯阳，一字耼；其后有李宗，魏封于段，为干木大夫，是以段为氏也。余按：通鉴赧王四十二年，魏有段干子，则段干，复姓也。书：武王式商容闾。注云：式其闾巷，以礼贤。记·曲礼：国君抚式，士下之。注云：升车必正立，据式小俛，崇敬也。师古曰：式，车前横木。古者立乘；凡言式车者，谓俛首抚式，以礼敬人。孔颖达曰：式，谓俯下头也。古者车箱长四尺四寸而三分，前一后二，横一木，下去车床三尺三寸，谓之为式；又于式上二尺二寸横一木，谓之较，较去车床凡五尺五寸。于时立乘，若平常则凭较，故诗云「倚重较兮」是也。若应为敬，则落隐下式，而头得俯俛，故记云「式视马尾」是也。较，讫岳翻。"}]','人事,魏文侯,卜子夏,田子方,段干木','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(21,'8bf42adc-db0e-11ef-b8bc-a0d3651f611f',1,1,21,'文侯與羣臣飲酒，樂，而天雨，命駕將適野。左右曰：「今日飲酒樂，天又雨，君將安之？」文侯曰：「吾與虞人期獵，雖樂，豈可無一會期哉？」乃往，身自罷之。','文侯与群臣饮酒，乐，而天雨，命驾将适野。左右曰：「今日饮酒乐，天又雨，君将安之？」文侯曰：「吾与虞人期猎，虽乐，岂可无一会期哉？」乃往，身自罢之。','魏文侯与群臣饮酒，十分畅快，这时天却下起雨来，魏文侯下令备好车驾，准备前往郊外。左右侍从问道：“今天饮酒正快乐，何况天又下起了雨，主君要到哪里去呢？”魏文侯说：“我已经和管山林的虞人约好打猎，虽然现在快乐，又怎么能不守这一次约定呢？”于是乘车前往，亲自向虞人说明，因下雨取消了这次打猎。','[{"type": "胡注", "text": "周禮有山虞、澤虞，以掌山澤。註云：虞，度也，度知山林之大小及其所生。身自罷之者，身往告之，以雨而罷獵也。樂，音洛。", "textJt": "周礼有山虞、泽虞，以掌山泽。注云：虞，度也，度知山林之大小及其所生。身自罢之者，身往告之，以雨而罢猎也。乐，音洛。"}]','文侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(22,'8bf42ae2-db0e-11ef-91ad-a0d3651f611f',1,1,22,'韓借師於魏以伐趙，文侯曰：「寡人與趙，兄弟也，不敢聞命。」趙借師於魏以伐韓，文侯應之亦然。二國皆怒而去。已而知文侯以講於己也，皆朝于魏。魏於是始大於三晉，諸侯莫能與之爭。','韩借师于魏以伐赵，文侯曰：「寡人与赵，兄弟也，不敢闻命。」赵借师于魏以伐韩，文侯应之亦然。二国皆怒而去。已而知文侯以讲于己也，皆朝于魏。魏于是始大于三晋，诸侯莫能与之争。','韩国派人向魏国借兵去攻打赵国，魏文侯说：“我与赵国是兄弟之国，不敢听从你们这一请求。”赵国也派人向魏国借兵去攻打韩国，魏文侯也用同样的话答复了赵国。韩、赵两国使者都愤怒地离去。不久，两国得知魏文侯是在以善意对待自己，便都到魏国朝见。魏国从此在三晋中开始成为最强国，诸侯没有谁能与它争雄。','[{"type": "胡注", "text": "講，和也。", "textJt": "讲，和也。"}]','外交,文侯,韩,魏,赵,三晋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(23,'8bf42af2-db0e-11ef-899a-a0d3651f611f',1,1,23,'使樂羊伐中山，克之；以封其子擊。文侯問於羣臣曰：「我何如主？」皆曰：「仁君。」任座曰：「君得中山，不以封君之弟而以封君之子，何謂仁君！」文侯怒，任座趨出。次問翟璜，對曰：「仁君。」文侯曰：「何以知之？」對曰：「臣聞君仁則臣直。嚮者任座之言直，臣是以知之。」文侯悅，使翟璜召任座而反之，親下堂迎之，以爲上客。','使乐羊伐中山，克之；以封其子击。文侯问于群臣曰：「我何如主？」皆曰：「仁君。」任座曰：「君得中山，不以封君之弟而以封君之子，何谓仁君！」文侯怒，任座趋出。次问翟璜，对曰：「仁君。」文侯曰：「何以知之？」对曰：「臣闻君仁则臣直。向者任座之言直，臣是以知之。」文侯悦，使翟璜召任座而反之，亲下堂迎之，以为上客。','魏文侯派乐羊攻打中山国，攻克了它；把它封给自己的儿子魏击。魏文侯问群臣说：“我是怎样的君主？”大家都说：“是仁君。”任座说：“您取得了中山，不把它封给您的弟弟，却封给自己的儿子，怎么能说是仁君！”魏文侯大怒，任座急忙退出朝堂。魏文侯接着问翟璜，翟璜回答说：“是仁君。”魏文侯问：“你凭什么知道我是仁君？”翟璜回答说：“我听说国君仁爱，臣子就正直。刚才任座的话正直，我因此知道您是仁君。”魏文侯很高兴，派翟璜去召任座回朝堂，并亲自下堂迎接他，待他为上客。','[{"type": "胡注", "text": "樂，姓也。本自有殷微子之後。宋戴公四世孫樂呂爲大司寇。中山，春秋之鮮虞也，漢爲中山郡。宋白曰：唐定州，春秋白狄鮮虞之地。隋圖經曰：中山城在今唐昌縣東北三十一里，中山故城是也。杜佑曰：城中有山，故曰中山。", "textJt": "乐，姓也。本自有殷微子之后。宋戴公四世孙乐吕为大司寇。中山，春秋之鲜虞也，汉为中山郡。宋白曰：唐定州，春秋白狄鲜虞之地。隋图经曰：中山城在今唐昌县东北三十一里，中山故城是也。杜佑曰：城中有山，故曰中山。"}, {"type": "胡注", "text": "任座亦習見當時鄰國之事而爲是言耳。任，音壬。「座」一作「痤」，音才戈翻。", "textJt": "任座亦习见当时邻国之事而为是言耳。任，音壬。「座」一作「痤」，音才戈翻。"}, {"type": "胡注", "text": "翟，姓也，音直格翻，又音狄。姓譜：翟爲晉所滅，子孫以國爲氏。今人多讀從上音。璜，戶光翻。", "textJt": "翟，姓也，音直格翻，又音狄。姓谱：翟为晋所灭，子孙以国为氏。今人多读从上音。璜，户光翻。"}]','人事,内政,魏灭中山之战,乐羊,击,文侯,任座,翟璜,中山','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(24,'8bf42b1f-db0e-11ef-8a56-a0d3651f611f',1,1,24,'文侯與田子方飲，文侯曰：「鍾聲不比乎？左高。」田子方笑。文侯曰：「何笑？」子方曰：「臣聞之，君明樂官，不明樂音。今君審於音，臣恐其聾於官也。」文侯曰：「善。」','文侯与田子方饮，文侯曰：「钟声不比乎？左高。」田子方笑。文侯曰：「何笑？」子方曰：「臣闻之，君明乐官，不明乐音。今君审于音，臣恐其聋于官也。」文侯曰：「善。」','魏文侯和田子方一起饮酒，魏文侯说：“编钟的声音好像不和谐，左边的音偏高。”田子方听后笑了。魏文侯问：“你笑什么？”田子方说：“臣听说，国君应当明察并追究乐官，不必去审订乐音。现在您对乐音明察秋毫，我担心您对乐官的管理会松懈失察。”魏文侯说：“你说得好。”','[{"type": "胡注", "text": "比，音毗。不比，言不和也。", "textJt": "比，音毗。不比，言不和也。"}, {"type": "胡注", "text": "此蓋編鍾之懸，左高，故其聲不和。", "textJt": "此盖编钟之悬，左高，故其声不和。"}, {"type": "胡注", "text": "明樂官，知其才不才；明樂音，知其和不和。五聲合和，然後成音。詩·大序曰：聲成文，謂之音。", "textJt": "明乐官，知其才不才；明乐音，知其和不和。五声合和，然后成音。诗·大序曰：声成文，谓之音。"}]','内政,文侯,田子方,子方','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(25,'8bf67664-db0e-11ef-b8a4-a0d3651f611f',1,1,25,'子擊出，遭田子方於道，下車伏謁。子方不爲禮。子擊怒，謂子方曰：「富貴者驕人乎？貧賤者驕人乎？」子方曰：「亦貧賤者驕人耳，富貴者安敢驕人！國君而驕人則失其國，大夫而驕人則失其家。失其國者未聞有以國待之者也，失其家者未聞有以家待之者也。夫士貧賤者，言不用，行不合，則納履而去耳，安往而不得貧賤哉！」子擊乃謝之。','子击出，遭田子方于道，下车伏谒。子方不为礼。子击怒，谓子方曰：「富贵者骄人乎？贫贱者骄人乎？」子方曰：「亦贫贱者骄人耳，富贵者安敢骄人！国君而骄人则失其国，大夫而骄人则失其家。失其国者未闻有以国待之者也，失其家者未闻有以家待之者也。夫士贫贱者，言不用，行不合，则纳履而去耳，安往而不得贫贱哉！」子击乃谢之。','魏文侯的儿子魏击一次外出，在路上遇到田子方，便下车伏地拜见问好。田子方却不回礼。魏击大怒，对田子方说：“是富贵的人能傲慢待人呢，还是贫贱的人能傲慢待人呢？”田子方说：“只是贫贱的人才能对人傲慢罢了，富贵的人哪里敢对人傲慢呢！身为国君如果傲慢待人，就会失去他的国家；身为大夫如果傲慢待人，就会失去他的封邑。失去国家的人，从没听说有人会以国君之礼对待他；失去封邑的人，也从没听说有人会以大夫之礼对待他。至于那些贫贱的士人，进言不被采用，行事不合人意，就穿上鞋子离开罢了，到哪里还不都是贫贱呢！”魏击于是向田子方道歉。','[{"type": "胡注", "text": "古文史考曰：黃帝作車，引重致遠；少昊氏加牛；禹時奚仲加馬。釋名曰：車，居也。韋昭曰：古唯尺遮翻，自漢以來，始有「居」音。蕭子顯曰：三皇氏乘祇車出谷口，車之始也。祇，翹移翻。", "textJt": "古文史考曰：黄帝作车，引重致远；少昊氏加牛；禹时奚仲加马。释名曰：车，居也。韦昭曰：古唯尺遮翻，自汉以来，始有「居」音。萧子显曰：三皇氏乘祇车出谷口，车之始也。祇，翘移翻。"}]','人事,子击,田子方,子方','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(26,'8bf67679-db0e-11ef-b621-a0d3651f611f',1,1,26,'文侯謂李克曰：「先生嘗有言曰：『家貧思良妻，國亂思良相。』今所置非成則璜，二子何如？」對曰：「卑不謀尊，疏不謀戚。臣在闕門之外，不敢當命。」文侯曰：「先生臨事勿讓！」克曰：「君弗察故也。居視其所親，富視其所與，達視其所舉，窮視其所不爲，貧視其所不取，五者足以定之矣，何待克哉！」文侯曰：「先生就舍，吾之相定矣。」李克出，見翟璜。翟璜曰：「今者聞君召先生而卜相，果誰爲之？」克曰：「魏成。」翟璜忿然作色曰：「西河守吳起，臣所進也。君內以鄴爲憂，臣進西門豹。君欲伐中山，臣進樂羊。中山已拔，無使守之，臣進先生。君之子無傅，臣進屈侯鮒。以耳目之所睹記，臣何負於魏成！」李克曰：「子言克於子之君者，豈將比周以求大官哉？君問相於克，克之對如是。所以知君之必相魏成者，魏成食祿千鍾，什九在外，什一在內；是以東得卜子夏、田子方、段干木。此三人者，君皆師之；子所進五人者，君皆臣之。子惡得與魏成比也！」翟璜逡巡再拜曰：「璜，鄙人也，失對，願卒爲子弟！」','文侯谓李克曰：「先生尝有言曰：『家贫思良妻，国乱思良相。』今所置非成则璜，二子何如？」对曰：「卑不谋尊，疏不谋戚。臣在阙门之外，不敢当命。」文侯曰：「先生临事勿让！」克曰：「君弗察故也。居视其所亲，富视其所与，达视其所举，穷视其所不为，贫视其所不取，五者足以定之矣，何待克哉！」文侯曰：「先生就舍，吾之相定矣。」李克出，见翟璜。翟璜曰：「今者闻君召先生而卜相，果谁为之？」克曰：「魏成。」翟璜忿然作色曰：「西河守吴起，臣所进也。君内以邺为忧，臣进西门豹。君欲伐中山，臣进乐羊。中山已拔，无使守之，臣进先生。君之子无傅，臣进屈侯鲋。以耳目之所睹记，臣何负于魏成！」李克曰：「子言克于子之君者，岂将比周以求大官哉？君问相于克，克之对如是。所以知君之必相魏成者，魏成食禄千钟，什九在外，什一在内；是以东得卜子夏、田子方、段干木。此三人者，君皆师之；子所进五人者，君皆臣之。子恶得与魏成比也！」翟璜逡巡再拜曰：「璜，鄙人也，失对，愿卒为子弟！」','魏文侯对李克说：“先生曾经说过：‘家贫时想着良妻，国乱时想着良相。’现在所要选任的国相，不是魏成就是翟璜，你看两人怎么样？”李克回答说：“地位卑下的人不谋议尊上的事，关系疏远的人不谋议亲近者的事。臣身在宫门之外，不敢参与议论。”魏文侯说：“先生遇到国事就不要推辞了！”李克说：“这是您没有仔细考察的缘故。平时看他亲近什么人，富有时看他交往什么人，显达时看他举荐什么人，困厄时看他不肯做什么，贫穷时看他不拿取什么。这五点就足以确定国相了，哪里用得着等我李克来定呢！”魏文侯说：“先生请回府吧，我的国相已经定了。”李克出来后，见到翟璜。翟璜问道：“刚才听说主君召先生去商议国相人选，到底定了谁做国相？”李克说：“魏成。”翟璜立刻气得变了脸色，说：“西河守吴起，是我举荐的；主君为国内的邺地忧虑，我举荐了西门豹；主君想攻伐中山，我举荐了乐羊；中山攻下之后，没有人可派去镇守，我举荐了先生；主君的儿子没有师傅，我举荐了屈侯鲋。凭这些耳闻目睹的事实，我哪里比不上魏成！”李克说：“你向主君推荐我李克，难道是为了结党营私来求取大官吗？主君向我询问国相人选，我就是这样回答的。我之所以知道主君必定会让魏成做国相，是因为魏成享受千钟俸禄，十分之九用在外面结交贤士，十分之一才用在家里；因此他在东边得到了卜子夏、田子方、段干木。这三个人，主君都当作老师；你所举荐的五个人，主君都当作臣下。你怎么能和魏成相比呢！”翟璜惭愧不安地拜了两拜说：“我翟璜是个鄙陋的人，方才答对失礼，情愿终身做先生的弟子！”','[{"type": "胡注", "text": "李氏出自顓頊曾孫皋陶，爲堯大理，以官命族爲理氏。商紂時，裔孫利貞逃難，食木子得全，改爲李氏。置，言置相也。相，息亮翻。難，乃旦翻。", "textJt": "李氏出自颛顼曾孙皋陶，为尧大理，以官命族为理氏。商纣时，裔孙利贞逃难，食木子得全，改为李氏。置，言置相也。相，息亮翻。难，乃旦翻。"}, {"type": "胡注", "text": "在闕門之外，謂疏遠也。", "textJt": "在阙门之外，谓疏远也。"}, {"type": "胡注", "text": "班志：魏地，其界自高陵以東，盡河東、河內。高陵縣，漢屬馮翊，其地在河西，所謂「西河之外」者也。魏初使吳起守之，秦兵不敢東向。至惠王時，秦使衞鞅擊虜其將公子卬，遂獻西河之外於秦。吳，以國爲姓。相，息亮翻。守，式又翻。", "textJt": "班志：魏地，其界自高陵以东，尽河东、河内。高陵县，汉属冯翊，其地在河西，所谓「西河之外」者也。魏初使吴起守之，秦兵不敢东向。至惠王时，秦使衞鞅击虏其将公子卬，遂献西河之外于秦。吴，以国为姓。相，息亮翻。守，式又翻。"}, {"type": "胡注", "text": "班志，鄴縣屬魏郡。西門豹爲鄴令，鑿渠以利民。王符潛夫論·姓氏篇曰：如有東門、西郭、南宮、北郭，皆因居以爲姓。西門蓋亦此類。鄴，魚怯翻。", "textJt": "班志，邺县属魏郡。西门豹为邺令，凿渠以利民。王符潜夫论·姓氏篇曰：如有东门、西郭、南宫、北郭，皆因居以为姓。西门盖亦此类。邺，鱼怯翻。"}, {"type": "胡注", "text": "傅者，傅之以德義，因以爲官名。傅，芳遇翻。屈，九勿翻，姓也。余按屈，晉地，時屬魏；鮒蓋魏封屈侯也。鮒，音符遇翻。", "textJt": "傅者，傅之以德义，因以为官名。傅，芳遇翻。屈，九勿翻，姓也。余按屈，晋地，时属魏；鲋盖魏封屈侯也。鲋，音符遇翻。"}, {"type": "胡注", "text": "不勝爲負。", "textJt": "不胜为负。"}, {"type": "胡注", "text": "比，毗至翻。阿黨爲比。", "textJt": "比，毗至翻。阿党为比。"}, {"type": "胡注", "text": "李克自叙其答魏文侯之言也。", "textJt": "李克自叙其答魏文侯之言也。"}, {"type": "胡注", "text": "孔穎達曰：祿者，穀也。故鄭註司祿云：祿也言穀，年穀豐然後制祿。授神契云：祿者，錄也。白虎通曰：上以收錄接下，下以名錄謹以事上是也。六斛四斗爲一鍾。", "textJt": "孔颖达曰：禄者，谷也。故郑注司禄云：禄也言谷，年谷丰然后制禄。授神契云：禄者，录也。白虎通曰：上以收录接下，下以名录谨以事上是也。六斛四斗为一钟。"}, {"type": "胡注", "text": "逡，七倫翻。逡巡，却退貌。卒，子恤翻，終也。孔穎達曰：先生，師也。謂師爲先生者，言彼先己而生，其德多厚也。自稱爲弟子者，言己自處如弟子，則尊其師如父兄也。", "textJt": "逡，七伦翻。逡巡，却退貌。卒，子恤翻，终也。孔颖达曰：先生，师也。谓师为先生者，言彼先己而生，其德多厚也。自称为弟子者，言己自处如弟子，则尊其师如父兄也。"}]','人事,文侯,李克,成,璜,克,翟璜,魏成,吴起,西门豹,乐羊,屈侯鲋,卜子夏,田子方,段干木,西河,邺,中山,相,西河守,傅','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(27,'8bf7ce8f-db0e-11ef-b7ae-a0d3651f611f',1,1,27,'吳起者，衞人，仕於魯。齊人伐魯，魯人欲以爲將，起取齊女爲妻，魯人疑之，起殺妻以求將，大破齊師。或譖之魯侯曰：「起始事曾參，母死不奔喪，曾參絕之；今又殺妻以求爲君將。起，殘忍薄行人也！且以魯國區區而有勝敵之名，則諸侯圖魯矣。」起恐得罪，聞魏文侯賢，乃往歸之。文侯問諸李克，李克曰：「起貪而好色；然用兵，司馬穰苴弗能過也。」於是文侯以爲將，擊秦，拔五城。','吴起者，衞人，仕于鲁。齐人伐鲁，鲁人欲以为将，起取齐女为妻，鲁人疑之，起杀妻以求将，大破齐师。或谮之鲁侯曰：「起始事曾参，母死不奔丧，曾参绝之；今又杀妻以求为君将。起，残忍薄行人也！且以鲁国区区而有胜敌之名，则诸侯图鲁矣。」起恐得罪，闻魏文侯贤，乃往归之。文侯问诸李克，李克曰：「起贪而好色；然用兵，司马穰苴弗能过也。」于是文侯以为将，击秦，拔五城。','吴起是卫国人，在鲁国做官。齐国攻打鲁国，鲁国想任用吴起为将，但吴起娶齐国女子为妻，鲁国人因此怀疑他；吴起便杀死妻子来求取将领之位，大败齐军。有人在鲁侯面前诋毁他说：“吴起起初事奉曾参时，母亲死了也不回去奔丧，曾参因此与他断绝关系并赶走了他；如今他又杀死妻子来求取做您的将领。吴起，真是个残忍刻薄的人！况且，以小小的鲁国有了战胜敌国的名声，诸侯们就会图谋鲁国了。”吴起害怕获罪，听说魏文侯贤明，便前去归附。魏文侯向李克询问吴起的为人，李克说：“吴起贪婪而且好色；但论用兵，司马穰苴也不能超过他。”于是魏文侯任命吴起为将，攻打秦国，夺取了五座城池。','[{"type": "胡注", "text": "將，卽亮翻；下同。取，讀曰娶。孔穎達曰：妻之爲言齊也；以禮見問，得與夫敵體也。", "textJt": "将，即亮翻；下同。取，读曰娶。孔颖达曰：妻之为言齐也；以礼见问，得与夫敌体也。"}, {"type": "胡注", "text": "世本曰：曾姓出自鄫國。陸德明曰：參，所金翻，一音七南翻。", "textJt": "世本曰：曾姓出自鄫国。陆德明曰：参，所金翻，一音七南翻。"}, {"type": "胡注", "text": "司馬，官名。穰苴本齊田姓，仕齊爲是官，故以稱之；齊景公之賢將也。穰，如羊翻。苴，子余翻。", "textJt": "司马，官名。穰苴本齐田姓，仕齐为是官，故以称之；齐景公之贤将也。穰，如羊翻。苴，子余翻。"}]','人事,军事,吴起,起,鲁侯,曾参,魏文侯,文侯,李克,司马穰苴,衞,鲁,齐,鲁国,秦,將','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(28,'8bf8ca21-db0e-11ef-9739-a0d3651f611f',1,1,28,'起之爲將，與士卒最下者同衣食，臥不設席，行不騎乘，親裹贏糧，與士卒分勞苦。卒有病疽者，起爲吮之。卒母聞而哭之。人曰：「子，卒也，而將軍自吮其疽，何哭爲？」母曰：「非然也。往年吳公吮其父疽，其父戰不旋踵，遂死於敵。吳公今又吮其子，妾不知其死所矣，是以哭之。」','起之为将，与士卒最下者同衣食，卧不设席，行不骑乘，亲裹赢粮，与士卒分劳苦。卒有病疽者，起为吮之。卒母闻而哭之。人曰：「子，卒也，而将军自吮其疽，何哭为？」母曰：「非然也。往年吴公吮其父疽，其父战不旋踵，遂死于敌。吴公今又吮其子，妾不知其死所矣，是以哭之。」','吴起担任将领时，与最下等的士兵穿一样的衣服、吃一样的饭食，睡觉不铺设席垫，行军不骑马、不乘车，亲自包裹并背负军粮，与士兵分担劳苦。士兵中有患痈疽的，吴起替他吸吮脓血。士兵的母亲听说后为此痛哭。有人问她：“你的儿子只是个士兵，将军却亲自为他吸吮痈疽，你为什么还要哭呢？”母亲说：“不是这样的。往年吴公吸吮过他父亲的痈疽，他父亲作战时勇往直前、从不后退，最终被敌人杀死。吴公如今又吸吮我儿子的痈疽，我不知道他又会死在哪里，因此才哭。”','[{"type": "胡注", "text": "騎馬爲騎，乘車爲乘，言起與士卒同其勞苦，行不用車馬也。", "textJt": "骑马为骑，乘车为乘，言起与士卒同其劳苦，行不用车马也。"}, {"type": "胡注", "text": "師古曰：贏，擔也。此言起親裹士卒所齎擔之糧。贏，怡成翻。", "textJt": "师古曰：赢，担也。此言起亲裹士卒所赍担之粮。赢，怡成翻。"}, {"type": "胡注", "text": "疽，七余翻，癰也。吮，徐兗翻；說文：嗽也，康：所角切。", "textJt": "疽，七余翻，痈也。吮，徐兖翻；说文：嗽也，康：所角切。"}]','人事,起,吴公,將,將軍','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(29,'8bf8ca32-db0e-11ef-8b19-a0d3651f611f',1,1,29,'燕湣公薨，子僖公立。','燕湣公薨，子僖公立。','燕湣公去世，其子燕僖公即位。','[{"type": "胡注", "text": "燕自召公奭受封於北燕，其地則唐幽州薊縣故城是也。自召公至湣公三十二世。燕，因肩翻。湣，讀與閔同。諡法：使民悲傷曰閔；小心畏忌曰僖。", "textJt": "燕自召公奭受封于北燕，其地则唐幽州蓟县故城是也。自召公至湣公三十二世。燕，因肩翻。湣，读与闵同。谥法：使民悲伤曰闵；小心畏忌曰僖。"}]','内政,燕湣公,僖公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8be19ea3-db0e-11ef-bc29-a0d3651f611f',CURRENT_TIMESTAMP),
(30,'8bf8ca41-db0e-11ef-827c-a0d3651f611f',2,1,30,'王崩，子安王驕立。','王崩，子安王骄立。','周威烈王驾崩，他的儿子周安王姬骄即位。',NULL,'内政,安王,骄','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bf8ca3f-db0e-11ef-901b-a0d3651f611f',CURRENT_TIMESTAMP),
(31,'8bf8ca44-db0e-11ef-916c-a0d3651f611f',2,1,31,'盜殺楚聲王，國人立其子悼王。','盗杀楚声王，国人立其子悼王。','强盗杀死楚国声王，楚国人拥立他的儿子即位，是为悼王。','[{"type": "胡注", "text": "周成王封熊繹於楚，姓羋氏，居丹陽，今枝江縣故丹陽城是也。括地志曰：歸州秭歸縣丹陽城，熊繹之始國。其後強大，北封畛於汝，南幷吳、越，地方五千里。自熊繹至聲王三十世。索隱曰：聲王，名當。悼王，名疑。諡法：不生其國曰聲。註云：生於外家。年中早夭曰悼。註云：年不稱志。又云：恐懼從處曰悼。註云：從處，言險圮也。", "textJt": "周成王封熊绎于楚，姓芈氏，居丹阳，今枝江县故丹阳城是也。括地志曰：归州秭归县丹阳城，熊绎之始国。其后强大，北封畛于汝，南幷吴、越，地方五千里。自熊绎至声王三十世。索隐曰：声王，名当。悼王，名疑。谥法：不生其国曰声。注云：生于外家。年中早夭曰悼。注云：年不称志。又云：恐惧从处曰悼。注云：从处，言险圮也。"}]','权争,楚声王,悼王','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bf8ca3f-db0e-11ef-901b-a0d3651f611f',CURRENT_TIMESTAMP),
(32,'8bf8ca66-db0e-11ef-8b87-a0d3651f611f',3,1,32,'秦伐魏，至陽孤。','秦伐魏，至阳孤。','秦国攻打魏国，进抵阳孤。','[{"type": "胡注", "text": "周孝王邑非子於秦。徐廣曰：今隴西縣秦亭是也。括地志曰：秦州清水縣本名秦。十三州志曰：秦亭，秦谷是也。至襄公取周地，穆公霸西戎，日以強大。是年，秦簡公之十四年也。自非子至簡公二十八世。「陽孤」，史記作「陽狐」。正義引括地志曰：陽狐郭在魏州元城縣東北三十里。余按此時西河之外皆爲魏境，若秦兵至元城，則是越魏都安邑而東矣。水經註：河東垣縣有陽壺城。九域志：絳州有陽壺城。識之以廣異聞，且俟知者。", "textJt": "周孝王邑非子于秦。徐广曰：今陇西县秦亭是也。括地志曰：秦州清水县本名秦。十三州志曰：秦亭，秦谷是也。至襄公取周地，穆公霸西戎，日以强大。是年，秦简公之十四年也。自非子至简公二十八世。「阳孤」，史记作「阳狐」。正义引括地志曰：阳狐郭在魏州元城县东北三十里。余按此时西河之外皆为魏境，若秦兵至元城，则是越魏都安邑而东矣。水经注：河东垣县有阳壶城。九域志：绛州有阳壶城。识之以广异闻，且俟知者。"}]','军事,秦,魏,阳孤','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bf8ca64-db0e-11ef-85aa-a0d3651f611f',CURRENT_TIMESTAMP),
(33,'8bfa3218-db0e-11ef-badc-a0d3651f611f',4,1,33,'魏、韓、趙伐楚，至桑丘。','魏、韩、赵伐楚，至桑丘。','魏国、韩国、赵国联合攻打楚国，攻进桑丘。','[{"type": "胡注", "text": "水經註：澺水自葛陂東南逕新蔡縣故城東，而東南流注于汝水；又東南逕下桑里，左迆爲橫塘陂。史記作「乘丘」。正義：地理志，乘丘故城在兗州瑕丘縣西北三十五里。當從之。", "textJt": "水经注：澺水自葛陂东南迳新蔡县故城东，而东南流注于汝水；又东南迳下桑里，左迆为横塘陂。史记作「乘丘」。正义：地理志，乘丘故城在兖州瑕丘县西北三十五里。当从之。"}]','军事,魏,韩,赵,楚,桑丘','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfa3216-db0e-11ef-89da-a0d3651f611f',CURRENT_TIMESTAMP),
(34,'8bfa322c-db0e-11ef-9e20-a0d3651f611f',4,1,34,'鄭圍韓陽翟。','郑围韩阳翟。','郑国围攻韩国阳翟。','[{"type": "胡注", "text": "周宣王封其弟友於鄭。杜預世族譜曰：封於咸林，今京兆鄭邑是也。幽王無道，友徙其人於虢、鄶之間，遂有其地，今河南新鄭是也。友，諡桓公。是年，鄭繻公駘之二十三年。自桓公至繻公二十二世。班志，陽翟縣屬潁川郡。索隱曰：翟，音狄，溫公類篇音萇伯切。繻，詢趨翻。駘，堂來翻。", "textJt": "周宣王封其弟友于郑。杜预世族谱曰：封于咸林，今京兆郑邑是也。幽王无道，友徙其人于虢、郐之间，遂有其地，今河南新郑是也。友，谥桓公。是年，郑𦈡公骀之二十三年。自桓公至𦈡公二十二世。班志，阳翟县属颍川郡。索隐曰：翟，音狄，温公类篇音苌伯切。𦈡，询趋翻。骀，堂来翻。"}]','军事,郑,韩,阳翟','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfa3216-db0e-11ef-89da-a0d3651f611f',CURRENT_TIMESTAMP),
(35,'8bfaf57b-db0e-11ef-bd7d-a0d3651f611f',4,1,35,'韓景侯薨，子烈侯取立。','韩景侯薨，子烈侯取立。','韩景侯去世，他的儿子韩烈侯韩取继位。',NULL,'人事,韩景侯,烈侯,取','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfa3216-db0e-11ef-89da-a0d3651f611f',CURRENT_TIMESTAMP),
(36,'8bfb1502-db0e-11ef-8828-a0d3651f611f',4,1,36,'趙烈侯薨，國人立其弟武侯。','赵烈侯薨，国人立其弟武侯。','赵烈侯去世，赵国人拥立他的弟弟为国君，是为赵武侯。',NULL,'内政,赵烈侯,武侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfa3216-db0e-11ef-89da-a0d3651f611f',CURRENT_TIMESTAMP),
(37,'8bfb1505-db0e-11ef-8b73-a0d3651f611f',4,1,37,'秦簡公薨，子惠公立。','秦简公薨，子惠公立。','秦简公去世，他的儿子秦惠公即位。','[{"type": "胡注", "text": "諡法：愛民好與曰惠。", "textJt": "谥法：爱民好与曰惠。"}]','人事,秦简公,惠公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfa3216-db0e-11ef-89da-a0d3651f611f',CURRENT_TIMESTAMP),
(38,'8bfb150c-db0e-11ef-ae6c-a0d3651f611f',5,1,38,'王子定奔晉。','王子定奔晋。','周朝王子姬定逃奔到晋国。',NULL,'外交,王子定,晋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb150a-db0e-11ef-949e-a0d3651f611f',CURRENT_TIMESTAMP),
(39,'8bfb150f-db0e-11ef-93cd-a0d3651f611f',5,1,39,'虢山崩，壅河。','虢山崩，壅河。','虢山崩塌，黄河被堵塞。','[{"type": "胡注", "text": "徐廣曰：虢山在陝。裴駰曰：弘農陝縣，故虢國。北虢在大陽，東虢在滎陽。括地志曰：虢山在陝州陝縣，西臨黃河；今臨河有岡阜，似是頹山之餘。水經註曰：陝城西北帶河，水湧起方數十丈。父老云：石虎載銅翁仲至此沈沒，水所以湧。洪河巨瀆，宜不爲金狄梗流，蓋魏文侯時虢山崩壅河所致耳。陝，失冉翻。", "textJt": "徐广曰：虢山在陕。裴骃曰：弘农陕县，故虢国。北虢在大阳，东虢在荥阳。括地志曰：虢山在陕州陕县，西临黄河；今临河有冈阜，似是颓山之余。水经注曰：陕城西北带河，水涌起方数十丈。父老云：石虎载铜翁仲至此沉没，水所以涌。洪河巨渎，宜不为金狄梗流，盖魏文侯时虢山崩壅河所致耳。陕，失冉翻。"}]','虢山,河','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb150a-db0e-11ef-949e-a0d3651f611f',CURRENT_TIMESTAMP),
(40,'8bfb152d-db0e-11ef-9b1e-a0d3651f611f',6,1,40,'楚圍鄭。鄭人殺其相駟子陽。','楚围郑。郑人杀其相驷子阳。','楚军围攻郑国。郑国人杀死了国相驷子阳。','[{"type": "胡注", "text": "鄭穆公之子騑，字子駟；古者以王父之字爲氏，子陽其後也。相，息亮翻。騑，芳菲翻。", "textJt": "郑穆公之子𬴂，字子驷；古者以王父之字为氏，子阳其后也。相，息亮翻。𬴂，芳菲翻。"}]','军事,内政,驷子阳,楚,郑,相','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb152b-db0e-11ef-8db2-a0d3651f611f',CURRENT_TIMESTAMP),
(41,'8bfb1539-db0e-11ef-a590-a0d3651f611f',7,1,41,'日有食之。','日有食之。','发生日食。','[{"type": "胡注", "text": "杜預曰：日行遲，一歲一周天。月行速，一月一周天；一歲凡十二交會。然日、月，動物，雖行度有大量，不能不小有贏縮，故有雖交會而不食者，或有頻交而食者。孔穎達曰：日月交會，謂朔也。周天三百六十五度四分度之一。日月皆右行於天，一晝一夜，日行一度，月行十三度十九分度之七，二十九日日有餘，而月行天一周，追及於日而與之會。交會而日月同道則食；月或在日道表，或在日道裏，則不食矣。又曆家爲交食之法，大率以一百七十有三日有奇爲限。然月先在裏，則依限而食者多；若月在表，則依限而食者少。杜預見其參差，乃云「雖行度有大量，不能不小有贏縮，故有雖交會而不食者，或有頻交而食者」，此得之矣。蘇氏曰：交當朔則日食，然亦有交而不食者。交而食，陽微而陰乘之也；交而不食，陽盛而陰不能揜也。朱元晦曰：此則繫乎人事之感。蓋臣子背君父，妾婦乘其夫，小人陵君子，夷狄侵中國，所感如是，則陰盛陽微而日爲之食矣。是以聖人於春秋，每食必書，而詩人亦以爲醜也。今此書年而不書月與晦、朔，史失之也。釋名曰：日、月虧曰食；稍小侵虧，如蟲食草木之葉也。亦作「蝕」。", "textJt": "杜预曰：日行迟，一岁一周天。月行速，一月一周天；一岁凡十二交会。然日、月，动物，虽行度有大量，不能不小有赢缩，故有虽交会而不食者，或有频交而食者。孔颖达曰：日月交会，谓朔也。周天三百六十五度四分度之一。日月皆右行于天，一昼一夜，日行一度，月行十三度十九分度之七，二十九日日有余，而月行天一周，追及于日而与之会。交会而日月同道则食；月或在日道表，或在日道里，则不食矣。又历家为交食之法，大率以一百七十有三日有奇为限。然月先在里，则依限而食者多；若月在表，则依限而食者少。杜预见其参差，乃云「虽行度有大量，不能不小有赢缩，故有虽交会而不食者，或有频交而食者」，此得之矣。苏氏曰：交当朔则日食，然亦有交而不食者。交而食，阳微而阴乘之也；交而不食，阳盛而阴不能揜也。朱元晦曰：此则系乎人事之感。盖臣子背君父，妾妇乘其夫，小人陵君子，夷狄侵中国，所感如是，则阴盛阳微而日为之食矣。是以圣人于春秋，每食必书，而诗人亦以为丑也。今此书年而不书月与晦、朔，史失之也。释名曰：日、月亏曰食；稍小侵亏，如虫食草木之叶也。亦作「蚀」。"}]',NULL,'https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1537-db0e-11ef-bb5f-a0d3651f611f',CURRENT_TIMESTAMP),
(42,'8bfb1542-db0e-11ef-a3f1-a0d3651f611f',7,1,42,'三月，盜殺韓相俠累。俠累與濮陽嚴仲子有惡。仲子聞軹人聶政之勇，以黃金百溢爲政母壽，欲因以報仇。政不受，曰：「老母在，政身未敢以許人也！」及母卒，仲子乃使政刺俠累。俠累方坐府上，兵衞甚衆，聶政直入上階，刺殺俠累，因自皮面決眼，自屠出腸。韓人暴其尸於市，購問，莫能識。其姊嫈聞而往，哭之曰：「是軹深井里聶政也！以妾尚在之故，重自刑以絕從。妾柰何畏歿身之誅，終滅賢弟之名！」遂死於政尸之旁。','三月，盗杀韩相侠累。侠累与濮阳严仲子有恶。仲子闻轵人聂政之勇，以黄金百溢为政母寿，欲因以报仇。政不受，曰：「老母在，政身未敢以许人也！」及母卒，仲子乃使政刺侠累。侠累方坐府上，兵衞甚众，聂政直入上阶，刺杀侠累，因自皮面决眼，自屠出肠。韩人暴其尸于市，购问，莫能识。其姊嫈闻而往，哭之曰：「是轵深井里聂政也！以妾尚在之故，重自刑以绝从。妾柰何畏殁身之诛，终灭贤弟之名！」遂死于政尸之旁。','三月，强盗刺杀了韩国国相侠累。侠累与濮阳人严仲子有仇。严仲子听说轵邑人聂政勇敢，用一百镒黄金给聂政的母亲祝寿，想借他报仇。聂政不接受，说：“老母还在世，我聂政不敢把自身许诺给别人！”等到母亲去世后，严仲子就派聂政去刺杀侠累。侠累正坐在相府厅堂上，侍卫很多，聂政径直冲上台阶，杀死了侠累，然后自己割破脸皮、剜出眼睛，又剖腹拉出肠子而死。韩国人把他的尸体陈放在街市上示众，悬赏征求能辨认的人，但没有人能认出来。他的姐姐聂嫈听说后，赶往陈尸的街市，抚着尸体哭着说：“这是轵邑深井里的聂政啊！他因为我还在人世，就深深毁伤自己来断绝线索。我怎么能因为怕招来杀身之祸，就永远埋没贤弟的名声呢！”于是自杀，死在聂政尸体旁边。','[{"type": "胡注", "text": "相，息亮翻。俠，戶頰翻。累，力追翻。濮陽，春秋之帝丘，漢爲濮陽縣，屬東郡。應劭曰：濮水南入鉅野。水北爲陽。濮，博木翻。惡，如字，不善也；康：烏故切，非。軹，春秋原邑，晉文公所圍者；漢爲軹縣，屬河內郡；音只。姓譜曰：楚大夫食采於聶，因以爲氏。聶，尼輒翻。溢，夷質翻。二十四兩爲溢。", "textJt": "相，息亮翻。侠，户颊翻。累，力追翻。濮阳，春秋之帝丘，汉为濮阳县，属东郡。应劭曰：濮水南入巨野。水北为阳。濮，博木翻。恶，如字，不善也；康：乌故切，非。轵，春秋原邑，晋文公所围者；汉为轵县，属河内郡；音只。姓谱曰：楚大夫食采于聂，因以为氏。聂，尼辄翻。溢，夷质翻。二十四两为溢。"}, {"type": "胡注", "text": "史記正義曰：深井里在懷州濟源縣南三十里。", "textJt": "史记正义曰：深井里在怀州济源县南三十里。"}, {"type": "胡注", "text": "皮面，以刀剺面而去其皮。懸賞以募告者曰購。購，古候翻。嫈，烏莖翻。絕從之從，讀曰蹤，謂自絕其蹤跡。或曰：從，讀如字，謂絕其從坐之罪也。", "textJt": "皮面，以刀剺面而去其皮。悬赏以募告者曰购。购，古候翻。嫈，乌茎翻。绝从之从，读曰踪，谓自绝其踪迹。或曰：从，读如字，谓绝其从坐之罪也。"}]','权争,侠累,严仲子,仲子,聂政,政,嫈,韩,濮阳,轵,轵深井里,韓相','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1537-db0e-11ef-bb5f-a0d3651f611f',CURRENT_TIMESTAMP),
(43,'8bfb157a-db0e-11ef-ae25-a0d3651f611f',8,1,43,'鄭駟子陽之黨弑繻公，而立其弟乙，是爲康公。','郑驷子阳之党弑𦈡公，而立其弟乙，是为康公。','郑国驷子阳的党羽弑杀郑繻公，拥立他的弟弟姬乙，即郑康公。','[{"type": "胡注", "text": "繻者，諡法所不載。史記註：「繻」，或作「繚」。繻，詢趨翻。", "textJt": "𦈡者，谥法所不载。史记注：「𦈡」，或作「缭」。𦈡，询趋翻。"}, {"type": "胡注", "text": "白虎通曰：弟，悌也，心順、行篤也。行，下孟翻。", "textJt": "白虎通曰：弟，悌也，心顺、行笃也。行，下孟翻。"}]','权争,驷子阳,𦈡公,乙,康公,郑','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1578-db0e-11ef-959d-a0d3651f611f',CURRENT_TIMESTAMP),
(44,'8bfb1585-db0e-11ef-8166-a0d3651f611f',8,1,44,'宋悼公薨，子休公田立。','宋悼公薨，子休公田立。','宋悼公去世，他的儿子田即位，是为宋休公。','[{"type": "胡注", "text": "武王封微子啓於宋，唐宋州之睢陽縣是也。自微子二十七世至悼公，名購由。休，亦諡法所不載。", "textJt": "武王封微子启于宋，唐宋州之睢阳县是也。自微子二十七世至悼公，名购由。休，亦谥法所不载。"}]','内政,宋悼公,休公田','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1578-db0e-11ef-959d-a0d3651f611f',CURRENT_TIMESTAMP),
(45,'8bfb1595-db0e-11ef-9632-a0d3651f611f',9,1,45,'齊伐魯，取最。','齐伐鲁，取最。','齐国攻打鲁国，夺取了最地。','[{"type": "胡注", "text": "武王封太公於齊，唐青州之臨淄是也。括地志曰：天齊水在臨淄東南十五里。封禪書曰：齊之所以爲齊者，以天齊。是年，康公貸之十一年。自太公至康公二十九世。成王封伯禽於魯，唐兗州之曲阜是也。是年，穆公之十六年。自伯禽至穆公凡二十八世。", "textJt": "武王封太公于齐，唐青州之临淄是也。括地志曰：天齐水在临淄东南十五里。封禅书曰：齐之所以为齐者，以天齐。是年，康公贷之十一年。自太公至康公二十九世。成王封伯禽于鲁，唐兖州之曲阜是也。是年，穆公之十六年。自伯禽至穆公凡二十八世。"}]','军事,齐,鲁,最','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1593-db0e-11ef-94d4-a0d3651f611f',CURRENT_TIMESTAMP),
(46,'8bfd4b9b-db0e-11ef-b501-a0d3651f611f',9,1,46,'鄭負黍叛，復歸韓。','郑负黍叛，复归韩。','郑国的负黍反叛郑国，重新归附韩国。','[{"type": "胡注", "text": "據史記，繻公之十六年，敗韓於負黍，蓋以此時取之，而今復叛歸韓也。劉昭郡國志：潁川郡陽城縣有負黍聚。古今地名云：負黍山在陽城縣西南二十七里，或云在西南三十五里。", "textJt": "据史记，𦈡公之十六年，败韩于负黍，盖以此时取之，而今复叛归韩也。刘昭郡国志：颍川郡阳城县有负黍聚。古今地名云：负黍山在阳城县西南二十七里，或云在西南三十五里。"}]','外交,郑,负黍,韩','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfb1593-db0e-11ef-94d4-a0d3651f611f',CURRENT_TIMESTAMP),
(47,'8bfd6651-db0e-11ef-bf6a-a0d3651f611f',10,1,47,'魏伐鄭。','魏伐郑。','魏国出兵攻打郑国。',NULL,'军事,魏,郑','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd664f-db0e-11ef-87b9-a0d3651f611f',CURRENT_TIMESTAMP),
(48,'8bfd6654-db0e-11ef-8531-a0d3651f611f',10,1,48,'晉烈公薨，子孝公傾立。','晋烈公薨，子孝公倾立。','晋烈公去世，他的儿子姬倾即位，是为晋孝公。','[{"type": "胡注", "text": "周成王封弟叔虞於唐。括地志曰：故唐城在幷州晉陽縣北二里，堯所築也。都城記曰：唐叔虞之子燮父徙居晉水旁，今幷州理故唐城，卽燮父初徙之處；其城南半入州城中。毛詩譜曰：燮父以堯墟南有晉水，改曰晉侯。自唐叔至烈公三十七世。烈公，名止。諡法：慈惠愛親曰孝。", "textJt": "周成王封弟叔虞于唐。括地志曰：故唐城在幷州晋阳县北二里，尧所筑也。都城记曰：唐叔虞之子燮父徙居晋水旁，今幷州理故唐城，即燮父初徙之处；其城南半入州城中。毛诗谱曰：燮父以尧墟南有晋水，改曰晋侯。自唐叔至烈公三十七世。烈公，名止。谥法：慈惠爱亲曰孝。"}]','内政,晋烈公,孝公,倾','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd664f-db0e-11ef-87b9-a0d3651f611f',CURRENT_TIMESTAMP),
(49,'8bfd6673-db0e-11ef-8dd2-a0d3651f611f',11,1,49,'秦伐韓宜陽，取六邑。','秦伐韩宜阳，取六邑。','秦国攻打韩国的宜阳，占领了六座城邑。','[{"type": "胡注", "text": "班志，宜陽縣屬弘農郡。史記正義曰：宜陽縣故城，在河南府福昌縣東十四里，故韓城是也。此邑卽周禮「四井爲邑」之邑。", "textJt": "班志，宜阳县属弘农郡。史记正义曰：宜阳县故城，在河南府福昌县东十四里，故韩城是也。此邑即周礼「四井为邑」之邑。"}]','军事,秦,韩,宜阳','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd6671-db0e-11ef-8551-a0d3651f611f',CURRENT_TIMESTAMP),
(50,'8bfd6682-db0e-11ef-812d-a0d3651f611f',11,1,50,'初，田常生襄子盤，盤生莊子白，白生太公和。是歲，齊田和遷齊康公於海上，使食一城，以奉其先祀。','初，田常生襄子盘，盘生庄子白，白生太公和。是岁，齐田和迁齐康公于海上，使食一城，以奉其先祀。','起初，田常生襄子田盘，田盘生庄子田白，田白生太公田和。这一年，齐国田和把齐康公迁到海上，给他一座城作食邑，让他以此供奉姜氏先人的祭祀。','[{"type": "胡注", "text": "此序齊田氏之世也。田常，卽左傳陳成子恆也。溫公避仁廟諱，改「恆」曰「常」。自陳公子完奔齊，五世至常得政。諡法：勝敵志強曰莊。", "textJt": "此序齐田氏之世也。田常，即左传陈成子恒也。温公避仁庙讳，改「恒」曰「常」。自陈公子完奔齐，五世至常得政。谥法：胜敌志强曰庄。"}]','权争,田常,襄子盘,盘,庄子白,白,太公和,田和,齐康公,齐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd6671-db0e-11ef-8551-a0d3651f611f',CURRENT_TIMESTAMP),
(51,'8bfd6699-db0e-11ef-ae0f-a0d3651f611f',12,1,51,'秦、晉戰于武城。','秦、晋战于武城。','秦、晋两国在武城交战。','[{"type": "胡注", "text": "此非魯之武城。左傳：晉陰飴甥會秦伯，盟于王城。杜預曰：馮翊臨晉縣東有王城，今名武鄕。括地志：故武城，一名武平城，在華州鄭縣東北十三里。", "textJt": "此非鲁之武城。左传：晋阴饴甥会秦伯，盟于王城。杜预曰：冯翊临晋县东有王城，今名武鄕。括地志：故武城，一名武平城，在华州郑县东北十三里。"}]','军事,秦,晋,武城','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd6697-db0e-11ef-b94a-a0d3651f611f',CURRENT_TIMESTAMP),
(52,'8bfd66b7-db0e-11ef-ad3e-a0d3651f611f',12,1,52,'齊伐魏，取襄陽。','齐伐魏，取襄阳。','齐国攻打魏国，夺取襄陵。','[{"type": "胡注", "text": "「陽」，當作「陵」。徐廣曰：今之南平陽也。余據晉志，南平陽縣屬山陽郡。班志，陳留郡有襄邑縣。師古曰：圈稱云：襄邑，宋地，本承匡襄陵鄕也，宋襄公所葬，故曰襄陵。秦始皇以承匡卑濕，徙縣襄陵，因曰襄邑。", "textJt": "「阳」，当作「陵」。徐广曰：今之南平阳也。余据晋志，南平阳县属山阳郡。班志，陈留郡有襄邑县。师古曰：圈称云：襄邑，宋地，本承匡襄陵鄕也，宋襄公所葬，故曰襄陵。秦始皇以承匡卑湿，徙县襄陵，因曰襄邑。"}]','军事,齐,魏,襄阳','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd6697-db0e-11ef-b94a-a0d3651f611f',CURRENT_TIMESTAMP),
(53,'8bfd66d1-db0e-11ef-8e7f-a0d3651f611f',12,1,53,'魯敗齊師于平陸。','鲁败齐师于平陆。','鲁国军队在平陆击败了齐国军队。','[{"type": "胡注", "text": "班志，東平國有東平陸縣，戰國時之平陸也。史記正義曰：平陸，兗州縣，卽古厥國。宋白曰：鄆州中都縣，漢爲平陸縣，史記「魯敗齊師于平陸」是也。敗，補邁翻。", "textJt": "班志，东平国有东平陆县，战国时之平陆也。史记正义曰：平陆，兖州县，即古厥国。宋白曰：郓州中都县，汉为平陆县，史记「鲁败齐师于平陆」是也。败，补迈翻。"}]','军事,鲁,齐,平陆','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd6697-db0e-11ef-b94a-a0d3651f611f',CURRENT_TIMESTAMP),
(54,'8bfd66eb-db0e-11ef-b06b-a0d3651f611f',13,1,54,'秦侵晉。','秦侵晋。','秦国侵犯魏国的阴晋。',NULL,'军事,阴晋之战,秦,晋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd66e9-db0e-11ef-8e6b-a0d3651f611f',CURRENT_TIMESTAMP),
(55,'8bfd66ee-db0e-11ef-987c-a0d3651f611f',13,1,55,'齊田和會魏文侯、楚人、衞人于濁澤，求爲諸侯。魏文侯爲之請於王及諸侯，王許之。','齐田和会魏文侯、楚人、衞人于浊泽，求为诸侯。魏文侯为之请于王及诸侯，王许之。','齐国田和在浊泽会同魏文侯、楚人、卫人，谋求取得诸侯名位。魏文侯替田和向周安王及各国诸侯陈请，周安王准予所请。','[{"type": "胡注", "text": "康曰：濁，水名；漢志：濁水出齊郡廣縣嬀山。余謂康說誤矣。徐廣史記註曰：長社有濁澤。水經註曰：皇陂水出胡城西北。胡城，潁陰之狐人亭也。皇陂，古長社之濁澤也。記：諸侯相見於郤地曰會。孔穎達曰：諸侯未及期而相見曰遇。會者，謂及期之禮，旣及期，又至所期之地。", "textJt": "康曰：浊，水名；汉志：浊水出齐郡广县妫山。余谓康说误矣。徐广史记注曰：长社有浊泽。水经注曰：皇陂水出胡城西北。胡城，颍阴之狐人亭也。皇陂，古长社之浊泽也。记：诸侯相见于郤地曰会。孔颖达曰：诸侯未及期而相见曰遇。会者，谓及期之礼，既及期，又至所期之地。"}]','外交,田和,魏文侯,齐,楚,衞,浊泽,諸侯,王','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd66e9-db0e-11ef-8e6b-a0d3651f611f',CURRENT_TIMESTAMP),
(56,'8bfd6711-db0e-11ef-9099-a0d3651f611f',14,1,56,'秦伐蜀，取南鄭。','秦伐蜀，取南郑。','秦国进攻蜀国，夺取南郑。','[{"type": "胡注", "text": "譜記普疑衍云：蜀之先，肇自人皇之際。黃帝子昌意娶蜀山氏女，生帝俈。旣立，封其支庶於蜀，歷虞、夏、商、周。周衰，先稱王者蠶叢。余據武王伐紂，庸、蜀諸國皆會于牧野。孔安國曰：蜀，叟也，春秋之時不與中國通。班志，南鄭縣屬漢中郡，唐爲梁州治所。「俈」，通作「嚳」，音括沃翻。", "textJt": "谱记普疑衍云：蜀之先，肇自人皇之际。黄帝子昌意娶蜀山氏女，生帝俈。既立，封其支庶于蜀，历虞、夏、商、周。周衰，先称王者蚕丛。余据武王伐纣，庸、蜀诸国皆会于牧野。孔安国曰：蜀，叟也，春秋之时不与中国通。班志，南郑县属汉中郡，唐为梁州治所。「俈」，通作「喾」，音括沃翻。"}]','军事,秦,蜀,南郑','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(57,'8bffbbe2-db0e-11ef-9aaf-a0d3651f611f',14,1,57,'魏文侯薨，太子擊立，是爲武侯。','魏文侯薨，太子击立，是为武侯。','魏文侯去世，太子魏击即位，是为魏武侯。','[{"type": "胡注", "text": "王者以嫡長子爲太子，謂之國儲副君。諸侯曰世子。周衰，率上僭。孔穎達曰：太者，大中之大也。上，時掌翻。長，知兩翻。", "textJt": "王者以嫡长子为太子，谓之国储副君。诸侯曰世子。周衰，率上僭。孔颖达曰：太者，大中之大也。上，时掌翻。长，知两翻。"}]','人事,魏文侯,击,武侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(58,'8bfff26d-db0e-11ef-824f-a0d3651f611f',14,1,58,'武侯浮西河而下，中流顧謂吳起曰：「美哉山河之固，此魏國之寶也！」對曰：「在德不在險。昔三苗氏，左洞庭，右彭蠡；德義不脩，禹滅之。夏桀之居，左河濟，右泰華，伊闕在其南，羊腸在其北；脩政不仁，湯放之。商紂之國，左孟門，右太行，常山在其北，大河經其南；脩政不德，武王殺之。由此觀之，在德不在險。若君不脩德，舟中之人皆敵國也！」武侯曰：「善。」','武侯浮西河而下，中流顾谓吴起曰：「美哉山河之固，此魏国之宝也！」对曰：「在德不在险。昔三苗氏，左洞庭，右彭蠡；德义不修，禹灭之。夏桀之居，左河济，右泰华，伊阙在其南，羊肠在其北；修政不仁，汤放之。商纣之国，左孟门，右太行，常山在其北，大河经其南；修政不德，武王杀之。由此观之，在德不在险。若君不修德，舟中之人皆敌国也！」武侯曰：「善。」','魏武侯乘船沿西河顺流而下，行至中流，回头对吴起说：“壮美啊，这华山、黄河的天险如此坚固，真是魏国的大宝！”吴起回答说：“国家的大宝在于施行德政，而不在于依靠天险。古时候的三苗氏部落，西面有洞庭湖，东面有彭蠡泽；他不修德义，夏禹便灭亡了他。夏桀所统治的疆域，东边有黄河、济水，西边有华山，伊阙山在它的南边，羊肠坂在它的北边；他不实行仁政，商汤就把他放逐了。商纣的国境，西边有孟门山，东边有太行山，常山在它的北境，黄河流经它的南境；他施政不仁德，周武王就杀了他。由此看来，国家的大宝在于施行德政，而不在于依靠山河天险。假使主君您不施行德政，眼下这条船上的人都会成为敌国之人！”武侯说：“说得很好。”','[{"type": "胡注", "text": "西河，卽禹貢之「龍門西河」。", "textJt": "西河，即禹贡之「龙门西河」。"}, {"type": "胡注", "text": "武陵、長沙、零、桂之水，匯爲洞庭，周七百里。彭蠡澤在漢豫章郡彭澤縣西。書：有苗弗率，汝徂征。三苗所居，蓋今江南西道之地。蠡，里弟翻。", "textJt": "武陵、长沙、零、桂之水，汇为洞庭，周七百里。彭蠡泽在汉豫章郡彭泽县西。书：有苗弗率，汝徂征。三苗所居，盖今江南西道之地。蠡，里弟翻。"}, {"type": "胡注", "text": "濟水出河東垣縣王屋山，南流貫河而南，合于滎瀆。禹貢所謂「導沇水，東流爲濟，溢爲滎」者也。自漢築滎陽石門，而濟與河合流而注于海，不入滎瀆。禹貢所謂「導沇水，東流爲濟，入于河」。桀都安邑，蓋恃以爲險。泰華山在京兆華陰縣南。水經：伊水出南陽縣西荀渠山，東北流至河南新城縣，又東南過伊闕中，大禹所鑿也。兩山相對，望之若闕。左傳「女寬守闕塞」，卽其地。括地志：伊闕山在洛州南十九里。班志，上黨壺關縣有羊腸阪。此安邑四履所憑，山河之固也。書曰：成湯放桀于南巢。濟，子禮翻。華，戶化翻。", "textJt": "济水出河东垣县王屋山，南流贯河而南，合于荥渎。禹贡所谓「导沇水，东流为济，溢为荥」者也。自汉筑荥阳石门，而济与河合流而注于海，不入荥渎。禹贡所谓「导沇水，东流为济，入于河」。桀都安邑，盖恃以为险。泰华山在京兆华阴县南。水经：伊水出南阳县西荀渠山，东北流至河南新城县，又东南过伊阙中，大禹所凿也。两山相对，望之若阙。左传「女宽守阙塞」，即其地。括地志：伊阙山在洛州南十九里。班志，上党壶关县有羊肠阪。此安邑四履所凭，山河之固也。书曰：成汤放桀于南巢。济，子礼翻。华，户化翻。"}, {"type": "胡注", "text": "水經註：孟門在河東北屈縣西，卽龍門上口也。淮南子曰：龍門未闢，呂梁未鑿，河出孟門之上，溢而逆流，無有丘陵，名曰洪水。太行山在河內野王縣西北。常山在常山郡上曲陽縣西北。河水自孟門南抵華陰，屈而東流；紂都朝歌，河經其南。北屈之孟門在朝歌西北，恐不可言「左」。索隱曰：孟門別一山，在朝歌東邊。此特左、右二字之差而誤耳。春秋說題辭：河之爲言荷也；荷精分布，懷陰引度也。釋名：河，下也，隨地下處而通流也。書曰：武王勝殷，殺紂。太行之行，戶剛翻。北屈，陸：求忽翻，顏：居勿翻。", "textJt": "水经注：孟门在河东北屈县西，即龙门上口也。淮南子曰：龙门未辟，吕梁未凿，河出孟门之上，溢而逆流，无有丘陵，名曰洪水。太行山在河内野王县西北。常山在常山郡上曲阳县西北。河水自孟门南抵华阴，屈而东流；纣都朝歌，河经其南。北屈之孟门在朝歌西北，恐不可言「左」。索隐曰：孟门别一山，在朝歌东边。此特左、右二字之差而误耳。春秋说题辞：河之为言荷也；荷精分布，怀阴引度也。释名：河，下也，随地下处而通流也。书曰：武王胜殷，杀纣。太行之行，户刚翻。北屈，陆：求忽翻，颜：居勿翻。"}]','史论,武侯,吴起,禹,夏桀,汤,商纣,武王,西河,魏国,三苗氏,洞庭,彭蠡,河济,泰华,伊阙,羊肠,孟门,太行,常山,大河','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(59,'8c021a35-db0e-11ef-94de-a0d3651f611f',14,1,59,'魏置相，相田文。吳起不悅，謂田文曰：「請與子論功可乎？」田文曰：「可。」起曰：「將三軍，使士卒樂死，敵國不敢謀，子孰與起？」文曰：「不如子。」起曰：「治百官，親萬民，實府庫，子孰與起？」文曰：「不如子。」起曰：「守西河，秦兵不敢東鄕，韓、趙賓從，子孰與起？」文曰：「不如子。」起曰：「此三者子皆出吾下，而位居吾上，何也？」文曰：「主少國疑，大臣未附，百姓不信，方是之時，屬之子乎，屬之我乎？」起默然良久曰：「屬之子矣！」','魏置相，相田文。吴起不悦，谓田文曰：「请与子论功可乎？」田文曰：「可。」起曰：「将三军，使士卒乐死，敌国不敢谋，子孰与起？」文曰：「不如子。」起曰：「治百官，亲万民，实府库，子孰与起？」文曰：「不如子。」起曰：「守西河，秦兵不敢东鄕，韩、赵宾从，子孰与起？」文曰：「不如子。」起曰：「此三者子皆出吾下，而位居吾上，何也？」文曰：「主少国疑，大臣未附，百姓不信，方是之时，属之子乎，属之我乎？」起默然良久曰：「属之子矣！」','魏国设置相职，任命田文为相。吴起不高兴，对田文说：“请让我与你比较一下功绩，可以吗？”田文说：“可以。”吴起说：“统率三军，使士兵乐于拼死作战，敌国不敢前来图谋侵犯，你和我吴起相比怎么样？”田文说：“我不如你。”吴起说：“管理百官，安抚万民，充实府库，你和我吴起相比怎么样？”田文说：“我不如你。”吴起说：“守卫西河，使秦兵不敢向东进犯魏国，韩国、赵国都来归附臣服，你和我吴起相比怎么样？”田文说：“我不如你。”吴起说：“这三方面你都在我之下，而官职地位却在我之上，这是为什么？”田文说：“主君年少，国家还不稳定，大臣尚未归附，百姓猜疑而不信服，正当这个时候，相职是托付给你呢，还是托付给我呢？”吴起沉默了很久，说：“是该托付给你啊！”','[{"type": "胡注", "text": "相，息亮翻。此田文非齊之田文。", "textJt": "相，息亮翻。此田文非齐之田文。"}, {"type": "胡注", "text": "鄕，讀曰向。賓從，猶言賓服也。", "textJt": "鄕，读曰向。宾从，犹言宾服也。"}]','人事,权争,田文,吴起,起,文,魏,西河,秦,韩,赵,相','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(60,'8c021a50-db0e-11ef-8568-a0d3651f611f',14,1,60,'久之，魏相公叔尚主而害吳起。公叔之僕曰：「起易去也。起爲人剛勁自喜。子先言於君曰：『吳起，賢人也，而君之國小，臣恐起之無留心也。君盍試延以女，起無留心，則必辭矣。』子因與起歸而使公主辱子，起見公主之賤子也，必辭，則子之計中矣。」公叔從之，吳起果辭公主。魏武侯疑之而未信，起懼誅，遂奔楚。','久之，魏相公叔尚主而害吴起。公叔之仆曰：「起易去也。起为人刚劲自喜。子先言于君曰：『吴起，贤人也，而君之国小，臣恐起之无留心也。君盍试延以女，起无留心，则必辞矣。』子因与起归而使公主辱子，起见公主之贱子也，必辞，则子之计中矣。」公叔从之，吴起果辞公主。魏武侯疑之而未信，起惧诛，遂奔楚。','过了很长时间，魏国国相公叔痤娶公主为妻，想陷害吴起。公叔痤的仆人说：“除掉吴起很容易。吴起为人刚愎自用。您先去对主君说：‘吴起是贤能的人，而主君您的国家小，我担心吴起没有长久留在魏国的想法。您何不用招他为婿的办法试一试，他如果没有留下的想法，就一定会推辞。’然后您邀请吴起一同回家，让公主羞辱您。吴起看见公主如此看不起您，一定会推辞娶公主为妻，那么您的计谋就成功了。”公叔痤听从了他的计策，吴起果然推辞娶公主为妻。魏武侯对他起了疑心，因此不信任他，吴起害怕被杀，便投奔楚国。','[{"type": "胡注", "text": "如淳曰：天子嫁女於諸侯，必使諸侯同姓者主之，故謂之公主。帝姊妹曰長公主，諸王女曰翁主。師古曰：如說得之。天子不親主婚，故謂之公主；諸王則自主婚，故其女曰翁主。翁者，父也，言父主其婚也；亦曰王主，言王自主其婚也。揚雄方言云：周、晉、秦、隴謂父曰翁。而臣瓚、王楙，或云「公者比於上爵」，或云「主者婦人尊稱」，皆失之。劉貢父曰：予謂公主之稱本出秦舊，男爲公子，女爲公主。古者大夫妻稱主，故以公配之。若謂同姓主之，故謂之公主，則周之事，秦不知用也。古之嫁女，禮當如周使大夫主之，何不謂之夫主乎？然則謂之王主者，猶言王子也；謂之公主者，緣公而生耳。毛晃曰：尚，崇也，高也，貴也，飾也，加也，尊也。娶公主謂之尚，言帝王之女尊而尚之，不敢言娶也。相，息亮翻。", "textJt": "如淳曰：天子嫁女于诸侯，必使诸侯同姓者主之，故谓之公主。帝姊妹曰长公主，诸王女曰翁主。师古曰：如说得之。天子不亲主婚，故谓之公主；诸王则自主婚，故其女曰翁主。翁者，父也，言父主其婚也；亦曰王主，言王自主其婚也。扬雄方言云：周、晋、秦、陇谓父曰翁。而臣瓒、王楙，或云「公者比于上爵」，或云「主者妇人尊称」，皆失之。刘贡父曰：予谓公主之称本出秦旧，男为公子，女为公主。古者大夫妻称主，故以公配之。若谓同姓主之，故谓之公主，则周之事，秦不知用也。古之嫁女，礼当如周使大夫主之，何不谓之夫主乎？然则谓之王主者，犹言王子也；谓之公主者，缘公而生耳。毛晃曰：尚，崇也，高也，贵也，饰也，加也，尊也。娶公主谓之尚，言帝王之女尊而尚之，不敢言娶也。相，息亮翻。"}, {"type": "胡注", "text": "易，以豉翻。去，起呂翻。師古曰：喜，許吏翻。", "textJt": "易，以豉翻。去，起吕翻。师古曰：喜，许吏翻。"}]','人事,权争,公叔,吴起,起,魏武侯,魏,楚,魏相','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(61,'8c021a7c-db0e-11ef-8a54-a0d3651f611f',14,1,61,'楚悼王素聞其賢，至則任之爲相。起明灋審令，捐不急之官，廢公族疏遠者，以撫養戰鬬之士，要在強兵，破遊說之言從橫者。於是南平百越，北卻三晉，西伐秦，諸侯皆患楚之強；而楚之貴戚大臣多怨吳起者。','楚悼王素闻其贤，至则任之为相。起明灋审令，捐不急之官，废公族疏远者，以抚养战鬬之士，要在强兵，破游说之言从横者。于是南平百越，北却三晋，西伐秦，诸侯皆患楚之强；而楚之贵戚大臣多怨吴起者。','楚悼王一向听说吴起贤能，吴起一到楚国，就被任用为国相。吴起严明法度，审察政令，裁撤冗杂不急的官职，废除公族中关系疏远者的爵禄，用来供养和奖赏作战将士，要旨在于强兵，推行强国方略，并破除游说之士所宣扬的合纵连横言论。于是，楚国向南平定百越，向北逼退韩、赵、魏三晋，向西攻伐秦国，各国诸侯都畏惧楚国的强盛；而楚国的贵戚大臣中，很多人怨恨吴起。','[{"type": "胡注", "text": "相，息亮翻。灋，古法字。", "textJt": "相，息亮翻。灋，古法字。"}, {"type": "胡注", "text": "捐，余專翻，弃也，除去也。漢書音義曰：以利合曰從，以威力相脅曰橫。或曰：南北曰從，從者，連南北爲一，西鄕以擯秦。東西曰橫，橫者，離山東之交，使之西鄕以事秦。說，式芮翻。從，卽容翻。「橫」，亦作「衡」，音同。", "textJt": "捐，余专翻，弃也，除去也。汉书音义曰：以利合曰从，以威力相胁曰横。或曰：南北曰从，从者，连南北为一，西鄕以摈秦。东西曰横，横者，离山东之交，使之西鄕以事秦。说，式芮翻。从，即容翻。「横」，亦作「衡」，音同。"}, {"type": "胡注", "text": "韋昭曰：越有百邑。", "textJt": "韦昭曰：越有百邑。"}]','内政,军事,人事,楚悼王,起,吴起,百越,三晋,秦,楚,相,官,大臣','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(62,'8c021a8e-db0e-11ef-bb36-a0d3651f611f',14,1,62,'秦惠公薨，子出公立。','秦惠公薨，子出公立。','秦惠公去世，其子秦出公即位。','[{"type": "胡注", "text": "出，非諡也；以其失國出死，故曰出公。", "textJt": "出，非谥也；以其失国出死，故曰出公。"}]','内政,秦惠公,出公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(63,'8c021a93-db0e-11ef-924f-a0d3651f611f',14,1,63,'趙武侯薨，國人復立烈侯之太子章，是爲敬侯。','赵武侯薨，国人复立烈侯之太子章，是为敬侯。','赵武侯去世，赵国人重新拥立赵烈侯的太子赵章即位，这就是赵敬侯。','[{"type": "胡注", "text": "諡法：夙夜警戒曰敬。", "textJt": "谥法：夙夜警戒曰敬。"}]','人事,赵武侯,烈侯,章,敬侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(64,'8c021a9a-db0e-11ef-836e-a0d3651f611f',14,1,64,'韓烈侯薨，子文侯立。','韩烈侯薨，子文侯立。','韩烈侯去世，他的儿子韩文侯继位。',NULL,'内政,韩烈侯,文侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8bfd670f-db0e-11ef-b7b5-a0d3651f611f',CURRENT_TIMESTAMP),
(65,'8c021a9f-db0e-11ef-9a7e-a0d3651f611f',15,1,65,'初命齊大夫田和爲諸侯。','初命齐大夫田和为诸侯。','这一年，开始册命齐国大夫田和为诸侯。','[{"type": "胡注", "text": "田氏自此遂有齊國。田和是爲太公。", "textJt": "田氏自此遂有齐国。田和是为太公。"}]','内政,人事,田和,齐,大夫','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021a9d-db0e-11ef-937d-a0d3651f611f',CURRENT_TIMESTAMP),
(66,'8c021aa7-db0e-11ef-b18d-a0d3651f611f',15,1,66,'趙公子朝作亂，奔魏；與魏襲邯鄲，不克。','赵公子朝作乱，奔魏；与魏袭邯郸，不克。','赵国公子赵朝作乱，出奔魏国；又与魏国一起偷袭赵国邯郸，没有攻克。',NULL,'军事,公子朝,赵,魏,邯郸','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021a9d-db0e-11ef-937d-a0d3651f611f',CURRENT_TIMESTAMP),
(67,'8c021ab5-db0e-11ef-8379-a0d3651f611f',16,1,67,'秦庶長改逆獻公于河西而立之；殺出子及其母，沈之淵旁。','秦庶长改逆献公于河西而立之；杀出子及其母，沈之渊旁。','秦国庶长改到河西迎接秦灵公的儿子，把他拥立为国君，即秦献公；随后杀死出子及其母亲，把尸体沉入深潭。','[{"type": "胡注", "text": "後秦制爵，一級曰公士，二上造，三簪裊，四不更，五大夫，六官大夫，七公大夫，八公乘，九五大夫，十左庶長，十一右庶長，十二左更，十三中更，十四右更，十五少上造，十六大上造，十七駟車庶長，十八大庶長，十九關內侯，二十徹侯。師古曰：庶長，言衆列之長。註又詳見下卷顯王十年前。據史記：威烈王十一年秦靈公卒，子獻公師隰不得立，立靈公季父悼子，是爲簡公。出子，簡公之孫也。今庶長改迎獻公而殺出子。正義曰：西者，秦州西縣，秦之舊地。時獻公在西縣，故迎立之。余謂此言河西，非西縣也。靈公之卒，獻公不得立，出居河西；河西者，黃河之西，蓋漢涼州之地。「裊」，當作「褭」，乃了翻。更，工衡翻。乘，繩證翻。長，知丈翻。", "textJt": "后秦制爵，一级曰公士，二上造，三簪袅，四不更，五大夫，六官大夫，七公大夫，八公乘，九五大夫，十左庶长，十一右庶长，十二左更，十三中更，十四右更，十五少上造，十六大上造，十七驷车庶长，十八大庶长，十九关内侯，二十彻侯。师古曰：庶长，言众列之长。注又详见下卷显王十年前。据史记：威烈王十一年秦灵公卒，子献公师隰不得立，立灵公季父悼子，是为简公。出子，简公之孙也。今庶长改迎献公而杀出子。正义曰：西者，秦州西县，秦之旧地。时献公在西县，故迎立之。余谓此言河西，非西县也。灵公之卒，献公不得立，出居河西；河西者，黄河之西，盖汉凉州之地。「袅」，当作「褭」，乃了翻。更，工衡翻。乘，绳证翻。长，知丈翻。"}]','权争,改,献公,出子,秦,河西,庶長','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021ab3-db0e-11ef-b6c0-a0d3651f611f',CURRENT_TIMESTAMP),
(68,'8c04670e-db0e-11ef-b336-a0d3651f611f',16,1,68,'齊伐魯。','齐伐鲁。','齐国攻打鲁国。',NULL,'军事,齐,鲁','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021ab3-db0e-11ef-b6c0-a0d3651f611f',CURRENT_TIMESTAMP),
(69,'8c046711-db0e-11ef-aba5-a0d3651f611f',16,1,69,'韓伐鄭，取陽城；伐宋，執宋公。','韩伐郑，取阳城；伐宋，执宋公。','韩国攻打郑国，占领了阳城；又攻打宋国，俘获了宋国国君宋公。','[{"type": "胡注", "text": "漢陽城縣屬潁川郡；是爲地中，成周於此以土圭測日景。", "textJt": "汉阳城县属颍川郡；是为地中，成周于此以土圭测日景。"}]','军事,宋公,韩,郑,阳城,宋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021ab3-db0e-11ef-b6c0-a0d3651f611f',CURRENT_TIMESTAMP),
(70,'8c04671c-db0e-11ef-9adc-a0d3651f611f',16,1,70,'齊太公薨，子桓公午立。','齐太公薨，子桓公午立。','齐太公田和去世，其子齐桓公田午即位。',NULL,'人事,齐太公,桓公,午,太公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c021ab3-db0e-11ef-b6c0-a0d3651f611f',CURRENT_TIMESTAMP),
(71,'8c046722-db0e-11ef-a07e-a0d3651f611f',17,1,71,'魏敗趙師于兔臺。','魏败赵师于兔台。','魏国军队在兔台击败了赵国军队。','[{"type": "胡注", "text": "史記·趙世家曰：魏敗我兔臺，築剛平。正義曰：兔臺、剛平，並在河北。敗，補邁翻。", "textJt": "史记·赵世家曰：魏败我兔台，筑刚平。正义曰：兔台、刚平，并在河北。败，补迈翻。"}]','军事,魏,赵,兔台','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046720-db0e-11ef-8f8e-a0d3651f611f',CURRENT_TIMESTAMP),
(72,'8c046731-db0e-11ef-8571-a0d3651f611f',18,1,72,'日有食之，旣。','日有食之，既。','发生日食，为日全食。','[{"type": "胡注", "text": "旣，盡也。", "textJt": "既，尽也。"}]',NULL,'https://www.dutongjian.com/api/reign?reign_tongjian_id=8c04672f-db0e-11ef-b527-a0d3651f611f',CURRENT_TIMESTAMP),
(73,'8c046735-db0e-11ef-a257-a0d3651f611f',19,1,73,'楚悼王薨。貴戚大臣作亂，攻吳起；起走之王尸而伏之。擊起之徒因射刺起，並中王尸。旣葬，肅王卽位，使令尹盡誅爲亂者；坐起夷宗者七十餘家。','楚悼王薨。贵戚大臣作乱，攻吴起；起走之王尸而伏之。击起之徒因射刺起，并中王尸。既葬，肃王即位，使令尹尽诛为乱者；坐起夷宗者七十余家。','楚悼王去世。楚国贵戚大臣们发动叛乱，围攻吴起；吴起逃到楚悼王尸体处，伏在尸体上面。攻击吴起的人于是用箭射刺吴起，连楚悼王的尸体也被射中。丧葬完毕后，楚肃王即位，命令令尹将作乱的人全部诛杀；因攻打吴起之事受牵连而被灭族的有七十余家。','[{"type": "胡注", "text": "之，往也，往赴王尸而伏其側。", "textJt": "之，往也，往赴王尸而伏其侧。"}, {"type": "胡注", "text": "諡法：剛德克就曰肅；執心決斷曰肅。", "textJt": "谥法：刚德克就曰肃；执心决断曰肃。"}, {"type": "胡注", "text": "令尹，楚相也。", "textJt": "令尹，楚相也。"}, {"type": "胡注", "text": "夷，殺也；夷宗者，殺其同宗也。", "textJt": "夷，杀也；夷宗者，杀其同宗也。"}]','权争,楚悼王,吴起,起,肃王,令尹','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046733-db0e-11ef-aaea-a0d3651f611f',CURRENT_TIMESTAMP),
(74,'8c046746-db0e-11ef-99ff-a0d3651f611f',20,1,74,'齊伐燕，取桑丘。魏、韓、趙伐齊，至桑丘。','齐伐燕，取桑丘。魏、韩、赵伐齐，至桑丘。','齐国攻打燕国，夺取了桑丘。魏、韩、赵三国救援燕国，攻打齐国，也进兵到了桑丘。','[{"type": "胡注", "text": "此桑丘，非二年所書楚之桑丘。括地志曰：桑丘故城，俗名敬城，在易州遂城縣，蓋燕之南界也。", "textJt": "此桑丘，非二年所书楚之桑丘。括地志曰：桑丘故城，俗名敬城，在易州遂城县，盖燕之南界也。"}]','军事,齐,燕,桑丘,魏,韩,赵','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046744-db0e-11ef-a66c-a0d3651f611f',CURRENT_TIMESTAMP),
(75,'8c04675b-db0e-11ef-afdb-a0d3651f611f',21,1,75,'趙襲衞，不克。','赵袭衞，不克。','赵国偷袭卫国，未能攻克。','[{"type": "胡注", "text": "成王封康叔於衞，居河、淇之間，故殷墟也。至懿公爲狄所滅，東徙度河。文公徙居楚丘，遂國於濮陽。是年，愼公頹之三十五年。自康叔至愼公凡三十二世。", "textJt": "成王封康叔于衞，居河、淇之间，故殷墟也。至懿公为狄所灭，东徙度河。文公徙居楚丘，遂国于濮阳。是年，愼公颓之三十五年。自康叔至愼公凡三十二世。"}]','军事,赵,衞','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046759-db0e-11ef-a207-a0d3651f611f',CURRENT_TIMESTAMP),
(76,'8c04676f-db0e-11ef-b484-a0d3651f611f',21,1,76,'齊康公薨，無子，田氏遂幷齊而有之。','齐康公薨，无子，田氏遂幷齐而有之。','齐康公去世，没有儿子，姜氏从此灭亡，田氏于是取代姜氏，兼并并占有了齐国。','[{"type": "胡注", "text": "姜氏至此滅矣。", "textJt": "姜氏至此灭矣。"}]','内政,权争,齐康公,田氏,齐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046759-db0e-11ef-a207-a0d3651f611f',CURRENT_TIMESTAMP),
(77,'8c046775-db0e-11ef-a805-a0d3651f611f',21,1,77,'是歲，齊桓公亦薨，子威王因齊立。','是岁，齐桓公亦薨，子威王因齐立。','这一年，田氏齐桓公也去世了，他的儿子齐威王田因齐继位。','[{"type": "胡注", "text": "諡法：強毅訅正曰威。訅，渠留翻。齊桓公，田午。訅，謀也。", "textJt": "谥法：强毅訅正曰威。訅，渠留翻。齐桓公，田午。訅，谋也。"}]','人事,齐桓公,威王,因齐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c046759-db0e-11ef-a207-a0d3651f611f',CURRENT_TIMESTAMP),
(78,'8c04677f-db0e-11ef-8d78-a0d3651f611f',22,1,78,'狄敗魏師于澮。','狄败魏师于浍。','狄人在浍地击败了魏国军队。','[{"type": "胡注", "text": "漢之中山、上黨、西河、上郡，自春秋以來，狄皆居之，此亦其種也。水經：澮水出河東絳縣東澮山，西過絳縣南，又西南過虒祁宮南，又西南至王橋，入汾水。括地志：澮山在絳州翼城縣東北。敗，補邁翻。澮，古外翻。", "textJt": "汉之中山、上党、西河、上郡，自春秋以来，狄皆居之，此亦其种也。水经：浍水出河东绛县东浍山，西过绛县南，又西南过虒祁宫南，又西南至王桥，入汾水。括地志：浍山在绛州翼城县东北。败，补迈翻。浍，古外翻。"}]','军事,狄,魏,浍','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c04677d-db0e-11ef-a702-a0d3651f611f',CURRENT_TIMESTAMP),
(79,'8c046798-db0e-11ef-a831-a0d3651f611f',22,1,79,'魏、韓、趙伐齊，至靈丘。','魏、韩、赵伐齐，至灵丘。','魏、韩、赵三国讨伐齐国，军队进至灵丘。','[{"type": "胡注", "text": "史記正義曰：靈丘，河東蔚州縣。余按蔚州之靈丘，卽漢代郡之靈丘，此時齊境安能至代北邪！此卽孟子謂蚳鼃辭靈丘請士師之地。班志曰：齊地北有千乘、清河以南。漢清河郡有靈縣，清河北接趙、魏之境，此爲近之。蚳，音遲。鼃，烏花翻。", "textJt": "史记正义曰：灵丘，河东蔚州县。余按蔚州之灵丘，即汉代郡之灵丘，此时齐境安能至代北邪！此即孟子谓蚳鼃辞灵丘请士师之地。班志曰：齐地北有千乘、清河以南。汉清河郡有灵县，清河北接赵、魏之境，此为近之。蚳，音迟。鼃，乌花翻。"}]','军事,魏,韩,赵,齐,灵丘','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c04677d-db0e-11ef-a702-a0d3651f611f',CURRENT_TIMESTAMP),
(80,'8c0467b8-db0e-11ef-a6d6-a0d3651f611f',22,1,80,'晉孝公薨，子靖公俱酒立。','晋孝公薨，子靖公俱酒立。','晋孝公去世，他的儿子晋靖公姬俱酒继位为国君。','[{"type": "胡注", "text": "諡法：柔衆安民曰靖；又，恭己鮮言曰靖。", "textJt": "谥法：柔众安民曰靖；又，恭己鲜言曰靖。"}]','内政,晋孝公,靖公,俱酒','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c04677d-db0e-11ef-a702-a0d3651f611f',CURRENT_TIMESTAMP),
(81,'8c06abb9-db0e-11ef-a763-a0d3651f611f',23,1,81,'蜀伐楚，取茲方。','蜀伐楚，取兹方。','蜀国出兵进攻楚国，夺取了兹方。','[{"type": "胡注", "text": "據史記：蜀伐楚，取茲方，楚爲扞關以拒之。則茲方之地在扞關之西。劉昭志：巴郡魚復縣有扞關。", "textJt": "据史记：蜀伐楚，取兹方，楚为扞关以拒之。则兹方之地在扞关之西。刘昭志：巴郡鱼复县有扞关。"}]','军事,蜀,楚,兹方','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(82,'8c06abcb-db0e-11ef-85c4-a0d3651f611f',23,1,82,'子思言苟變於衞侯曰：「其才可將五百乘。」公曰：「吾知其可將；然變也嘗爲吏，賦於民而食人二雞子，故弗用也。」子思曰：「夫聖人之官人，猶匠之用木也，取其所長，棄其所短；故杞梓連抱而有數尺之朽，良工不棄。今君處戰國之世，選爪牙之士，而以二卵棄干城之將，此不可使聞於鄰國也。」公再拜曰：「謹受敎矣！」','子思言苟变于衞侯曰：「其才可将五百乘。」公曰：「吾知其可将；然变也尝为吏，赋于民而食人二鸡子，故弗用也。」子思曰：「夫圣人之官人，犹匠之用木也，取其所长，弃其所短；故杞梓连抱而有数尺之朽，良工不弃。今君处战国之世，选爪牙之士，而以二卵弃干城之将，此不可使闻于邻国也。」公再拜曰：「谨受教矣！」','子思在卫侯面前举荐苟变说：“他的才能可以统率五百乘兵车。”卫侯说：“我知道他可以担任将领；但苟变曾经做过官吏，向百姓征收赋税时竟白吃了人家两个鸡蛋，所以没有任用他。”子思说：“圣人任命人做官，就像工匠使用木料，取用它的长处，舍弃它的短处；所以杞梓树有几人合抱那么粗，即使有几尺朽烂之处，好的工匠也不会丢弃。如今您处在战国乱世，要选拔勇武的爪牙之士，却因为两个鸡蛋而抛弃能保卫国家的干城之将，这样可笑的事不能让邻国听到啊！”卫侯再三拜谢说：“恭敬地接受您的教诲。”','[{"type": "胡注", "text": "古者兵車一乘，甲士三人，步卒七十二人；五百乘，三萬七千五百人。國語曰：苟本自黃帝之子。將，卽亮翻；下同。乘，繩證翻。", "textJt": "古者兵车一乘，甲士三人，步卒七十二人；五百乘，三万七千五百人。国语曰：苟本自黄帝之子。将，即亮翻；下同。乘，绳证翻。"}, {"type": "胡注", "text": "詩：赳赳武夫，公侯干城。毛氏傳曰：干，扞也；音戶旦翻。鄭氏箋曰：干也，城也，皆所以禦難也。干，讀如字。", "textJt": "诗：赳赳武夫，公侯干城。毛氏传曰：干，扞也；音户旦翻。郑氏笺曰：干也，城也，皆所以御难也。干，读如字。"}]','人事,子思,苟变,衞侯,变,战国,吏','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(83,'8c06abde-db0e-11ef-9919-a0d3651f611f',23,1,83,'衞侯言計非是，而羣臣和者如出一口。子思曰：「以吾觀衞，所謂『君不君，臣不臣』者也！」公丘懿子曰：「何乃若是？」子思曰：「人主自臧，則衆謀不進。事是而臧之，猶卻衆謀，況和非以長惡乎！夫不察事之是非而悅人讚己，闇莫甚焉；不度理之所在而阿諛求容，諂莫甚焉。君闇臣諂，以居百姓之上，民不與也。若此不已，國無類矣！」','衞侯言计非是，而群臣和者如出一口。子思曰：「以吾观衞，所谓『君不君，臣不臣』者也！」公丘懿子曰：「何乃若是？」子思曰：「人主自臧，则众谋不进。事是而臧之，犹却众谋，况和非以长恶乎！夫不察事之是非而悦人赞己，暗莫甚焉；不度理之所在而阿谀求容，谄莫甚焉。君暗臣谄，以居百姓之上，民不与也。若此不已，国无类矣！」','卫侯所说的计谋不对，群臣却随声附和，如同出于同一人之口。子思说：“依我观察卫国，正是所谓‘君不像君，臣不像臣’的情形啊！”公丘懿子说：“怎么会到这种地步？”子思说：“君主如果自以为高明，众人的计谋就不会进献上来。事情正确却自以为是，尚且会堵塞众人的谋略，更何况让人们附和错误的计谋来助长恶行呢！君主不考察事情的是非而喜欢别人称赞自己，昏暗没有比这更严重的；臣子不揣度道理何在而阿谀奉承以求容身，谄媚没有比这更严重的。君主昏暗，臣子谄媚，却高居百姓之上，民众是不会支持这样的国家的。如果这样下去而不停止，国家就要灭亡了！”','[{"type": "胡注", "text": "「君不君，臣不臣，」論語載齊景公之言。", "textJt": "「君不君，臣不臣，」论语载齐景公之言。"}, {"type": "胡注", "text": "公丘，複姓。諡法：溫柔賢善曰懿。", "textJt": "公丘，复姓。谥法：温柔贤善曰懿。"}, {"type": "胡注", "text": "臧，善也。", "textJt": "臧，善也。"}]','史论,衞侯,子思,公丘懿子','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(84,'8c06abed-db0e-11ef-94bb-a0d3651f611f',23,1,84,'子思言於衞侯曰：「君之國事將日非矣！」公曰：「何故？」對曰：「有由然焉。君出言自以爲是，而卿大夫莫敢矯其非；卿大夫出言亦自以爲是，而士庶人莫敢矯其非。君臣旣自賢矣，而羣下同聲賢之，賢之則順而有福，矯之則逆而有禍，如此則善安從生！詩曰：『具曰予聖，誰知烏之雌雄？』抑亦似君之君臣乎！」','子思言于衞侯曰：「君之国事将日非矣！」公曰：「何故？」对曰：「有由然焉。君出言自以为是，而卿大夫莫敢矫其非；卿大夫出言亦自以为是，而士庶人莫敢矫其非。君臣既自贤矣，而群下同声贤之，贤之则顺而有福，矫之则逆而有祸，如此则善安从生！诗曰：『具曰予圣，谁知乌之雌雄？』抑亦似君之君臣乎！」','子思对卫侯说：“主君的国事将一天天坏下去了！”卫侯说：“什么缘故呢？”子思回答说：“这是有原因的。主君说话自以为是，而卿大夫们没有谁敢纠正您的错误；卿大夫们说话也自以为是，而士人百姓没有谁敢纠正他们的错误。君臣既然都自以为贤能，而群臣百姓又同声称赞他们贤能，称赞贤能就顺从而有福，纠正错误就违逆而有祸，像这样，良好的政治又从哪里产生！《诗经》说：‘都说自己是圣人，谁能分辨乌鸦的雌雄？’这大概也就像主君这样的君臣吧！”','[{"type": "胡注", "text": "白虎通曰：君，羣也，羣下之所歸心也。臣，堅也，厲志自堅也。", "textJt": "白虎通曰：君，群也，群下之所归心也。臣，坚也，厉志自坚也。"}, {"type": "胡注", "text": "詩·正月之辭。毛氏傳曰：君臣俱自謂聖也。鄭氏箋曰：時君臣賢愚適同，如烏之雌雄相似，誰能別異之乎？又曰：烏鳥之雌雄不可別者，以翼知之，右掩左，雄，左掩右，雌，陰陽相下之義也。", "textJt": "诗·正月之辞。毛氏传曰：君臣俱自谓圣也。郑氏笺曰：时君臣贤愚适同，如乌之雌雄相似，谁能别异之乎？又曰：乌鸟之雌雄不可别者，以翼知之，右掩左，雄，左掩右，雌，阴阳相下之义也。"}]','内政,史论,子思,衞侯,卿大夫','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(85,'8c06abf9-db0e-11ef-b65f-a0d3651f611f',23,1,85,'魯穆公薨，子共公奮立。','鲁穆公薨，子共公奋立。','鲁穆公去世，他的儿子姬奋即位为鲁共公。','[{"type": "胡注", "text": "諡法：布德就義曰穆；中情見貌曰穆；尊賢敬讓曰共；旣過能改曰共；執事堅固曰共。共，讀曰恭。考異曰：司馬遷史記·六國表：周威烈王十九年甲戌，魯穆公元年。烈王元年丙午，共公元年。顯王十七年己巳，康公元年。二十六年戊寅，景公元年。赧王元年丁未，平公元年。二十年丙寅，文公元年。四十三年己丑，頃公元年。五十九年乙巳，周亡。秦莊襄王元年壬子，楚滅魯。按魯世家，穆公三十三年卒，若元甲戌，終乙巳，則是三十二年也。共公二十二年卒，若元丙午，終戊辰，則是二十三年也。康公九年卒，景公二十五年卒，平公二十二年卒，若元丁未，終乙丑，則是十九年也。文公二十三年卒，頃公二十四年楚滅魯。班固漢書·律曆志「文公」作「緡公」；其在位之年與世家異者，惟平公二十年耳。本志自魯僖公五年正月辛亥朔旦冬至推之，至成公十二年正月庚寅朔旦冬至，定公七年正月己巳朔旦冬至，元公四年正月戊申朔旦冬至，康公四年正月丁亥朔旦冬至，緡公二十二年正月丙寅朔旦冬至，漢高祖八年十一月乙巳朔旦冬至，武帝元朔六年十一月甲申朔旦冬至，元帝初元二年十一月癸亥朔旦冬至，其間相距皆七十六年，此最爲得實，又與魯世家註、皇甫謐所紀歲次皆合，今從之。六國表差謬，難可盡據也。余按考異自魯僖公五年至漢元帝初元二年六百餘年間，十二月朔旦冬至，相距皆七十六年，此最爲得實，又與魯世家註、皇甫謐所紀歲次皆合，蓋謂劉彝叟長曆也。且言「史記·六國表差謬，難可盡據」。又按通鑑目錄編年用劉彝叟長曆。漢武帝太初元年，初用夏正定曆，史記·曆書是年書閼逢攝提格，目錄書強圉赤奮若。閼逢攝提格，甲寅也，強圉赤奮若，丁丑也，有二十四年之差。溫公用彝叟曆，邵康節皇極經世書亦用彝叟曆。康節少自雄其才，旣學，力慕高遠，一見李之才，遂從而受學，廬於共城百源，冬不爐，夏不扇，夜不就席者數年，覃思於易經也。皇極經世書不能違彝叟曆。及其來居於洛，而溫公亦奉祠以書局在洛，相過從稔，又夙所敬者也。余意其講明之間必嘗及此，而決於用彝叟曆。讀考異此一段，辭意可見。", "textJt": "谥法：布德就义曰穆；中情见貌曰穆；尊贤敬让曰共；既过能改曰共；执事坚固曰共。共，读曰恭。考异曰：司马迁史记·六国表：周威烈王十九年甲戌，鲁穆公元年。烈王元年丙午，共公元年。显王十七年己巳，康公元年。二十六年戊寅，景公元年。赧王元年丁未，平公元年。二十年丙寅，文公元年。四十三年己丑，顷公元年。五十九年乙巳，周亡。秦庄襄王元年壬子，楚灭鲁。按鲁世家，穆公三十三年卒，若元甲戌，终乙巳，则是三十二年也。共公二十二年卒，若元丙午，终戊辰，则是二十三年也。康公九年卒，景公二十五年卒，平公二十二年卒，若元丁未，终乙丑，则是十九年也。文公二十三年卒，顷公二十四年楚灭鲁。班固汉书·律历志「文公」作「缗公」；其在位之年与世家异者，惟平公二十年耳。本志自鲁僖公五年正月辛亥朔旦冬至推之，至成公十二年正月庚寅朔旦冬至，定公七年正月己巳朔旦冬至，元公四年正月戊申朔旦冬至，康公四年正月丁亥朔旦冬至，缗公二十二年正月丙寅朔旦冬至，汉高祖八年十一月乙巳朔旦冬至，武帝元朔六年十一月甲申朔旦冬至，元帝初元二年十一月癸亥朔旦冬至，其间相距皆七十六年，此最为得实，又与鲁世家注、皇甫谧所纪岁次皆合，今从之。六国表差谬，难可尽据也。余按考异自鲁僖公五年至汉元帝初元二年六百余年间，十二月朔旦冬至，相距皆七十六年，此最为得实，又与鲁世家注、皇甫谧所纪岁次皆合，盖谓刘彝叟长历也。且言「史记·六国表差谬，难可尽据」。又按通鉴目录编年用刘彝叟长历。汉武帝太初元年，初用夏正定历，史记·历书是年书阏逢摄提格，目录书强圉赤奋若。阏逢摄提格，甲寅也，强圉赤奋若，丁丑也，有二十四年之差。温公用彝叟历，邵康节皇极经世书亦用彝叟历。康节少自雄其才，既学，力慕高远，一见李之才，遂从而受学，庐于共城百源，冬不炉，夏不扇，夜不就席者数年，覃思于易经也。皇极经世书不能违彝叟历。及其来居于洛，而温公亦奉祠以书局在洛，相过从稔，又夙所敬者也。余意其讲明之间必尝及此，而决于用彝叟历。读考异此一段，辞意可见。"}]','内政,鲁穆公,共公奋','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(86,'8c08f812-db0e-11ef-a582-a0d3651f611f',23,1,86,'韓文侯薨，子哀侯立。','韩文侯薨，子哀侯立。','韩文侯去世，他的儿子韩哀侯继位。',NULL,'韩文侯,哀侯','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c06768e-db0e-11ef-801a-a0d3651f611f',CURRENT_TIMESTAMP),
(87,'8c08f817-db0e-11ef-b315-a0d3651f611f',24,1,87,'王崩，子烈王喜立。','王崩，子烈王喜立。','周安王去世，他的儿子姬喜即位，是为周烈王。',NULL,'内政,烈王喜','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f815-db0e-11ef-83af-a0d3651f611f',CURRENT_TIMESTAMP),
(88,'8c08f819-db0e-11ef-9440-a0d3651f611f',24,1,88,'魏、韓、趙共廢晉靖公爲家人而分其地。','魏、韩、赵共废晋靖公为家人而分其地。','魏、韩、赵三国共同废黜晋靖公，把他降为平民，并瓜分了他的土地。','[{"type": "胡注", "text": "唐叔不祀矣。", "textJt": "唐叔不祀矣。"}]','权争,三家分晋,晋靖公,魏,韩,赵','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f815-db0e-11ef-83af-a0d3651f611f',CURRENT_TIMESTAMP),
(89,'8c08f826-db0e-11ef-8dc6-a0d3651f611f',25,1,89,'日有食之。','日有食之。','日食发生了。',NULL,NULL,'https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f824-db0e-11ef-b4c9-a0d3651f611f',CURRENT_TIMESTAMP),
(90,'8c08f827-db0e-11ef-8245-a0d3651f611f',25,1,90,'韓滅鄭，因徙都之。','韩灭郑，因徙都之。','韩国灭掉郑国，于是把国都迁到新郑。','[{"type": "胡注", "text": "韓本都平陽，其地屬漢之河東郡；中間徙都陽翟。鄭都新鄭，其地屬漢之河南郡。鄭桓公始封於鄭，其地屬漢之京兆；後滅虢、鄶而國於溱、洧之間，故曰新鄭，左傳鄭莊公所謂「吾先君新邑於此」是也。今韓旣滅鄭，自陽翟徙都之。韓旣都鄭，故時人亦謂韓王爲鄭王，考之戰國策、韓非子可見。", "textJt": "韩本都平阳，其地属汉之河东郡；中间徙都阳翟。郑都新郑，其地属汉之河南郡。郑桓公始封于郑，其地属汉之京兆；后灭虢、郐而国于溱、洧之间，故曰新郑，左传郑庄公所谓「吾先君新邑于此」是也。今韩既灭郑，自阳翟徙都之。韩既都郑，故时人亦谓韩王为郑王，考之战国策、韩非子可见。"}]','军事,韩灭郑之战,韩,郑','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f824-db0e-11ef-b4c9-a0d3651f611f',CURRENT_TIMESTAMP),
(91,'8c08f848-db0e-11ef-9e41-a0d3651f611f',25,1,91,'趙敬侯薨，子成侯種立。','赵敬侯薨，子成侯种立。','赵敬侯去世，其子赵成侯赵种即位。',NULL,'人事,赵敬侯,成侯,种','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f824-db0e-11ef-b4c9-a0d3651f611f',CURRENT_TIMESTAMP),
(92,'8c08f84f-db0e-11ef-bf21-a0d3651f611f',26,1,92,'燕敗齊師於林狐。','燕败齐师于林狐。','燕国在林狐击败齐国军队。',NULL,'军事,燕,齐,林狐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(93,'8c08f854-db0e-11ef-9d69-a0d3651f611f',26,1,93,'魯伐齊，入陽關。','鲁伐齐，入阳关。','鲁国讨伐齐国，军队进入阳关。','[{"type": "胡注", "text": "徐廣曰：陽關在鉅平。班志，鉅平縣屬泰山郡。括地志：陽關故城在兗州博城縣南二十九里，其城之西臨汶水。汶，音問。", "textJt": "徐广曰：阳关在巨平。班志，巨平县属泰山郡。括地志：阳关故城在兖州博城县南二十九里，其城之西临汶水。汶，音问。"}]','军事,鲁,齐,阳关','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(94,'8c08f865-db0e-11ef-a766-a0d3651f611f',26,1,94,'魏伐齊，至博陵。','魏伐齐，至博陵。','魏国进攻齐国，军队抵达博陵。','[{"type": "胡注", "text": "史記正義曰：博陵在濟州西界。宋白曰：史記，齊威王伐晉至博陵。徐廣曰：東郡之博平，漢爲縣。", "textJt": "史记正义曰：博陵在济州西界。宋白曰：史记，齐威王伐晋至博陵。徐广曰：东郡之博平，汉为县。"}]','军事,魏,齐,博陵','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(95,'8c08f876-db0e-11ef-ad2b-a0d3651f611f',26,1,95,'燕僖公薨，子桓公立。','燕僖公薨，子桓公立。','燕僖公去世，其子燕桓公即位。',NULL,'人事,燕僖公,桓公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(96,'8c08f879-db0e-11ef-add3-a0d3651f611f',26,1,96,'宋休公薨，子辟公立。','宋休公薨，子辟公立。','宋休公去世，其子宋辟公即位。','[{"type": "胡注", "text": "辟亦諡法之所不戴。", "textJt": "辟亦谥法之所不戴。"}]','内政,宋休公,辟公','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(97,'8c08f87e-db0e-11ef-9cf7-a0d3651f611f',26,1,97,'衞愼公薨，子聲公訓立。','衞愼公薨，子声公训立。','卫慎公去世，他的儿子卫声公姬训继位。','[{"type": "胡注", "text": "諡法：敏以敬曰愼。戴記：思慮深遠曰愼。", "textJt": "谥法：敏以敬曰愼。戴记：思虑深远曰愼。"}]','内政,衞愼公,声公,训','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f84d-db0e-11ef-bb96-a0d3651f611f',CURRENT_TIMESTAMP),
(98,'8c08f888-db0e-11ef-b9fe-a0d3651f611f',27,1,98,'趙伐衞，取都鄙七十三。','赵伐衞，取都鄙七十三。','赵国攻打卫国，夺取了七十三座城邑。','[{"type": "胡注", "text": "周禮：太宰以八則治都鄙。註云：都之所居曰鄙。都鄙，卿大夫之采邑。蓋周之制，四縣爲都，方四十里，一千六百井，積一萬四千四百夫；五酇爲鄙，鄙五百家也。此時衞國褊小，若都鄙七十三，以成周之制率之，其地廣矣，盡衞之提封，未必能及此數也。更俟博考。", "textJt": "周礼：太宰以八则治都鄙。注云：都之所居曰鄙。都鄙，卿大夫之采邑。盖周之制，四县为都，方四十里，一千六百井，积一万四千四百夫；五酂为鄙，鄙五百家也。此时衞国褊小，若都鄙七十三，以成周之制率之，其地广矣，尽衞之提封，未必能及此数也。更俟博考。"}]','军事,赵,衞','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f886-db0e-11ef-9d8d-a0d3651f611f',CURRENT_TIMESTAMP),
(99,'8c08f892-db0e-11ef-8195-a0d3651f611f',27,1,99,'魏敗趙師于北藺。','魏败赵师于北蔺。','魏国在北蔺击败了赵国军队。','[{"type": "胡注", "text": "班志，西河郡有藺縣。史記正義曰：在石州。其地於趙爲西北，故曰北藺。藺，離進翻。", "textJt": "班志，西河郡有蔺县。史记正义曰：在石州。其地于赵为西北，故曰北蔺。蔺，离进翻。"}]','军事,魏,赵,北蔺','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f886-db0e-11ef-9d8d-a0d3651f611f',CURRENT_TIMESTAMP),
(100,'8c08f8a1-db0e-11ef-922d-a0d3651f611f',28,1,100,'魏伐楚，取魯陽。','魏伐楚，取鲁阳。','魏国攻打楚国，夺取了鲁阳。','[{"type": "胡注", "text": "左傳所謂「劉累遷于魯縣」，卽魯陽也。班志，魯陽縣屬南陽郡。史記正義曰：今汝州魯山縣。", "textJt": "左传所谓「刘累迁于鲁县」，即鲁阳也。班志，鲁阳县属南阳郡。史记正义曰：今汝州鲁山县。"}]','军事,魏,楚,鲁阳','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f89f-db0e-11ef-a9b0-a0d3651f611f',CURRENT_TIMESTAMP),
(101,'8c0b1b1f-db0e-11ef-8c30-a0d3651f611f',28,1,101,'韓嚴遂弑哀侯，國人立其子懿侯。初，哀侯以韓廆爲相而愛嚴遂，二人甚相害也。嚴遂令人刺韓廆於朝，廆走哀侯，哀侯抱之；人刺韓廆，兼及哀侯。','韩严遂弑哀侯，国人立其子懿侯。初，哀侯以韩廆为相而爱严遂，二人甚相害也。严遂令人刺韩廆于朝，廆走哀侯，哀侯抱之；人刺韩廆，兼及哀侯。','韩国严遂杀死韩哀侯，国人拥立他的儿子韩懿侯为国君。当初，韩哀侯任命韩廆为相，又很宠信严遂，两人互相忌恨很深。严遂派人在朝堂上刺杀韩廆，韩廆逃到哀侯身旁，哀侯抱住他；刺客刺杀韩廆时，连带将哀侯一并刺死。','[{"type": "胡注", "text": "戰國策以聶政刺韓相事及幷中哀侯爲一事；此從史記。蜀本註曰：按太史公年表及韓世家，於韓烈侯三年皆書「聶政殺韓相俠累」，於哀侯六年又皆書「嚴遂弑哀侯」。以刺客傳考之，聶政殺俠累事在哀侯時；以戰國策考之亦然。從傳與戰國策，則是年表、世家於烈侯三年書「盜殺俠累」誤矣。通鑑於烈侯三年載聶政殺俠累事，又於哀侯六年載嚴遂殺其君哀侯，是從年表、世家所書。蓋刺客傳初不言倂殺哀侯，止戰國策言之，通鑑豈以此疑之歟！故載倂刺哀侯，不書聶政，止曰「使人」。以此求之，則通鑑之意不以嚴仲子爲嚴遂，亦不以俠累爲韓廆，止從年表、世家而不信其傳也。余按溫公與劉道原書，亦疑此事。廆，戶賄翻。相，息亮翻。刺，七亦翻。朝，直遙翻。走，音奏。", "textJt": "战国策以聂政刺韩相事及幷中哀侯为一事；此从史记。蜀本注曰：按太史公年表及韩世家，于韩烈侯三年皆书「聂政杀韩相侠累」，于哀侯六年又皆书「严遂弑哀侯」。以刺客传考之，聂政杀侠累事在哀侯时；以战国策考之亦然。从传与战国策，则是年表、世家于烈侯三年书「盗杀侠累」误矣。通鉴于烈侯三年载聂政杀侠累事，又于哀侯六年载严遂杀其君哀侯，是从年表、世家所书。盖刺客传初不言倂杀哀侯，止战国策言之，通鉴岂以此疑之欤！故载倂刺哀侯，不书聂政，止曰「使人」。以此求之，则通鉴之意不以严仲子为严遂，亦不以侠累为韩廆，止从年表、世家而不信其传也。余按温公与刘道原书，亦疑此事。廆，户贿翻。相，息亮翻。刺，七亦翻。朝，直遥翻。走，音奏。"}]','权争,严遂,哀侯,懿侯,韩廆,廆,韩,相','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f89f-db0e-11ef-a9b0-a0d3651f611f',CURRENT_TIMESTAMP),
(102,'8c0b1b63-db0e-11ef-8202-a0d3651f611f',28,1,102,'魏武侯薨，不立太子，子罃與公中緩爭立，國內亂。','魏武侯薨，不立太子，子䓨与公中缓争立，国内乱。','魏武侯去世，因为没有立太子，他的儿子魏罃与公中缓争夺国君之位，国内发生动乱。',NULL,'权争,浊泽之战,魏武侯,䓨,公中缓','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c08f89f-db0e-11ef-a9b0-a0d3651f611f',CURRENT_TIMESTAMP),
(103,'8c0b1b6a-db0e-11ef-bd8a-a0d3651f611f',29,1,103,'齊威王來朝。是時周室微弱，諸侯莫朝，而齊獨朝之，天下以此益賢威王。','齐威王来朝。是时周室微弱，诸侯莫朝，而齐独朝之，天下以此益贤威王。','齐威王前来朝见周烈王。当时周王室已很衰弱，诸侯没有谁前来朝见，唯有齐国独自前来朝见，天下人因此更加认为齐威王贤德。',NULL,'外交,齐威王,威王,周室,齐','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(104,'8c0b1b70-db0e-11ef-9e27-a0d3651f611f',29,1,104,'趙伐齊，至鄄。','赵伐齐，至鄄。','赵国攻打齐国，进军至鄄地。','[{"type": "胡注", "text": "班志，濟陰郡有鄄城縣。鄄，工掾翻。", "textJt": "班志，济阴郡有鄄城县。鄄，工掾翻。"}]','军事,赵,齐,鄄','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(105,'8c0b1b79-db0e-11ef-abe3-a0d3651f611f',29,1,105,'魏敗趙師于懷。','魏败赵师于怀。','魏国在怀地击败了赵国军队。','[{"type": "胡注", "text": "班志，河內郡有懷縣。魏收地形志，懷州武德郡有懷縣，縣管內有懷城。敗，補邁翻。", "textJt": "班志，河内郡有怀县。魏收地形志，怀州武德郡有怀县，县管内有怀城。败，补迈翻。"}]','军事,魏,赵,怀','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(106,'8c0b1b88-db0e-11ef-9be2-a0d3651f611f',29,1,106,'齊威王召卽墨大夫，語之曰：「自子之居卽墨也，毀言日至。然吾使人視卽墨，田野辟，人民給，官無事，東方以寧；是子不事吾左右以求助也！」封之萬家。召阿大夫，語之曰：「自子守阿，譽言日至。吾使人視阿，田野不辟，人民貧餒。昔日趙攻鄄，子不救；衞取薛陵，子不知；是子厚幣事吾左右以求譽也！」是日，烹阿大夫及左右嘗譽者。於是羣臣聳懼，莫敢飾詐，務盡其情，齊國大治，強於天下。','齐威王召即墨大夫，语之曰：「自子之居即墨也，毁言日至。然吾使人视即墨，田野辟，人民给，官无事，东方以宁；是子不事吾左右以求助也！」封之万家。召阿大夫，语之曰：「自子守阿，誉言日至。吾使人视阿，田野不辟，人民贫馁。昔日赵攻鄄，子不救；衞取薛陵，子不知；是子厚币事吾左右以求誉也！」是日，烹阿大夫及左右尝誉者。于是群臣耸惧，莫敢饰诈，务尽其情，齐国大治，强于天下。','齐威王召见即墨大夫，对他说：“自从你到即墨任职以来，诋毁你的话每天都有。然而我派人到即墨察看，田地开辟得很好，百姓生活充足，官府清静无事，东方因而安宁；这是你不肯侍奉我身边的近臣、请他们帮助说好话啊！”于是封给他一万户的食邑。齐威王又召见阿地大夫，对他说：“自从你镇守阿地以来，赞誉你的话每天都有。我派人到阿地察看，田地没有开辟，百姓贫困饥饿。从前赵国攻打鄄地，你不去救援；卫国夺取薛陵，你竟不知道；这是你用重礼贿赂我身边的近臣、向他们求取称誉啊！”当天，齐威王烹杀了阿地大夫以及身边那些曾为他称誉的人。从此群臣震惊恐惧，没有人再敢掩饰欺诈，都尽力说出实情，齐国因此大治，强于天下。','[{"type": "胡注", "text": "班志，卽墨縣屬膠東國。括地志：卽墨故城，在萊州膠水縣南六十里。宋白曰：城臨墨水，故曰卽墨。語，牛倨翻，下同。", "textJt": "班志，即墨县属胶东国。括地志：即墨故城，在莱州胶水县南六十里。宋白曰：城临墨水，故曰即墨。语，牛倨翻，下同。"}, {"type": "胡注", "text": "辟，讀曰闢；下同。", "textJt": "辟，读曰辟；下同。"}, {"type": "胡注", "text": "阿，卽東阿縣；班志屬東郡。譽，音余，稱其美也。", "textJt": "阿，即东阿县；班志属东郡。誉，音余，称其美也。"}, {"type": "胡注", "text": "薛陵，春秋薛國之墟也。班志，薛縣屬魯國，而衞國在漢東郡陳留界。薛陵屬齊而近於衞，故爲所取。齊後封田嬰於此。", "textJt": "薛陵，春秋薛国之墟也。班志，薛县属鲁国，而衞国在汉东郡陈留界。薛陵属齐而近于衞，故为所取。齐后封田婴于此。"}]','内政,人事,齐威王,即墨,阿,赵,鄄,衞,薛陵,齐国,卽墨大夫,阿大夫','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(107,'8c0b1bbb-db0e-11ef-b293-a0d3651f611f',29,1,107,'楚肅王薨，無子，立其弟良夫，是爲宣王。','楚肃王薨，无子，立其弟良夫，是为宣王。','楚肃王去世，没有儿子，于是立他的弟弟良夫为楚王，这就是楚宣王。',NULL,'内政,楚肃王,良夫,宣王','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(108,'8c0b1bbf-db0e-11ef-9990-a0d3651f611f',29,1,108,'宋辟公薨，子剔成立。','宋辟公薨，子剔成立。','宋辟公去世，其子剔成即位。',NULL,'内政,宋辟公,剔成','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1b68-db0e-11ef-bf33-a0d3651f611f',CURRENT_TIMESTAMP),
(109,'8c0b1bc5-db0e-11ef-82fe-a0d3651f611f',30,1,109,'日有食之。','日有食之。','发生了日食。',NULL,NULL,'https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1bc3-db0e-11ef-a7d0-a0d3651f611f',CURRENT_TIMESTAMP),
(110,'8c0d7c27-db0e-11ef-8d3f-a0d3651f611f',30,1,110,'王崩，弟扁立，是爲顯王。','王崩，弟扁立，是为显王。','周烈王驾崩，他的弟弟姬扁即位，是为周显王。','[{"type": "胡注", "text": "據班書·古今人表師古註：扁，音篇。", "textJt": "据班书·古今人表师古注：扁，音篇。"}]','内政,扁,显王','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1bc3-db0e-11ef-a7d0-a0d3651f611f',CURRENT_TIMESTAMP),
(111,'8c0d8feb-db0e-11ef-9580-a0d3651f611f',30,1,111,'魏大夫王錯出奔韓。公孫頎謂韓懿侯曰：「魏亂，可取也。」懿侯乃與趙成侯合兵伐魏，戰于濁澤，大破之，遂圍魏。成侯曰：「殺罃，立公中緩，割地而退，我二國之利也。」懿侯曰：「不可。殺魏君，暴也；割地而退，貪也。不如兩分之。魏分爲兩，不強於宋、衞，則我終無魏患矣。」趙人不聽。懿侯不悅，以其兵夜去。趙成侯亦去。罃遂殺公中緩而立，是爲惠王。','魏大夫王错出奔韩。公孙颀谓韩懿侯曰：「魏乱，可取也。」懿侯乃与赵成侯合兵伐魏，战于浊泽，大破之，遂围魏。成侯曰：「杀䓨，立公中缓，割地而退，我二国之利也。」懿侯曰：「不可。杀魏君，暴也；割地而退，贪也。不如两分之。魏分为两，不强于宋、衞，则我终无魏患矣。」赵人不听。懿侯不悦，以其兵夜去。赵成侯亦去。䓨遂杀公中缓而立，是为惠王。','魏国大夫王错出逃到韩国。公孙颀对韩懿侯说：“魏国混乱，可以攻取。”韩懿侯便与赵成侯合兵攻打魏国，在浊泽交战，大败魏军，随后包围了魏国都城。赵成侯说：“杀掉魏罃，改立公中缓，让魏国割地后退兵，这对我们两国都有利。”韩懿侯说：“不行。杀掉魏国国君，是暴虐；割地后退兵，是贪婪。不如让魏国一分为二。魏国分成两国后，国力就不会强于宋国、卫国，我们便永远不会再有魏国的祸患了。”赵成侯不肯听从。韩懿侯很不高兴，当夜率领自己的军队撤走。赵成侯也撤兵离去。魏罃于是杀死公中缓，自立为国君，这就是魏惠王。','[{"type": "胡注", "text": "姓譜：王氏之所自出非一。出太原、琅邪者，周靈王太子晉之後。北海、陳留，齊王田和之後。東海出自姬姓。高平、京兆，魏信陵君之後。天水、東平、新蔡、新野、山陽、中山、章武、東萊、河東者，殷王子比干爲紂所害，子孫以王者之後，號曰王氏。余謂此皆後世以諸郡著姓言之耳。春秋之時自有王姓，莫能審其所自出。", "textJt": "姓谱：王氏之所自出非一。出太原、琅邪者，周灵王太子晋之后。北海、陈留，齐王田和之后。东海出自姬姓。高平、京兆，魏信陵君之后。天水、东平、新蔡、新野、山阳、中山、章武、东莱、河东者，殷王子比干为纣所害，子孙以王者之后，号曰王氏。余谓此皆后世以诸郡著姓言之耳。春秋之时自有王姓，莫能审其所自出。"}, {"type": "胡注", "text": "公孫，姓也。黃帝，公孫氏。頎，渠希翻。", "textJt": "公孙，姓也。黄帝，公孙氏。颀，渠希翻。"}, {"type": "胡注", "text": "史記正義曰：徐廣以爲長社濁澤，非也。括地志云：濁水源出蒲州解縣東北平地，爾時魏都安邑，韓、趙伐魏，豈至河南長社邪！解縣濁水近於魏都，當是也。", "textJt": "史记正义曰：徐广以为长社浊泽，非也。括地志云：浊水源出蒲州解县东北平地，尔时魏都安邑，韩、赵伐魏，岂至河南长社邪！解县浊水近于魏都，当是也。"}]','军事,权争,浊泽之战,王错,公孙颀,韩懿侯,懿侯,赵成侯,成侯,䓨,公中缓,惠王,魏,韩,浊泽,宋,衞,赵,大夫','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1bc3-db0e-11ef-a7d0-a0d3651f611f',CURRENT_TIMESTAMP),
(112,'8c0d903e-db0e-11ef-854a-a0d3651f611f',30,1,112,'太史公曰：魏惠王所以身不死、國不分者，二國之謀不和也。若從一家之謀，魏必分矣。故曰：「君終，無適子，其國可破也。」','太史公曰：魏惠王所以身不死、国不分者，二国之谋不和也。若从一家之谋，魏必分矣。故曰：「君终，无适子，其国可破也。」','太史公司马迁说：魏惠王之所以自身不死、国家没有被瓜分，是因为韩、赵两国的计策不一致。如果采纳其中任何一国的计策，魏国必定被瓜分。所以说：“国君去世而没有嫡子，他的国家就可以被攻破。”','[{"type": "胡注", "text": "索隱曰：蓋古人之言及俗說，故云「故曰」。適，讀曰嫡。", "textJt": "索隐曰：盖古人之言及俗说，故云「故曰」。适，读曰嫡。"}]','史论,浊泽之战,太史公,魏惠王,魏','https://www.dutongjian.com/api/reign?reign_tongjian_id=8c0b1bc3-db0e-11ef-a7d0-a0d3651f611f',CURRENT_TIMESTAMP)
) AS V(CONTENT_ID,TONGJIAN_ID,REIGN_ID,VOLUME_ID,NUMBER,ORIGINAL,SIMPLIFIED,TRANSLATION,NOTES,TAGS,SOURCE_URL,CREATE_TIME)
WHERE NOT EXISTS (SELECT 1 FROM "TJ_CONTENT" S WHERE S.TONGJIAN_ID = V.TONGJIAN_ID);

